  IF (CASE WHEN app_mode THEN application_native_source_scope_allowed(w,dependency.resource_kind,dependency.resource_id,
   jsonb_build_object('workspaceId',w,'userId',dependency.user_id,'assistantId',dependency.assistant_id,'sensitivity',dependency.sensitivity,
   'compartments',dependency.compartments,'projectIds',dependency.project_ids),'{}',CASE WHEN writing AND application_native_same_destination(w,k,i,dependency.resource_kind,dependency.resource_id) THEN 'patch' ELSE 'read' END) ELSE application_reader_envelope_visible(w,jsonb_build_object('workspaceId',w,
   'userId',dependency.user_id,'assistantId',dependency.assistant_id,'sensitivity',dependency.sensitivity,
   'compartments',dependency.compartments,'projectIds',dependency.project_ids)) END) IS NOT TRUE THEN RETURN false;END IF;
 END LOOP;
 IF app_mode THEN
  FOR dependency IN SELECT DISTINCT s.source_kind,s.source_id FROM scope_derivation_sources s JOIN scope_derivations d
   ON d.workspace_id=s.workspace_id AND d.id=s.derivation_id JOIN jsonb_array_elements(nodes) ancestor(value)
   ON d.resource_kind=ancestor.value->>'kind' AND d.resource_id=(ancestor.value->>'id')::uuid
   WHERE d.workspace_id=w AND (scope_source_table(s.source_kind) IS NOT NULL OR s.source_kind='entity_instance') LOOP
    current:=read_scope_source(w,dependency.source_kind,dependency.source_id);
    IF application_native_source_scope_allowed(w,dependency.source_kind,dependency.source_id,current,
      application_native_source_fields(w,dependency.source_kind,dependency.source_id)) IS NOT TRUE THEN RETURN false;END IF;
  END LOOP;
 END IF;
 FOR dependency IN SELECT DISTINCT s.source_id FROM scope_derivation_sources s JOIN scope_derivations d
  ON d.workspace_id=s.workspace_id AND d.id=s.derivation_id JOIN jsonb_array_elements(nodes) ancestor(value)
  ON d.resource_kind=ancestor.value->>'kind' AND d.resource_id=(ancestor.value->>'id')::uuid
  WHERE d.workspace_id=w AND s.source_kind='entity' LOOP
  SELECT e.kind INTO type_key FROM entities e WHERE e.workspace_id=w AND e.id=dependency.source_id;
  IF NOT FOUND OR type_key NOT IN('company','person','deal') THEN CONTINUE;END IF;
  IF app_mode THEN
   current:=read_scope_source(w,'entity',dependency.source_id);
   IF application_native_source_scope_allowed(w,'entity',dependency.source_id,current,application_native_source_fields(w,'entity',dependency.source_id)) IS NOT TRUE THEN RETURN false;END IF;
   CONTINUE;
  END IF;
  policy:=application_native_field_contract_for(w,'{"kind":"native","moduleKey":"native"}',type_key,dependency.source_id::text);
  IF policy->>'registered' IS DISTINCT FROM 'false' THEN
   mask:=application_current_native_field_policy(w,'{"kind":"native","moduleKey":"native"}',type_key,dependency.source_id);
   IF policy->>'registered' IS DISTINCT FROM 'true' OR policy->>'held' IS DISTINCT FROM 'false'
    OR mask->>'held' IS DISTINCT FROM 'false' OR NOT coalesce(policy#>'{metadata,fieldKeys}'<@(mask->'readFields'),false) THEN RETURN false;END IF;
  END IF;
 END LOOP;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR insufficient_privilege THEN RETURN false;
END

DECLARE result jsonb;
BEGIN
 IF p_origin<>'{"kind":"native","moduleKey":"native"}'::jsonb OR p_type NOT IN('session_message','session_message_annotation') THEN
  RETURN application_compute_field_envelope_before_session_eval(w,p_origin,p_type,p_id,p_selection,p_selected_version,p_fields,depth);END IF;
 IF depth NOT BETWEEN 0 AND 2 OR p_selection='query_domain' AND depth>1 OR p_selected_version IS NOT NULL THEN RETURN NULL;END IF;
 result:=application_session_eval_envelope(w,p_type,p_id,p_selection,p_fields,'{}');RETURN result->'value';
END

DECLARE state jsonb; field_keys text[]; identity text; resource uuid; scope jsonb; version text;
 reference jsonb; child jsonb; children jsonb:='[]'; sources jsonb:='[]'; native_source jsonb; external record;
BEGIN
 IF depth NOT BETWEEN 0 AND 2 THEN RETURN NULL; END IF;
 IF p_origin->>'kind'='generic' THEN p_type:='record.'||(p_origin->>'entityTypeId')::uuid; END IF;
 field_keys:=ARRAY(SELECT DISTINCT field FROM unnest(p_fields) field ORDER BY field);
 IF p_fields IS NULL OR cardinality(field_keys) IS DISTINCT FROM cardinality(p_fields) THEN RETURN NULL; END IF;
 state:=application_field_projection_state(w,p_origin,p_type,p_id,p_selection,p_selected_version,field_keys);
 IF state IS NULL THEN RETURN NULL; END IF;
 scope:=jsonb_build_object('workspaceId',w,'userId',state#>'{source,userId}','assistantId',state#>'{source,assistantId}',
  'sensitivity',state#>'{source,sensitivity}','compartments',state#>'{source,compartments}','projectIds',state#>'{source,projectIds}');
 IF entity_derivation_envelope_valid(scope) IS NOT TRUE THEN RETURN NULL; END IF;
 identity:=application_field_digest(jsonb_build_object('workspaceId',w,'origin',p_origin,'typeKey',p_type,'id',p_id,
  'selection',p_selection,'selectedVersion',p_selected_version,'fields',field_keys,'fieldIdentity',state->'fieldIdentity'));
 resource:=application_field_resource_uuid(identity);
 FOR reference IN SELECT value FROM jsonb_array_elements(state->'references') ORDER BY value::text LOOP
  child:=application_compute_field_envelope(w,reference->'origin',reference->>'typeKey',(reference->>'id')::uuid,
   'identity',NULL,ARRAY(SELECT jsonb_array_elements_text(reference->'fields')),depth+1);
  IF child IS NULL THEN RETURN NULL; END IF;
  children:=children||jsonb_build_array(child);
  sources:=sources||jsonb_build_array(child->'source')||coalesce(child->'sources','[]'::jsonb);
  IF jsonb_array_length(sources)>=4096 THEN RETURN NULL; END IF;
 END LOOP;
 -- Preserve immutable external obligations independently of later native cleanup.
 -- This discovery is metadata only. Capture and every payload boundary must pin
 -- actual current source receipts; metadata discovery is never authorization.
 FOR external IN SELECT * FROM read_external_source_dependencies(w,ARRAY[state->>'sourceKind'],ARRAY[(state->>'sourceId')::uuid],ARRAY[state->>'sourceVersion']) LOOP
  IF external.source IS NULL OR external.source->>'workspaceId' IS DISTINCT FROM w::text
   OR external.node_version IS DISTINCT FROM external.source->>'version' THEN RETURN NULL; END IF;
  sources:=sources||jsonb_build_array(external.source);
  IF jsonb_array_length(sources)>=4096 THEN RETURN NULL; END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(value ORDER BY value::text),'[]') INTO sources
  FROM (SELECT DISTINCT value FROM jsonb_array_elements(sources)) unique_sources;
 version:=application_field_digest(jsonb_build_object('resourceId',resource,'recordVersion',state->'recordVersion',
  'sourceVersion',state->'sourceVersion','policyVersion',state->'policyVersion','scope',scope,'sources',sources));
 RETURN jsonb_build_object('resourceId',resource,'identity',identity,'origin',p_origin,'typeKey',p_type,'id',p_id,
  'selection',p_selection,'selectedVersion',p_selected_version,'fields',field_keys,'fieldIdentity',state->'fieldIdentity',
  'state',state,'children',children,'sources',sources,
  'source',scope||jsonb_build_object('resourceKind','application_field','resourceId',resource,'version',version));
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR numeric_value_out_of_range THEN RETURN NULL;
END

BEGIN
 IF p_origin->>'kind'='generic' THEN
  IF p_origin-ARRAY['kind','entityTypeId']<>'{}'::jsonb THEN RETURN NULL; END IF;
  p_origin:=jsonb_build_object('kind','generic','entityTypeId',((p_origin->>'entityTypeId')::uuid)::text);
  p_type:='record.'||(p_origin->>'entityTypeId');
 END IF;
 RETURN application_compute_field_envelope_before_module_policy(w,p_origin,p_type,p_id,p_selection,p_selected_version,p_fields,depth);
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value THEN RETURN NULL;
END

DECLARE envelope jsonb; point jsonb; child jsonb; children jsonb; sources jsonb; scope jsonb; version_value text;
BEGIN
 envelope:=public.application_compute_field_envelope_before_query_points(w,p_origin,p_type,p_id,p_selection,p_selected_version,p_fields,depth);
 IF envelope IS NULL OR envelope#>'{state,queryPoints}' IS NULL THEN RETURN envelope; END IF;
 IF depth NOT BETWEEN 0 AND 1 OR p_selection IS DISTINCT FROM 'query_domain' THEN RETURN NULL; END IF;
 children:=envelope->'children';sources:=envelope->'sources';
 FOR point IN SELECT value FROM jsonb_array_elements(envelope#>'{state,queryPoints}') LOOP
  IF jsonb_typeof(point) IS DISTINCT FROM 'object' OR NOT point ?& ARRAY['id','version','fields','source']
   OR point-ARRAY['id','version','fields','source']<>'{}'::jsonb OR jsonb_typeof(point->'fields') IS DISTINCT FROM 'array'
   OR jsonb_array_length(point->'fields')>128 OR point#>>'{source,workspaceId}' IS DISTINCT FROM w::text THEN RETURN NULL; END IF;
  child:=public.application_compute_field_envelope(w,p_origin,p_type,(point->>'id')::uuid,'query',NULL,
   ARRAY(SELECT jsonb_array_elements_text(point->'fields')),depth+1);
  IF child IS NULL OR child#>>'{state,recordVersion}' IS DISTINCT FROM point->>'version' OR child->'source' IS DISTINCT FROM point->'source' THEN RETURN NULL; END IF;
  children:=children||jsonb_build_array(child);sources:=sources||jsonb_build_array(child->'source')||coalesce(child->'sources','[]'::jsonb);
  IF jsonb_array_length(sources)>4096 OR jsonb_array_length(children)>4096 THEN RETURN NULL; END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(value ORDER BY value::text),'[]') INTO sources FROM (SELECT DISTINCT value FROM jsonb_array_elements(sources)) unique_sources;
 scope:=(envelope->'source')-ARRAY['resourceKind','resourceId','version'];
 version_value:=public.application_field_digest(jsonb_build_object('resourceId',envelope->'resourceId','recordVersion',envelope#>'{state,recordVersion}',
  'sourceVersion',envelope#>'{state,sourceVersion}','policyVersion',envelope#>'{state,policyVersion}','scope',scope,'sources',sources));
 RETURN envelope||jsonb_build_object('children',children,'sources',sources,'source',(envelope->'source')||jsonb_build_object('version',version_value));
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR numeric_value_out_of_range THEN RETURN NULL;
END

DECLARE resource application_field_resources; current jsonb;
BEGIN
 SELECT * INTO resource FROM application_field_resources f WHERE f.workspace_id=w AND f.id=i;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF scope_review_state_held('application_field',i) THEN RETURN '{"held":true}'::jsonb; END IF;
 current:=application_compute_field_envelope(w,resource.origin,resource.type_key,resource.resource_id,
  resource.selection,resource.selected_version,resource.fields);
 IF current IS NULL OR current->>'resourceId' IS DISTINCT FROM i::text
  OR current->>'identity' IS DISTINCT FROM resource.identity THEN RETURN '{"held":true}'::jsonb; END IF;
 RETURN current->'source'||jsonb_build_object('held',false,'validTo',NULL,'retractedAt',NULL);
END

DECLARE entry record;capture jsonb;current_source jsonb;lineage jsonb;
BEGIN
 IF NOT memo ? 'emptyQueries' THEN RETURN true;END IF;
 IF application_empty_query_helpers_current() IS NOT TRUE OR jsonb_typeof(memo->'emptyQueries') IS DISTINCT FROM 'object'
  OR (SELECT count(*) FROM jsonb_object_keys(memo-'memoryStatement'-'emptyQueries'))
    +(SELECT count(*) FROM jsonb_object_keys(memo->'emptyQueries'))>4096 THEN RETURN false;END IF;
 FOR entry IN SELECT key,value FROM jsonb_each(memo->'emptyQueries') LOOP
  IF entry.value->>'workspaceId' IS DISTINCT FROM w::text
   OR entry.value->>'actor' IS DISTINCT FROM current_setting('app.current_user_id',true) THEN RETURN false;END IF;
  current_source:=application_recorded_field_state_before_session_eval(w,(entry.value->>'id')::uuid,entry.value->>'version',0);
  IF current_source IS NULL OR current_source->>'held' IS DISTINCT FROM 'false'
   OR current_source IS DISTINCT FROM entry.value->'state' THEN RETURN false;END IF;
  capture:=application_recorded_field_root_capture(w,(entry.value->>'id')::uuid,entry.value->>'version',0);
  IF capture IS DISTINCT FROM entry.value->'capture' THEN RETURN false;END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),'[]') INTO lineage
   FROM application_scope_lineage(w,ARRAY['application_field'],ARRAY[(entry.value->>'id')::uuid],ARRAY[entry.value->>'version']) n;
  IF lineage IS DISTINCT FROM entry.value->'lineage' THEN RETURN false;END IF;
 END LOOP;
 RETURN true;
END

DECLARE root record;selected jsonb;recomputed jsonb;result jsonb;memo jsonb:='{}';actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
 direct_kinds text[];direct_ids uuid[];direct_versions text[];direct_position integer;history_shape boolean;
BEGIN

 IF envelope IS NULL THEN RETURN false;END IF;
 IF application_empty_query_helpers_current() IS TRUE
  AND envelope->'origin'='{"kind":"native","moduleKey":"native"}'::jsonb
  AND envelope->>'typeKey' IN('session_message','session_message_annotation') AND envelope->>'selection'='query_domain'
  AND envelope->>'selectedVersion' IS NULL AND envelope#>>'{state,sourceKind}'='application_query_domain'
  AND NOT EXISTS(WITH RECURSIVE envelopes(value) AS(
   SELECT envelope UNION ALL SELECT child.value FROM envelopes e CROSS JOIN LATERAL jsonb_array_elements(e.value->'children') child(value))
   SELECT 1 FROM envelopes WHERE value<>envelope AND (
    value->'origin'='{"kind":"native","moduleKey":"native"}'::jsonb
    AND value->>'typeKey' IN('session_message','session_message_annotation') AND value->>'selection' IN('read','query','identity')
    AND value->>'selectedVersion' IS NULL AND value#>>'{state,sourceKind}' IN('session_message','session_context_revision')
    AND pg_input_is_valid(value#>>'{state,sourceId}','uuid') AND value#>>'{state,sourceVersion}' IS NOT NULL) IS NOT TRUE) THEN
  WITH RECURSIVE envelopes(value) AS(
   SELECT envelope UNION ALL SELECT child.value FROM envelopes e CROSS JOIN LATERAL jsonb_array_elements(e.value->'children') child(value))
  SELECT array_agg(value#>>'{state,sourceKind}'),array_agg((value#>>'{state,sourceId}')::uuid),array_agg(value#>>'{state,sourceVersion}')
   INTO direct_kinds,direct_ids,direct_versions FROM envelopes WHERE value<>envelope;
  IF cardinality(direct_ids) BETWEEN 1 AND 100 THEN
   result:=read_native_empty_query_session_evidence(w,direct_kinds,direct_ids,direct_versions,true);
   IF result IS NOT NULL THEN RETURN result->>'admitted'='true';END IF;
  END IF;
 END IF;
 FOR selected IN WITH RECURSIVE envelopes(value) AS (
  SELECT envelope UNION ALL SELECT child.value FROM envelopes e CROSS JOIN LATERAL jsonb_array_elements(e.value->'children') child(value)

 ) SELECT value FROM envelopes LOOP
  IF application_empty_query_helpers_current() IS TRUE
   AND selected->'origin'='{"kind":"native","moduleKey":"native"}'::jsonb
   AND selected->>'typeKey' IN('session_message','session_message_annotation')
   AND selected->>'selection' IN('read','query','identity') AND selected->>'selectedVersion' IS NULL
   AND selected#>>'{state,sourceKind}' IN('session_message','session_context_revision')
   AND pg_input_is_valid(selected#>>'{state,sourceId}','uuid') AND selected#>>'{state,sourceVersion}' IS NOT NULL THEN
   result:=read_native_empty_query_session_evidence(w,ARRAY[selected#>>'{state,sourceKind}'],
    ARRAY[(selected#>>'{state,sourceId}')::uuid],ARRAY[selected#>>'{state,sourceVersion}'],true);
   IF result IS NOT NULL THEN
    IF result->>'admitted' IS DISTINCT FROM 'true' THEN RETURN false;END IF;
    CONTINUE;
   END IF;
  END IF;
  IF selected->'origin'='{"kind":"native","moduleKey":"native"}'::jsonb AND selected->>'typeKey'='memory' AND selected->>'selection'='history' THEN
   IF application_canonical_ancestry_from_admitted_root(w,'memory',(selected->>'id')::uuid,selected->>'selectedVersion',false,
    jsonb_build_object('kind','memory','id',selected->>'id','version',selected->>'selectedVersion','envelope',selected)) IS NOT TRUE THEN RETURN false;END IF;
  ELSIF selected->'origin'='{"kind":"native","moduleKey":"native"}'::jsonb AND selected->>'typeKey'='session_message'
   AND selected->>'selection' IN('read','query','identity') AND selected->>'selectedVersion' IS NULL
   AND selected#>>'{state,sourceKind}'='session_message' THEN
   history_shape:=false;
   IF actor IS NOT NULL AND EXISTS(SELECT 1 FROM workspace_members member WHERE member.workspace_id=w AND member.user_id=actor)
  AND nullif(current_setting('app.application_id',true),'') IS NULL
  AND nullif(current_setting('app.public_share_root',true),'') IS NULL
  AND NOT EXISTS(SELECT 1 FROM pg_roles login JOIN pg_class owned ON owned.oid='public.session_messages'::regclass WHERE login.rolname=session_user
    AND(login.rolsuper OR login.rolbypassrls OR pg_has_role(login.oid,owned.relowner,'USAGE'))) THEN

 SELECT array_agg(s.source_kind ORDER BY s.source_kind,s.source_id,s.source_version),
  array_agg(s.source_id ORDER BY s.source_kind,s.source_id,s.source_version),
  array_agg(s.source_version ORDER BY s.source_kind,s.source_id,s.source_version),
  count(*) BETWEEN 1 AND 100 AND bool_and(s.source_kind='application_field')
   AND bool_or(EXISTS(SELECT 1 FROM application_field_resources f WHERE f.workspace_id=w AND f.id=s.source_id
    AND f.origin='{"kind":"native","moduleKey":"native"}' AND f.type_key='memory' AND f.selection='history'))
 INTO direct_kinds,direct_ids,direct_versions,history_shape
 FROM session_messages message JOIN sessions session ON session.id=message.session_id AND session.workspace_id=message.workspace_id
 JOIN scope_derivations d ON d.workspace_id=message.workspace_id AND d.resource_kind='session_message'
  AND d.resource_id=message.id AND d.resource_version='1' AND d.user_id IS NOT DISTINCT FROM message.user_id
  AND d.assistant_id IS NOT DISTINCT FROM message.assistant_id AND d.sensitivity=message.sensitivity
  AND d.compartments=message.compartments AND d.project_ids=message.project_ids
 JOIN scope_derivation_sources s ON s.workspace_id=d.workspace_id AND s.derivation_id=d.id
 WHERE message.workspace_id=w AND message.id=(selected->>'id')::uuid AND message.scope_version=1 AND message.scope_held IS FALSE;
 IF history_shape IS TRUE THEN
  IF EXISTS(SELECT 1 FROM application_scope_lineage(w,direct_kinds,direct_ids,direct_versions) n
   WHERE n.kind='session_context_revision' OR n.kind='session_message' AND n.id=(selected->>'id')::uuid) THEN history_shape:=false;END IF;
  FOR direct_position IN 1..cardinality(direct_ids) LOOP
   IF NOT EXISTS(SELECT 1 FROM application_field_resources f WHERE f.workspace_id=w AND f.id=direct_ids[direct_position]
    AND f.origin='{"kind":"native","moduleKey":"native"}' AND f.type_key='memory' AND f.selection='history')
    AND EXISTS(SELECT 1 FROM application_scope_lineage(w,ARRAY[direct_kinds[direct_position]],ARRAY[direct_ids[direct_position]],ARRAY[direct_versions[direct_position]]) n
     JOIN application_field_resources f ON f.workspace_id=w AND f.id=n.id WHERE n.kind='application_field'
      AND f.origin='{"kind":"native","moduleKey":"native"}' AND f.type_key='memory' AND f.selection='history') THEN history_shape:=false;END IF;
  END LOOP;
 END IF;

   END IF;
   IF history_shape IS TRUE THEN
    result:=application_session_eval_envelope(w,'session_message',(selected->>'id')::uuid,
     selected->>'selection',ARRAY(SELECT jsonb_array_elements_text(selected->'fields')),memo);
    memo:=coalesce(result->'memo',memo);recomputed:=result->'value';
    IF recomputed IS NULL OR recomputed IS DISTINCT FROM selected THEN RETURN false;END IF;
   ELSE
    IF application_canonical_ancestry_allowed(w,selected#>>'{state,sourceKind}',(selected#>>'{state,sourceId}')::uuid,selected#>>'{state,sourceVersion}') IS NOT TRUE THEN RETURN false;END IF;
   END IF;
  ELSE
   IF scope_source_table(selected#>>'{state,sourceKind}') IS NOT NULL
    AND application_canonical_ancestry_allowed(w,selected#>>'{state,sourceKind}',(selected#>>'{state,sourceId}')::uuid,selected#>>'{state,sourceVersion}') IS NOT TRUE THEN RETURN false;END IF;
  END IF;
 END LOOP;
 RETURN true;
END

BEGIN
 IF p_origin='{"kind":"native","moduleKey":"native"}'::jsonb AND p_type='feedback_event' THEN
  IF p_selected_version IS NOT NULL THEN RETURN NULL;END IF;
  IF p_selection='query_domain' THEN RETURN application_feedback_outcome_domain_state(w,p_id,p_fields);END IF;
  IF p_selection NOT IN('read','query','identity') THEN RETURN NULL;END IF;
  RETURN application_feedback_field_state(w,p_id,p_fields);
 END IF;
 RETURN application_field_projection_state_before_feedback_outcome(w,p_origin,p_type,p_id,p_selection,p_selected_version,p_fields);
END

BEGIN
 IF p_origin='{"kind":"native","moduleKey":"native"}'::jsonb AND p_type='memory' AND p_selection='history' THEN
  RETURN application_memory_history_field_state(w,p_id,p_selected_version,p_fields);
 END IF;
 RETURN application_field_projection_state_before_memory_history(w,p_origin,p_type,p_id,p_selection,p_selected_version,p_fields);
END

BEGIN
 IF p_origin='{"kind":"native","moduleKey":"native"}'::jsonb AND p_type='memory' THEN
  IF p_selected_version IS NOT NULL THEN RETURN NULL;END IF;
  IF p_selection='query_domain' THEN RETURN application_memory_query_domain_state(w,p_id,p_fields);END IF;
  IF p_selection NOT IN('read','query','identity') THEN RETURN NULL;END IF;
  RETURN application_memory_field_state(w,p_id,p_fields);
 END IF;
 RETURN application_field_projection_state_before_memory_query(w,p_origin,p_type,p_id,p_selection,p_selected_version,p_fields);
END

BEGIN
 IF p_origin='{"kind":"native","moduleKey":"native"}'::jsonb AND p_type='knowledge_entry' AND p_selection='history' THEN
  IF p_selected_version IS NULL THEN RETURN NULL;END IF;RETURN knowledge_version_field_state(w,p_id,p_selected_version,p_fields);
 END IF;
 RETURN application_field_projection_state_before_knowledge_versions(w,p_origin,p_type,p_id,p_selection,p_selected_version,p_fields);
END

DECLARE child jsonb; source jsonb; resource application_field_resources; observation application_field_observations;
 resource_id_value uuid:=(envelope->>'resourceId')::uuid; v text:=envelope#>>'{source,version}'; field_keys text[];
BEGIN
 IF depth NOT BETWEEN 0 AND 2 OR envelope#>>'{source,workspaceId}' IS DISTINCT FROM w::text THEN
  RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023'; END IF;
 FOR child IN SELECT value FROM jsonb_array_elements(envelope->'children') ORDER BY value->>'resourceId' LOOP
  PERFORM application_materialize_field_envelope(w,child,depth+1);
 END LOOP;
 field_keys:=ARRAY(SELECT jsonb_array_elements_text(envelope->'fields'));
 INSERT INTO application_field_resources(id,workspace_id,origin,type_key,resource_id,selection,selected_version,fields,field_identity,identity)
  VALUES(resource_id_value,w,envelope->'origin',envelope->>'typeKey',(envelope->>'id')::uuid,envelope->>'selection',envelope->>'selectedVersion',
   field_keys,envelope->>'fieldIdentity',envelope->>'identity') ON CONFLICT DO NOTHING;
 SELECT * INTO resource FROM application_field_resources r WHERE r.workspace_id=w AND r.id=resource_id_value;
 IF NOT FOUND OR (resource.origin,resource.type_key,resource.resource_id,resource.selection,resource.selected_version,resource.fields,resource.field_identity,resource.identity)
  IS DISTINCT FROM (envelope->'origin',envelope->>'typeKey',(envelope->>'id')::uuid,envelope->>'selection',envelope->>'selectedVersion',field_keys,envelope->>'fieldIdentity',envelope->>'identity') THEN
  RAISE EXCEPTION 'scope_evidence_immutable' USING ERRCODE='22023'; END IF;
 source:=(envelope->'source')-ARRAY['resourceKind','resourceId','version'];
 INSERT INTO application_field_observations(workspace_id,resource_id,version,record_version,policy_version,source_kind,source_id,source_version,source_scope,owner_id)
  VALUES(w,resource_id_value,v,envelope#>>'{state,recordVersion}',envelope#>>'{state,policyVersion}',envelope#>>'{state,sourceKind}',
   (envelope#>>'{state,sourceId}')::uuid,envelope#>>'{state,sourceVersion}',source,(envelope#>>'{state,ownerId}')::uuid)
  ON CONFLICT DO NOTHING;
 SELECT * INTO observation FROM application_field_observations o WHERE o.workspace_id=w AND o.resource_id=resource_id_value AND o.version=v;
 IF NOT FOUND OR (observation.record_version,observation.policy_version,observation.source_kind,observation.source_id,observation.source_version,observation.source_scope,observation.owner_id)
  IS DISTINCT FROM (envelope#>>'{state,recordVersion}',envelope#>>'{state,policyVersion}',envelope#>>'{state,sourceKind}',
   (envelope#>>'{state,sourceId}')::uuid,envelope#>>'{state,sourceVersion}',source,(envelope#>>'{state,ownerId}')::uuid) THEN
  RAISE EXCEPTION 'scope_evidence_immutable' USING ERRCODE='22023'; END IF;
 FOR source IN SELECT value FROM jsonb_array_elements(envelope->'sources') ORDER BY value->>'resourceKind',value->>'resourceId',value->>'version' LOOP
  IF source->>'workspaceId' IS DISTINCT FROM w::text OR source->>'resourceKind' NOT IN('application_field','external_source') THEN
   RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023'; END IF;
  INSERT INTO application_field_observation_sources(workspace_id,resource_id,version,source_kind,source_id,source_version)
   VALUES(w,resource_id_value,v,source->>'resourceKind',(source->>'resourceId')::uuid,source->>'version') ON CONFLICT DO NOTHING;
 END LOOP;
 IF (SELECT count(*) FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=resource_id_value AND s.version=v)
  IS DISTINCT FROM jsonb_array_length(envelope->'sources') THEN RAISE EXCEPTION 'scope_evidence_immutable' USING ERRCODE='22023'; END IF;
END

BEGIN
 IF EXISTS(SELECT 1 FROM memories WHERE workspace_id=w AND id=i AND valid_to IS NOT NULL) THEN
  RETURN application_memory_historical_field_state(w,i,fields);
 END IF;
 RETURN application_memory_field_state_before_successor(w,i,fields);
END

DECLARE context jsonb;source jsonb;policy jsonb;mask jsonb;row_version text;values_json jsonb:='{}';field text;value jsonb;
BEGIN
 IF fields IS NULL OR NOT fields<@application_memory_field_keys() OR array_position(fields,NULL) IS NOT NULL
  OR cardinality(fields)<>(SELECT count(DISTINCT f) FROM unnest(fields) f) THEN RETURN NULL;END IF;
 context:=application_memory_query_context(w);
 IF context IS NULL OR NOT coalesce(to_jsonb(fields)<@(context->'read'),false) THEN RETURN NULL;END IF;
 SELECT scope_version::text INTO row_version FROM memories WHERE workspace_id=w AND id=i;
 IF NOT FOUND THEN RETURN NULL;END IF;
 -- Retained history without matching immutable current observations never becomes a native leaf.
 IF EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind='memory' AND d.resource_id=i)
  AND NOT EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind='memory' AND d.resource_id=i AND d.resource_version=row_version) THEN RETURN NULL;END IF;
 source:=read_admitted_native_scope_snapshot(w,'memory',i);
 IF source IS NULL OR source->>'held' IS DISTINCT FROM 'false' OR source->>'version' IS DISTINCT FROM row_version
  OR application_query_scope_admits_point(context->'bounds',source) IS NOT TRUE
  OR application_canonical_ancestry_allowed(w,'memory',i,row_version) IS NOT TRUE THEN RETURN NULL;END IF;
 policy:=application_native_field_contract_for(w,'{"kind":"native","moduleKey":"native"}','memory',i::text);
 IF policy->>'registered' IS DISTINCT FROM 'false' THEN
  IF policy->>'registered' IS DISTINCT FROM 'true' OR policy->>'held' IS DISTINCT FROM 'false'
   OR policy#>>'{metadata,recordVersion}' IS DISTINCT FROM row_version THEN RETURN NULL;END IF;
  mask:=read_native_application_field_mask(w,'{"kind":"native","moduleKey":"native"}','memory',i::text,row_version);
  IF mask IS NULL OR NOT coalesce(to_jsonb(fields)<@(mask->'readFields'),false) THEN RETURN NULL;END IF;
 END IF;
 -- Only the selected, already admitted fields are evaluated. No whole-row JSON before the mask.
 IF cardinality(fields)>0 THEN
  -- Identifiers come only from the validated selected field keys above.
  -- Each column is serialized individually after admission, never as a row.
  SELECT 'SELECT jsonb_build_object('||string_agg(format('%L,to_jsonb(%I)',selected,selected),',' ORDER BY ordinal)||
   ') FROM public.memories WHERE workspace_id=$1 AND id=$2 AND scope_version::text=$3'
   INTO field FROM unnest(fields) WITH ORDINALITY selection(selected,ordinal);
  EXECUTE field INTO values_json USING w,i,row_version;
 END IF;
 source:=jsonb_build_object('workspaceId',w,'userId',source->'userId','assistantId',source->'assistantId',
  'sensitivity',source->'sensitivity','compartments',source->'compartments','projectIds',source->'projectIds',
  'resourceKind','memory','resourceId',i,'version',row_version);
 RETURN jsonb_build_object('values',values_json,'source',source,'recordVersion',row_version,'sourceKind','memory','sourceId',i,'sourceVersion',row_version,'ownerId',NULL,
  'fieldIdentity',application_field_digest(jsonb_build_object('kind','memory-fields-v1','fields',fields)),
  'legacyPolicyVersion',application_field_digest(jsonb_build_object('kind','memory-fields-v1','catalog',context#>'{policy,fingerprint}','record',policy->'fingerprint','mask',mask)),
  'policyVersion',application_field_digest(jsonb_build_object('kind','memory-read-v2','catalog',context#>'{policy,fingerprint}','record',policy->'fingerprint','selectedRead',jsonb_build_object('fields',fields,'allowed',true))),
  'references','[]'::jsonb);
END

DECLARE candidate record;state jsonb;query_context jsonb;shared_context boolean:=false;count_value integer:=0;candidates jsonb:='[]';policies jsonb:='[]';excluded uuid[];
BEGIN
 IF fields IS NULL OR NOT fields<@application_memory_field_keys() OR application_query_scope_valid(bounds) IS NOT TRUE OR include_retained IS NULL THEN RETURN NULL;END IF;
 -- Keep unsupported profiles on the unchanged per-candidate canonical reader.
 -- An acquisition failure rolls back only these optional new locks. The old
 -- canonical source read may keep its original wait; this is not a no-wait RPC.
 BEGIN
  PERFORM id FROM workspaces WHERE id=w FOR SHARE NOWAIT;
  IF NOT FOUND THEN RAISE EXCEPTION 'native_memory_scan_context_unavailable' USING ERRCODE='55P03';END IF;
  PERFORM singleton FROM application_policy_contract_epoch WHERE singleton FOR SHARE NOWAIT;
  IF NOT FOUND THEN RAISE EXCEPTION 'native_memory_scan_context_unavailable' USING ERRCODE='55P03';END IF;
  PERFORM workspace_id FROM application_policy_workspace_epochs WHERE workspace_id=w FOR SHARE NOWAIT;
  IF NOT FOUND THEN RAISE EXCEPTION 'native_memory_scan_context_unavailable' USING ERRCODE='55P03';END IF;
  IF NOT EXISTS(SELECT 1 FROM pg_proc canonical_proc JOIN pg_proc candidate_proc
   ON candidate_proc.oid='public.application_memory_query_candidate_state(uuid,uuid,text[],jsonb)'::regprocedure
   WHERE canonical_proc.oid='public.application_memory_field_state_before_successor(uuid,uuid,text[])'::regprocedure
    AND array_length(string_to_array(canonical_proc.prosrc,'context:=application_memory_query_context(w);'),1)=2
    AND candidate_proc.prosrc=replace(canonical_proc.prosrc,'context:=application_memory_query_context(w);','context:=admitted_context;')
    AND ROW(candidate_proc.proowner,candidate_proc.prosecdef,candidate_proc.proconfig,candidate_proc.prolang,candidate_proc.provolatile,candidate_proc.proparallel,candidate_proc.proisstrict,candidate_proc.prorettype,candidate_proc.proretset,candidate_proc.prokind,candidate_proc.proleakproof)
     IS NOT DISTINCT FROM ROW(canonical_proc.proowner,canonical_proc.prosecdef,canonical_proc.proconfig,canonical_proc.prolang,canonical_proc.provolatile,canonical_proc.proparallel,canonical_proc.proisstrict,canonical_proc.prorettype,canonical_proc.proretset,canonical_proc.prokind,canonical_proc.proleakproof)) THEN
   RAISE EXCEPTION 'native_memory_scan_context_unavailable' USING ERRCODE='55P03';END IF;
  query_context:=application_memory_query_context(w);
  IF query_context#>>'{policy,nativeDefault}' IS DISTINCT FROM 'true' THEN
   RAISE EXCEPTION 'native_memory_scan_context_unavailable' USING ERRCODE='55P03';END IF;
  shared_context:=true;
 EXCEPTION WHEN lock_not_available THEN shared_context:=false;query_context:=NULL;
 END;
 WITH RECURSIVE successors(id,depth) AS (
  SELECT t.successor_id,1 FROM native_memory_successor_transitions t JOIN jsonb_array_elements(frozen->'candidates') c ON t.predecessor_id=(c->>'id')::uuid
   WHERE t.workspace_id=w AND t.predecessor_version=c->>'version'
  UNION ALL SELECT t.successor_id,s.depth+1 FROM successors s JOIN native_memory_successor_transitions t ON t.workspace_id=w AND t.predecessor_id=s.id WHERE s.depth<100
 ) SELECT coalesce(array_agg(DISTINCT id),'{}') INTO excluded FROM successors;
 FOR candidate IN SELECT id,scope_version FROM memories WHERE workspace_id=w AND NOT id=ANY(excluded)
  AND (valid_to IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(frozen->'candidates') c WHERE c->>'id'=memories.id::text AND c->>'version'=memories.scope_version::text)) ORDER BY id LOOP
  count_value:=count_value+1;IF count_value>4096 THEN RETURN NULL;END IF;
  IF NOT include_retained AND EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind='memory' AND d.resource_id=candidate.id) THEN CONTINUE;END IF;
  IF shared_context AND NOT EXISTS(SELECT 1 FROM memories WHERE workspace_id=w AND id=candidate.id AND valid_to IS NOT NULL) THEN
   state:=application_memory_query_candidate_state(w,candidate.id,fields,query_context);
  ELSE
   state:=application_memory_field_state(w,candidate.id,fields);
  END IF;
  IF state IS NULL OR application_query_scope_admits_point(bounds,state->'source') IS NOT TRUE THEN CONTINUE;END IF;
  candidates:=candidates||jsonb_build_array(jsonb_build_object('id',candidate.id,'version',candidate.scope_version::text,'source',state->'source'));
  policies:=policies||jsonb_build_array(jsonb_build_object('id',candidate.id,'policy',
   CASE WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(frozen->'policies') original_policy
    WHERE original_policy->>'id'=candidate.id::text AND original_policy->'policy'=state->'legacyPolicyVersion')
   THEN state->'legacyPolicyVersion' ELSE state->'policyVersion' END));
 END LOOP;
 IF shared_context AND (NOT EXISTS(SELECT 1 FROM pg_proc canonical_proc JOIN pg_proc candidate_proc
   ON candidate_proc.oid='public.application_memory_query_candidate_state(uuid,uuid,text[],jsonb)'::regprocedure
   WHERE canonical_proc.oid='public.application_memory_field_state_before_successor(uuid,uuid,text[])'::regprocedure
    AND array_length(string_to_array(canonical_proc.prosrc,'context:=application_memory_query_context(w);'),1)=2
    AND candidate_proc.prosrc=replace(canonical_proc.prosrc,'context:=application_memory_query_context(w);','context:=admitted_context;')
    AND ROW(candidate_proc.proowner,candidate_proc.prosecdef,candidate_proc.proconfig,candidate_proc.prolang,candidate_proc.provolatile,candidate_proc.proparallel,candidate_proc.proisstrict,candidate_proc.prorettype,candidate_proc.proretset,candidate_proc.prokind,candidate_proc.proleakproof)
     IS NOT DISTINCT FROM ROW(canonical_proc.proowner,canonical_proc.prosecdef,canonical_proc.proconfig,canonical_proc.prolang,canonical_proc.provolatile,canonical_proc.proparallel,canonical_proc.proisstrict,canonical_proc.prorettype,canonical_proc.proretset,canonical_proc.prokind,canonical_proc.proleakproof))
  OR application_memory_query_context(w) IS DISTINCT FROM query_context) THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('candidates',candidates,'policies',policies);
END

DECLARE selected memories;row_value memories;entry jsonb;transition native_memory_successor_transitions;
 receipt jsonb;state scope_resource_states;item jsonb;field application_field_resources;observation application_field_observations;
 ids uuid[]:=ARRAY[i];seen uuid[]:='{}';pending uuid;parents uuid[];forward_seen uuid[];cursor_id uuid;
 chain jsonb:='[]';transitions jsonb:='[]';receipts jsonb:='[]';anchors jsonb:='[]';own_fields jsonb:='[]';roots jsonb:='[]';
 protected boolean;actual_state jsonb;matched boolean;successor memories;successor_receipt jsonb;derivation scope_derivations;
 derivation_version text;points jsonb;retirement_fields jsonb:='[]';retraction_fields jsonb:='[]';retraction_roots jsonb:='[]';retirements jsonb:='[]';
 independent_roots jsonb;independent_nodes jsonb:='[]';queue jsonb;walk jsonb;child jsonb;walk_index integer:=0;
BEGIN
 SELECT * INTO selected FROM memories WHERE workspace_id=w AND id=i;
 IF NOT FOUND OR selected.scope_version::text IS DISTINCT FROM v THEN RETURN NULL;END IF;
 WHILE cardinality(ids)>0 LOOP
  pending:=ids[1];ids:=ids[2:];IF pending=ANY(seen) THEN CONTINUE;END IF;
  seen:=array_append(seen,pending);IF cardinality(seen)>100 THEN RETURN NULL;END IF;
  SELECT * INTO row_value FROM memories WHERE id=pending;
  IF NOT FOUND OR row_value.workspace_id IS DISTINCT FROM w THEN RETURN NULL;END IF;
  SELECT array_agg(id ORDER BY id) INTO parents FROM memories WHERE workspace_id=w AND superseded_by=pending;
  IF cardinality(parents)>1 THEN RETURN NULL;END IF;
  ids:=ids||coalesce(parents,'{}');
  IF row_value.superseded_by IS NOT NULL THEN
   IF row_value.valid_to IS NULL THEN RETURN NULL;END IF;
   ids:=array_append(ids,row_value.superseded_by);
  END IF;
  chain:=chain||jsonb_build_array(jsonb_build_object('id',row_value.id,'version',row_value.scope_version::text,
   'held',row_value.scope_held,'validTo',row_value.valid_to,'supersededBy',row_value.superseded_by,
   'retractedAt',row_value.retracted_at,'retractedBy',row_value.retracted_by,
   'scope',jsonb_build_object('workspaceId',w,'userId',row_value.user_id,'assistantId',row_value.assistant_id,
    'sensitivity',row_value.sensitivity,'compartments',row_value.compartments,'projectIds',row_value.project_ids)));
 END LOOP;
 -- A real physical chain may be unprotected; mere consumer observations are not outgoing provenance.
 protected:=EXISTS(SELECT 1 FROM scope_derivations WHERE workspace_id=w AND resource_kind='memory' AND resource_id=ANY(seen))
  OR EXISTS(SELECT 1 FROM memories WHERE workspace_id=w AND id=ANY(seen) AND(source_session_id IS NOT NULL OR source_episode_id IS NOT NULL))
  OR EXISTS(SELECT 1 FROM native_memory_successor_transitions WHERE workspace_id=w AND(predecessor_id=ANY(seen) OR successor_id=ANY(seen)))
  OR EXISTS(SELECT 1 FROM correction_audit WHERE workspace_id=w AND row_id=ANY(seen) AND native_memory_transition IS NOT NULL);
 FOR entry IN SELECT value FROM jsonb_array_elements(chain) ORDER BY value->>'id' LOOP
  SELECT * INTO row_value FROM memories WHERE workspace_id=w AND id=(entry->>'id')::uuid;
  cursor_id:=row_value.id;forward_seen:='{}';
  LOOP
   IF cursor_id=ANY(forward_seen) THEN RETURN NULL;END IF;
   forward_seen:=array_append(forward_seen,cursor_id);
   SELECT superseded_by INTO cursor_id FROM memories WHERE workspace_id=w AND id=cursor_id;
   IF NOT FOUND THEN RETURN NULL;END IF;EXIT WHEN cursor_id IS NULL;
  END LOOP;
  anchors:=anchors||jsonb_build_array(jsonb_build_object('kind','memory','id',row_value.id,'version',row_value.scope_version::text));
  IF row_value.superseded_by IS NOT NULL THEN
   SELECT * INTO transition FROM native_memory_successor_transitions WHERE workspace_id=w AND predecessor_id=row_value.id
    AND predecessor_version=row_value.scope_version::text AND successor_id=row_value.superseded_by;
   IF NOT FOUND THEN
    -- Absence is proved for this legacy creation edge, not inferred from a
    -- convenient later authenticated version elsewhere in the physical chain.
    SELECT * INTO successor FROM memories WHERE workspace_id=w AND id=row_value.superseded_by;
    IF NOT FOUND OR EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind='memory'
      AND d.resource_id IN(row_value.id,successor.id))
     OR row_value.source_session_id IS NOT NULL OR row_value.source_episode_id IS NOT NULL
     OR successor.source_session_id IS NOT NULL OR successor.source_episode_id IS NOT NULL
     OR EXISTS(SELECT 1 FROM correction_audit a WHERE a.workspace_id=w AND a.row_id IN(row_value.id,successor.id) AND a.native_memory_transition IS NOT NULL)
     OR EXISTS(SELECT 1 FROM native_memory_successor_transitions t WHERE t.workspace_id=w
      AND(t.successor_id IN(row_value.id,successor.id) OR t.predecessor_id=row_value.id)) THEN RETURN NULL;END IF;
   ELSE
    transitions:=transitions||jsonb_build_array(to_jsonb(transition));
    SELECT * INTO successor FROM memories WHERE workspace_id=w AND id=transition.successor_id;
    IF NOT FOUND THEN RETURN NULL;END IF;
    derivation_version:=successor.scope_version::text;
    IF successor.retracted_at IS NOT NULL THEN
     SELECT native_memory_transition INTO successor_receipt FROM correction_audit WHERE workspace_id=w AND row_id=successor.id
      AND primitive='memory' AND action='retract' AND native_memory_transition->>'kind'='native_memory_retract_v1';
     IF NOT FOUND OR successor_receipt->>'resultVersion' IS DISTINCT FROM successor.scope_version::text
      OR successor_receipt->>'priorVersion' IS DISTINCT FROM (successor.scope_version-1)::text
      OR successor_receipt->>'actorId' IS DISTINCT FROM successor.retracted_by::text THEN RETURN NULL;END IF;
     derivation_version:=successor_receipt->>'priorVersion';
    END IF;
    SELECT * INTO derivation FROM scope_derivations WHERE workspace_id=w AND resource_kind='memory'
     AND resource_id=successor.id AND resource_version=derivation_version;
    IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM scope_derivation_sources e WHERE e.workspace_id=w AND e.derivation_id=derivation.id
      AND e.source_kind='memory' AND e.source_id=transition.predecessor_id AND e.source_version=transition.predecessor_version) THEN RETURN NULL;END IF;
    SELECT coalesce(jsonb_agg(jsonb_build_object('kind',e.source_kind,'id',e.source_id,'version',e.source_version) ORDER BY e.source_kind,e.source_id),'[]')
     INTO item FROM scope_derivation_sources e WHERE e.workspace_id=w AND e.derivation_id=derivation.id;
    roots:=roots||item;IF jsonb_array_length(roots)>4096 THEN RETURN NULL;END IF;
    retirements:=retirements||jsonb_build_array(jsonb_build_object('transition',to_jsonb(transition),'derivation',to_jsonb(derivation),'roots',item));
    SELECT coalesce(jsonb_agg(jsonb_build_object('kind','application_field','id',f.id,'version',o.version)),'[]') INTO points FROM scope_derivation_sources e
     JOIN application_field_resources f ON f.workspace_id=w AND f.id=e.source_id
     JOIN application_field_observations o ON o.workspace_id=w AND o.resource_id=f.id AND o.version=e.source_version
     WHERE e.workspace_id=w AND e.derivation_id=derivation.id AND e.source_kind='application_field'
      AND f.origin='{"kind":"native","moduleKey":"native"}' AND f.type_key='memory' AND f.resource_id=transition.predecessor_id
      AND f.selection='read' AND f.selected_version IS NULL
      AND f.fields=ARRAY(SELECT key FROM unnest(application_memory_field_keys()) key ORDER BY key)
      AND o.source_kind='memory' AND o.source_id=transition.predecessor_id
      AND o.record_version=transition.predecessor_version AND o.source_version=transition.predecessor_version;
    IF jsonb_array_length(points)>1 THEN RETURN NULL;END IF;
    retirement_fields:=retirement_fields||points;
   END IF;
  ELSIF row_value.valid_to IS NOT NULL AND row_value.retracted_at IS NULL THEN RETURN NULL;
  END IF;
  IF row_value.retracted_at IS NOT NULL THEN
   SELECT native_memory_transition INTO receipt FROM correction_audit WHERE workspace_id=w AND row_id=row_value.id
    AND primitive='memory' AND action='retract' AND native_memory_transition->>'kind'='native_memory_retract_v1';
   IF NOT FOUND OR receipt->>'resultVersion' IS DISTINCT FROM row_value.scope_version::text
    OR receipt->>'priorVersion' IS DISTINCT FROM (row_value.scope_version-1)::text
    OR receipt->>'actorId' IS DISTINCT FROM row_value.retracted_by::text
    OR jsonb_typeof(receipt->'originalRoots') IS DISTINCT FROM 'array'
    OR jsonb_typeof(receipt#>'{reasonEvidence,sources}') IS DISTINCT FROM 'array'
    OR receipt->'writeFields' IS DISTINCT FROM '["retracted_at","retracted_reason","retracted_by","valid_to"]'::jsonb THEN RETURN NULL;END IF;
   SELECT * INTO state FROM scope_resource_states WHERE workspace_id=w AND resource_kind='memory' AND resource_id=row_value.id AND resource_version=row_value.scope_version::text;
   matched:=FOUND;actual_state:=CASE WHEN matched THEN jsonb_build_object('workspaceId',w,'resourceKind','memory','resourceId',row_value.id,
    'resourceVersion',row_value.scope_version::text,'reviewState',state.review_state,'classificationRevision',state.classification_revision::text,'holdingReason',state.holding_reason) ELSE 'null'::jsonb END;
   IF row_value.scope_held THEN
    IF NOT matched OR state.review_state IS DISTINCT FROM 'held' OR state.holding_reason IS DISTINCT FROM 'source_changed'
     OR receipt->'resultHoldState' IS DISTINCT FROM actual_state THEN RETURN NULL;END IF;
   ELSIF matched AND state.review_state='held' THEN RETURN NULL;
   END IF;
   anchors:=anchors||jsonb_build_array(jsonb_build_object('kind','memory','id',row_value.id,'version',receipt->>'priorVersion'));
   receipts:=receipts||jsonb_build_array(jsonb_build_object('id',row_value.id,'receipt',receipt,'state',actual_state));
   roots:=roots||(receipt->'originalRoots');retraction_roots:=retraction_roots||(receipt->'originalRoots');
   SELECT coalesce(jsonb_agg(jsonb_build_object('kind','application_field','id',f.id,'version',o.version)),'[]') INTO points
    FROM jsonb_array_elements(receipt->'originalRoots') r
    JOIN application_field_resources f ON r->>'kind'='application_field' AND f.workspace_id=w AND f.id=(r->>'id')::uuid
    JOIN application_field_observations o ON o.workspace_id=w AND o.resource_id=f.id AND o.version=r->>'version'
    WHERE f.origin='{"kind":"native","moduleKey":"native"}' AND f.type_key='memory' AND f.resource_id=row_value.id
     AND f.selection='read' AND f.selected_version IS NULL
     AND f.fields=ARRAY(SELECT key FROM unnest(application_memory_field_keys()) key ORDER BY key)
     AND o.source_kind='memory' AND o.source_id=row_value.id
     AND o.record_version=receipt->>'priorVersion' AND o.source_version=receipt->>'priorVersion';
   IF jsonb_array_length(points)<>1 THEN RETURN NULL;END IF;
   retraction_fields:=retraction_fields||points;
   IF jsonb_array_length(roots)>4096 THEN RETURN NULL;END IF;
  ELSIF row_value.scope_held OR scope_review_state_held('memory',row_value.id) THEN RETURN NULL;
  END IF;
 END LOOP;
 FOR item IN SELECT DISTINCT value FROM jsonb_array_elements(roots) WHERE value->>'kind'='application_field' LOOP
  SELECT * INTO field FROM application_field_resources WHERE workspace_id=w AND id=(item->>'id')::uuid;
  IF NOT FOUND THEN RETURN NULL;END IF;
  SELECT * INTO observation FROM application_field_observations WHERE workspace_id=w AND resource_id=field.id AND version=item->>'version';
  IF NOT FOUND THEN RETURN NULL;END IF;
  IF field.origin='{"kind":"native","moduleKey":"native"}'::jsonb AND field.type_key='memory'
   AND field.resource_id=ANY(seen) AND observation.source_kind='memory' AND observation.source_id=field.resource_id
   AND observation.record_version=observation.source_version
   AND anchors @> jsonb_build_array(jsonb_build_object('kind','memory','id',observation.source_id,'version',observation.source_version))
   AND (retraction_fields @> jsonb_build_array(item) OR retirement_fields @> jsonb_build_array(item)) THEN
   own_fields:=own_fields||jsonb_build_array(jsonb_build_object('kind','application_field','id',field.id,'version',observation.version,
    'resource',to_jsonb(field),'observation',to_jsonb(observation)));
  END IF;
 END LOOP;
 -- Preserve observable independent paths before any tuple projection. The
 -- fixed metadata walk uses the unchanged Knowledge/predecessor edge kernel;
 -- encountering nested historical purpose refuses rather than recursing.
 SELECT coalesce(jsonb_agg(value ORDER BY value::text),'[]') INTO independent_roots FROM(SELECT DISTINCT root.value FROM jsonb_array_elements(roots) root(value)
  WHERE NOT anchors @> jsonb_build_array(root.value) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(own_fields) own(value)
   WHERE own.value->>'kind'=root.value->>'kind' AND own.value->>'id'=root.value->>'id' AND own.value->>'version'=root.value->>'version')) seeds;
 queue:=independent_roots;
 WHILE walk_index<jsonb_array_length(queue) LOOP
  walk:=queue->walk_index;walk_index:=walk_index+1;
  IF independent_nodes @> jsonb_build_array(walk) THEN CONTINUE;END IF;
  independent_nodes:=independent_nodes||jsonb_build_array(walk);
  IF jsonb_array_length(independent_nodes)>4096 THEN RETURN NULL;END IF;
  IF walk->>'kind'='application_field' AND EXISTS(SELECT 1 FROM application_field_resources f WHERE f.workspace_id=w
   AND f.id=(walk->>'id')::uuid AND f.origin='{"kind":"native","moduleKey":"native"}' AND f.type_key='memory' AND f.selection='history') THEN RETURN NULL;END IF;
  FOR child IN SELECT to_jsonb(e) FROM knowledge_version_source_edges(w,walk->>'kind',(walk->>'id')::uuid,walk->>'version') e LOOP
   IF child->>'kind' IS NULL OR child->>'id' IS NULL OR child->>'version' IS NULL THEN RETURN NULL;END IF;
   IF NOT independent_nodes @> jsonb_build_array(child) THEN queue:=queue||jsonb_build_array(child);END IF;
   IF jsonb_array_length(queue)>8192 THEN RETURN NULL;END IF;
  END LOOP;
 END LOOP;
 SELECT coalesce(jsonb_agg(value ORDER BY value->>'kind',value->>'id',value->>'version'),'[]') INTO independent_nodes FROM jsonb_array_elements(independent_nodes);
 SELECT coalesce(jsonb_agg(own ORDER BY own::text),'[]') INTO own_fields FROM jsonb_array_elements(own_fields) own
  WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(independent_nodes) required
   WHERE required->>'kind'=own->>'kind' AND required->>'id'=own->>'id' AND required->>'version'=own->>'version');
 SELECT coalesce(jsonb_agg(value ORDER BY value->>'id'),'[]') INTO chain FROM jsonb_array_elements(chain);
 SELECT coalesce(jsonb_agg(value ORDER BY value::text),'[]') INTO roots FROM(SELECT DISTINCT value FROM jsonb_array_elements(roots)) values_only;
 SELECT coalesce(jsonb_agg(value ORDER BY value::text),'[]') INTO anchors FROM(SELECT DISTINCT value FROM jsonb_array_elements(anchors)) values_only;
 RETURN jsonb_build_object('kind','native-memory-history-status-v1','workspaceId',w,'id',i,'version',v,'protected',protected,
  'chain',chain,'transitions',transitions,'retirements',retirements,'receipts',receipts,'anchors',anchors,'ownFields',own_fields,
  'qualifiedAnchors',(SELECT coalesce(jsonb_agg(a),'[]') FROM jsonb_array_elements(anchors) a WHERE NOT independent_nodes @> jsonb_build_array(a)),
  'independentRoots',independent_roots,'independentNodes',independent_nodes,'roots',roots);
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR numeric_value_out_of_range THEN RETURN NULL;
END

DECLARE context jsonb;source jsonb;policy jsonb;mask jsonb;row_version text;values_json jsonb:='{}';field text;value jsonb;
BEGIN
 IF fields IS NULL OR NOT fields<@application_memory_field_keys() OR array_position(fields,NULL) IS NOT NULL
  OR cardinality(fields)<>(SELECT count(DISTINCT f) FROM unnest(fields) f) THEN RETURN NULL;END IF;
 context:=admitted_context;
 IF context IS NULL OR NOT coalesce(to_jsonb(fields)<@(context->'read'),false) THEN RETURN NULL;END IF;
 SELECT scope_version::text INTO row_version FROM memories WHERE workspace_id=w AND id=i;
 IF NOT FOUND THEN RETURN NULL;END IF;
 -- Retained history without matching immutable current observations never becomes a native leaf.
 IF EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind='memory' AND d.resource_id=i)
  AND NOT EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind='memory' AND d.resource_id=i AND d.resource_version=row_version) THEN RETURN NULL;END IF;
 source:=read_admitted_native_scope_snapshot(w,'memory',i);
 IF source IS NULL OR source->>'held' IS DISTINCT FROM 'false' OR source->>'version' IS DISTINCT FROM row_version
  OR application_query_scope_admits_point(context->'bounds',source) IS NOT TRUE
  OR application_canonical_ancestry_allowed(w,'memory',i,row_version) IS NOT TRUE THEN RETURN NULL;END IF;
 policy:=application_native_field_contract_for(w,'{"kind":"native","moduleKey":"native"}','memory',i::text);
 IF policy->>'registered' IS DISTINCT FROM 'false' THEN
  IF policy->>'registered' IS DISTINCT FROM 'true' OR policy->>'held' IS DISTINCT FROM 'false'
   OR policy#>>'{metadata,recordVersion}' IS DISTINCT FROM row_version THEN RETURN NULL;END IF;
  mask:=read_native_application_field_mask(w,'{"kind":"native","moduleKey":"native"}','memory',i::text,row_version);
  IF mask IS NULL OR NOT coalesce(to_jsonb(fields)<@(mask->'readFields'),false) THEN RETURN NULL;END IF;
 END IF;
 -- Only the selected, already admitted fields are evaluated. No whole-row JSON before the mask.
 IF cardinality(fields)>0 THEN
  -- Identifiers come only from the validated selected field keys above.
  -- Each column is serialized individually after admission, never as a row.
  SELECT 'SELECT jsonb_build_object('||string_agg(format('%L,to_jsonb(%I)',selected,selected),',' ORDER BY ordinal)||
   ') FROM public.memories WHERE workspace_id=$1 AND id=$2 AND scope_version::text=$3'
   INTO field FROM unnest(fields) WITH ORDINALITY selection(selected,ordinal);
  EXECUTE field INTO values_json USING w,i,row_version;
 END IF;
 source:=jsonb_build_object('workspaceId',w,'userId',source->'userId','assistantId',source->'assistantId',
  'sensitivity',source->'sensitivity','compartments',source->'compartments','projectIds',source->'projectIds',
  'resourceKind','memory','resourceId',i,'version',row_version);
 RETURN jsonb_build_object('values',values_json,'source',source,'recordVersion',row_version,'sourceKind','memory','sourceId',i,'sourceVersion',row_version,'ownerId',NULL,
  'fieldIdentity',application_field_digest(jsonb_build_object('kind','memory-fields-v1','fields',fields)),
  'legacyPolicyVersion',application_field_digest(jsonb_build_object('kind','memory-fields-v1','catalog',context#>'{policy,fingerprint}','record',policy->'fingerprint','mask',mask)),
  'policyVersion',application_field_digest(jsonb_build_object('kind','memory-read-v2','catalog',context#>'{policy,fingerprint}','record',policy->'fingerprint','selectedRead',jsonb_build_object('fields',fields,'allowed',true))),
  'references','[]'::jsonb);
END

DECLARE actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;bounds jsonb;policy jsonb;mask jsonb;keys text[];fields jsonb;scope jsonb;
BEGIN
 IF actor IS NULL OR nullif(current_setting('app.application_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.public_share_root',true),'') IS NOT NULL
  OR nullif(current_setting('app.agent_workspace_id',true),'') IS DISTINCT FROM w::text
  OR NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=actor)
  OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='public.memories'::regclass WHERE r.rolname=session_user
   AND(r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,'USAGE'))) THEN RETURN NULL;END IF;
 -- Unsupported in-flight data selectors hold instead of dropping a restriction.
 DECLARE
  ceilings jsonb:=coalesce(nullif(current_setting('app.native_query_data_ceilings',true),'')::jsonb,'[]'::jsonb);
  ceiling jsonb;scope_cap jsonb;axis text;
 BEGIN
  IF jsonb_typeof(ceilings) IS DISTINCT FROM 'array' OR jsonb_array_length(ceilings)>16 THEN RETURN NULL;END IF;
  FOR ceiling IN SELECT value FROM jsonb_array_elements(ceilings) LOOP
   IF jsonb_typeof(ceiling) IS DISTINCT FROM 'object'
    OR ceiling-ARRAY['workspaceId','typeKey','ids','tier','compartments','projectIds','departmentRead','privateUserId','assistants']<>'{}'
    OR NOT ceiling ?& ARRAY['workspaceId','typeKey','ids','tier','compartments','projectIds','departmentRead','privateUserId','assistants']
    OR jsonb_typeof(ceiling->'workspaceId') IS DISTINCT FROM 'string'
    OR jsonb_typeof(ceiling->'typeKey') IS DISTINCT FROM 'string'
    OR ceiling->>'typeKey' NOT IN('company','person','deal','task')
    OR ceiling->'tier' NOT IN('0'::jsonb,'1'::jsonb,'2'::jsonb,'3'::jsonb)
    OR jsonb_typeof(ceiling->'privateUserId') NOT IN('string','null') THEN RETURN NULL;END IF;
   PERFORM (ceiling->>'workspaceId')::uuid;
   IF ceiling->>'privateUserId' IS NOT NULL THEN PERFORM (ceiling->>'privateUserId')::uuid;END IF;
   FOREACH axis IN ARRAY ARRAY['ids','assistants'] LOOP
    IF jsonb_typeof(ceiling->axis) NOT IN('array','null') THEN RETURN NULL;END IF;
    IF ceiling->axis<>'null'::jsonb THEN
     IF jsonb_array_length(ceiling->axis)>(CASE axis WHEN 'ids' THEN 100 ELSE 256 END)
      OR EXISTS(SELECT 1 FROM jsonb_array_elements(ceiling->axis) item WHERE jsonb_typeof(item)<>'string') THEN RETURN NULL;END IF;
     PERFORM (value#>>'{}')::uuid FROM jsonb_array_elements(ceiling->axis);
    END IF;
   END LOOP;
   scope_cap:=application_query_scope_cap((ceiling->>'tier')::int,ceiling->'compartments',ceiling->'projectIds');
   IF scope_cap IS NULL THEN RETURN NULL;END IF;
   IF ceiling->'departmentRead'<>'null'::jsonb THEN
    IF application_query_scope_valid(ceiling->'departmentRead') IS NOT TRUE
     OR application_query_scope_intersection(scope_cap,ceiling->'departmentRead') IS NULL THEN RETURN NULL;END IF;
   END IF;
  END LOOP;
 END;
 bounds:=application_native_query_bounds(w);IF bounds IS NULL OR application_query_scope_valid(bounds) IS NOT TRUE THEN RETURN NULL;END IF;
 keys:=ARRAY(SELECT key FROM unnest(application_memory_field_keys()) key ORDER BY key);
 policy:=application_native_field_catalog_for(w,'{"kind":"native","moduleKey":"native"}','memory');
 IF policy->>'registered'='false' THEN
  SELECT jsonb_agg(jsonb_build_object('key',key,'read','[]'::jsonb,'write','[]'::jsonb,'releaseReadTo','[]'::jsonb,'releaseWriteTo','[]'::jsonb) ORDER BY key)
   INTO fields FROM unnest(keys) key;
  -- This is the public schema definition, not a default for a data row or missing ancestor.
  scope:=jsonb_build_object('workspaceId',w,'userId',NULL,'assistantId',NULL,'sensitivity','public','compartments','[]'::jsonb,'projectIds','[]'::jsonb);
  policy:=jsonb_build_object('registered',true,'held',false,'nativeDefault',true,'roleKeys','[]'::jsonb,
   'metadata',jsonb_build_object('moduleKey','native','origin','{"kind":"native","moduleKey":"native"}'::jsonb,'typeKey','memory',
    'schemaVersion','memory-fields-v1','policyVersion','memory-fields-v1','fieldKeys',keys,'fields',fields,'scope',scope),
   'fingerprint',application_field_digest(jsonb_build_object('kind','memory-fields-v1','workspaceId',w,'fields',fields)));
  mask:=application_native_member_field_permissions(w,policy,actor);
 ELSE
  IF policy->>'registered' IS DISTINCT FROM 'true' OR policy->>'held' IS DISTINCT FROM 'false'
   OR NOT coalesce(to_jsonb(keys)<@(policy#>'{metadata,fieldKeys}'),false) THEN RETURN NULL;END IF;
  mask:=read_native_application_field_catalog(w,'{"kind":"native","moduleKey":"native"}','memory');
  mask:=jsonb_build_object('read',mask->'readFields');
 END IF;
 IF workflow_evidence_envelope_visible(w,policy#>'{metadata,scope}') IS NOT TRUE OR jsonb_typeof(mask->'read') IS DISTINCT FROM 'array' THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('policy',policy,'read',mask->'read','bounds',bounds,
  'visibility',jsonb_build_object('userId',CASE WHEN current_setting('app.agent_shared_audience',true)='true' THEN NULL ELSE actor END,
   'assistants',coalesce(nullif(current_setting('app.agent_visibility_assistants',true),'')::jsonb,'null'::jsonb)));
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR numeric_value_out_of_range THEN RETURN NULL;
END

DECLARE frozen application_query_domains;context jsonb;scanned jsonb;
BEGIN
 SELECT * INTO frozen FROM application_query_domains WHERE workspace_id=w AND id=i AND origin='{"kind":"native","moduleKey":"native"}' AND type_key='memory';
 IF NOT FOUND OR frozen.domain->>'kind' IS DISTINCT FROM 'memory_query_domain_v1'
  OR frozen.domain-ARRAY['kind','fields','bounds','visibility','includeRetained','candidates','policies']<>'{}'
  OR frozen.domain->'fields' IS DISTINCT FROM to_jsonb(fields) THEN RETURN NULL;END IF;
 context:=application_memory_query_context(w);
 IF context IS NULL OR context#>>'{policy,metadata,schemaVersion}' IS DISTINCT FROM frozen.schema_version
  OR NOT coalesce(to_jsonb(fields)<@(context->'read'),false)
  OR application_query_scope_union_contains(frozen.domain->'bounds',jsonb_build_array(context->'bounds'),4096)->>'contains' IS DISTINCT FROM 'true'
  OR frozen.domain->'visibility' IS DISTINCT FROM context->'visibility' THEN RETURN NULL;END IF;
 scanned:=application_memory_historical_query_scan(w,fields,frozen.domain->'bounds',(frozen.domain->>'includeRetained')::boolean,frozen.domain);
 IF scanned IS NULL OR scanned->'candidates' IS DISTINCT FROM frozen.domain->'candidates' OR scanned->'policies' IS DISTINCT FROM frozen.domain->'policies' THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('values','{}'::jsonb,'source',context#>'{policy,metadata,scope}','recordVersion',frozen.schema_version,
  'sourceKind','application_query_domain','sourceId',i,'sourceVersion',frozen.identity,'ownerId',NULL,
  'fieldIdentity',application_field_digest(jsonb_build_object('kind','memory_query_domain_v1','identity',frozen.identity,'fields',fields)),
  'policyVersion',application_field_digest(jsonb_build_object('kind','memory_query_domain_v1','identity',frozen.identity,'policy',context#>'{policy,fingerprint}','policies',scanned->'policies')),
  'references','[]'::jsonb);
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR numeric_value_out_of_range THEN RETURN NULL;
END

