DECLARE admitted jsonb;captured jsonb;
BEGIN
 captured:=application_recorded_field_root_capture(w,i,v,depth);
 admitted:=CASE WHEN captured ? 'envelope' THEN captured->'state' ELSE captured END;
 IF admitted IS NULL OR admitted->>'held' IS DISTINCT FROM 'false' THEN RETURN admitted;END IF;
 IF application_canonical_ancestry_from_admitted_root(w,'application_field',i,v,false,
  jsonb_build_object('kind','application_field','id',i,'version',v,'state',admitted,'envelope',captured->'envelope')) IS NOT TRUE THEN RETURN '{"held":true}'::jsonb;END IF;
 RETURN admitted;
END

'::text)) pin(function_oid,fingerprint)
   JOIN pg_catalog.pg_proc r ON r.oid=pin.function_oid) THEN
  RETURN QUERY SELECT kinds[1],ids[1],versions[1];
  RETURN;
 END IF;
 WITH RECURSIVE lineage(kind,id,version) AS (
  SELECT * FROM unnest(kinds,ids,versions)
  UNION
  SELECT next.kind,next.id,next.version FROM lineage l
   CROSS JOIN LATERAL application_scope_source_edges(w,l.kind,l.id,l.version) next
 ), bounded AS MATERIALIZED(SELECT * FROM lineage LIMIT 4097)
 SELECT coalesce(jsonb_agg(to_jsonb(b)),'[]') INTO nodes FROM bounded b;
 -- UNION terminates native high-water back-edges (including a row edited from
 -- its earlier version). New field-child graphs are separately depth bounded
 -- by capture and the admitted reader; no app role may author metadata edges.
 IF jsonb_array_length(nodes)>4096 OR EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n
  WHERE n->>'version' IS NULL OR n->>'kind' IS NULL OR n->>'id' IS NULL
   OR n->>'kind'='application_field' AND NOT EXISTS(SELECT 1 FROM application_field_observations o
    WHERE o.workspace_id=w AND o.resource_id=(n->>'id')::uuid AND o.version=n->>'version')) THEN
  RAISE EXCEPTION 'scope_ancestry_unavailable' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT DISTINCT n->>'kind',(n->>'id')::uuid,n->>'version' FROM jsonb_array_elements(nodes) n;
END

DECLARE resource application_field_resources;observation application_field_observations;proof jsonb;
BEGIN
 RETURN QUERY SELECT e.kind,e.id,e.version FROM knowledge_version_source_edges(w,k,i,v) e;
 IF k IS DISTINCT FROM 'application_field' THEN RETURN;END IF;
 SELECT f.* INTO resource FROM application_field_resources f WHERE f.workspace_id=w AND f.id=i
  AND f.origin='{"kind":"native","moduleKey":"native"}' AND f.type_key='memory' AND f.selection='history';
 IF NOT FOUND THEN RETURN;END IF;
 SELECT o.* INTO observation FROM application_field_observations o WHERE o.workspace_id=w AND o.resource_id=i AND o.version=v;
 IF NOT FOUND OR observation.source_kind IS DISTINCT FROM 'memory' OR observation.source_id IS DISTINCT FROM resource.resource_id
  OR observation.record_version IS DISTINCT FROM resource.selected_version OR observation.source_version IS DISTINCT FROM resource.selected_version THEN
  RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 proof:=application_memory_history_status(w,resource.resource_id,resource.selected_version);
 IF proof IS NULL THEN RAISE EXCEPTION 'scope_ancestry_unavailable' USING ERRCODE='22023';END IF;
 RETURN QUERY SELECT value->>'kind',(value->>'id')::uuid,value->>'version' FROM jsonb_array_elements(proof->'roots');
END

DECLARE frozen application_query_domains;parent jsonb;current_bounds jsonb;visibility jsonb;result jsonb;scanned jsonb;actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;state jsonb;
BEGIN
 SELECT * INTO frozen FROM application_query_domains WHERE workspace_id=w AND id=i AND origin='{"kind":"native","moduleKey":"native"}' AND type_key=t;
 IF NOT FOUND OR frozen.domain->>'kind' IS DISTINCT FROM 'session_query_domain_v1'
  OR frozen.domain-ARRAY['kind','sessionId','throughSequence','fields','bounds','visibility','parentFingerprint','candidates','points']<>'{}'
  OR frozen.domain->'fields' IS DISTINCT FROM to_jsonb(fields) THEN RETURN jsonb_build_object('memo',memo);END IF;
 parent:=application_session_query_parent(w,(frozen.domain->>'sessionId')::uuid);
 IF parent IS NULL OR parent->'fingerprint' IS DISTINCT FROM frozen.domain->'parentFingerprint' THEN RETURN jsonb_build_object('memo',memo);END IF;
 current_bounds:=application_session_query_bounds(w,parent);
 IF current_bounds IS NULL OR application_query_scope_union_contains(frozen.domain->'bounds',jsonb_build_array(current_bounds),4096)->>'contains' IS DISTINCT FROM 'true' THEN RETURN jsonb_build_object('memo',memo);END IF;
 visibility:=jsonb_build_object('userId',CASE WHEN current_setting('app.agent_shared_audience',true)='true' THEN NULL ELSE actor END,
  'assistants',coalesce(nullif(current_setting('app.agent_visibility_assistants',true),'')::jsonb,'null'::jsonb));
 IF frozen.domain#>>'{visibility,userId}' IS NOT NULL AND frozen.domain#>>'{visibility,userId}' IS DISTINCT FROM visibility->>'userId'
  OR visibility->'assistants'<>'null'::jsonb AND (frozen.domain#>'{visibility,assistants}'='null'::jsonb
   OR NOT coalesce(frozen.domain#>'{visibility,assistants}'<@(visibility->'assistants'),false)) THEN RETURN jsonb_build_object('memo',memo);END IF;
 result:=application_session_eval_scan(w,(frozen.domain->>'sessionId')::uuid,t,(frozen.domain->>'throughSequence')::integer,fields,frozen.domain->'bounds',frozen.domain->'visibility',memo);
 memo:=coalesce(result->'memo',memo);scanned:=result->'value';
 IF scanned IS NULL OR scanned->'candidates' IS DISTINCT FROM frozen.domain->'candidates' OR scanned->'points' IS DISTINCT FROM frozen.domain->'points' THEN RETURN jsonb_build_object('memo',memo);END IF;
 state:=jsonb_build_object('values','{}'::jsonb,'source',parent->'scope','recordVersion','1',
  'sourceKind','application_query_domain','sourceId',i,'sourceVersion',frozen.identity,'ownerId',NULL,
  'fieldIdentity',application_field_digest(jsonb_build_object('kind','session_query_domain_v1','identity',frozen.identity,'fields',fields)),
  'policyVersion',application_field_digest(jsonb_build_object('kind','session_query_domain_v1','identity',frozen.identity,'policies',scanned->'policies')),
  'references','[]'::jsonb,'queryPoints',frozen.domain->'points');
 RETURN jsonb_build_object('value',state,'memo',memo,'children',result->'children');
END

DECLARE result jsonb;state jsonb;scope jsonb;identity_value text;resource uuid;version_value text;sources jsonb:='[]';children jsonb:='[]';child jsonb;external record;keys text[];
 origin constant jsonb:='{"kind":"native","moduleKey":"native"}';
BEGIN
 IF (t NOT IN('session_message','session_message_annotation') AND NOT(t='memory' AND coalesce(memo#>>'{memoryStatement,workspaceId}'=w::text,false))) OR selection NOT IN('read','query','identity','query_domain') THEN RETURN jsonb_build_object('memo',memo);END IF;
 keys:=ARRAY(SELECT DISTINCT key FROM unnest(fields) key ORDER BY key);
 IF fields IS NULL OR cardinality(keys)<>cardinality(fields) THEN RETURN jsonb_build_object('memo',memo);END IF;
 IF t='memory' THEN
  state:=CASE WHEN selection='query_domain' THEN application_memory_statement_domain(w,i,keys,memo->'memoryStatement') ELSE application_memory_statement_state(w,i,keys,memo->'memoryStatement') END;
  IF state IS NULL THEN RETURN jsonb_build_object('memo',memo);END IF;
  RETURN jsonb_build_object('memo',memo,'value',application_memory_statement_envelope(w,origin,t,i,selection,NULL,keys,0,state));
 END IF;
 IF selection='query_domain' THEN result:=application_session_eval_domain(w,t,i,keys,memo);children:=coalesce(result->'children','[]'::jsonb);
 ELSE result:=application_session_eval_point_state(w,t,i,keys,memo);END IF;
 memo:=coalesce(result->'memo',memo);state:=result->'value';
 IF state IS NULL OR state='null'::jsonb THEN RETURN jsonb_build_object('memo',memo);END IF;
 scope:=jsonb_build_object('workspaceId',w,'userId',state#>'{source,userId}','assistantId',state#>'{source,assistantId}',
  'sensitivity',state#>'{source,sensitivity}','compartments',state#>'{source,compartments}','projectIds',state#>'{source,projectIds}');
 IF entity_derivation_envelope_valid(scope) IS NOT TRUE THEN RETURN jsonb_build_object('memo',memo);END IF;
 identity_value:=application_field_digest(jsonb_build_object('workspaceId',w,'origin',origin,'typeKey',t,'id',i,
  'selection',selection,'selectedVersion',NULL,'fields',keys,'fieldIdentity',state->'fieldIdentity'));
 resource:=application_field_resource_uuid(identity_value);
 IF memo#>>ARRAY['native:'||(state->>'sourceKind')||':'||(state->>'sourceId')||':'||(state->>'sourceVersion'),'value'] IS DISTINCT FROM 'true'
  OR memo#>ARRAY['native:'||(state->>'sourceKind')||':'||(state->>'sourceId')||':'||(state->>'sourceVersion'),'external'] IS DISTINCT FROM '[]'::jsonb THEN
 FOR external IN SELECT * FROM read_external_source_dependencies(w,ARRAY[state->>'sourceKind'],ARRAY[(state->>'sourceId')::uuid],ARRAY[state->>'sourceVersion']) LOOP
  IF external.source IS NULL OR external.source->>'workspaceId' IS DISTINCT FROM w::text OR external.node_version IS DISTINCT FROM external.source->>'version' THEN RETURN jsonb_build_object('memo',memo);END IF;
  sources:=sources||jsonb_build_array(external.source);
 END LOOP;
 END IF;
 FOR child IN SELECT value FROM jsonb_array_elements(children) LOOP
  sources:=sources||jsonb_build_array(child->'source')||coalesce(child->'sources','[]');
 END LOOP;
 SELECT coalesce(jsonb_agg(value ORDER BY value::text),'[]') INTO sources FROM (SELECT DISTINCT value FROM jsonb_array_elements(sources)) unique_sources;
 IF jsonb_array_length(sources)>4096 OR jsonb_array_length(children)>4096 THEN RETURN jsonb_build_object('memo',memo);END IF;
 version_value:=application_field_digest(jsonb_build_object('resourceId',resource,'recordVersion',state->'recordVersion',
  'sourceVersion',state->'sourceVersion','policyVersion',state->'policyVersion','scope',scope,'sources',sources));
 RETURN jsonb_build_object('memo',memo,'value',jsonb_build_object('resourceId',resource,'identity',identity_value,'origin',origin,'typeKey',t,'id',i,
  'selection',selection,'selectedVersion',NULL,'fields',keys,'fieldIdentity',state->'fieldIdentity','state',state,'children',children,'sources',sources,
  'source',scope||jsonb_build_object('resourceKind','application_field','resourceId',resource,'version',version_value)));
END

DECLARE key text:='field:'||i||':'||v;resource application_field_resources;observation application_field_observations;result jsonb;envelope jsonb;current_source jsonb;dependency record;refs jsonb:='[]';empty_capture jsonb;empty_lineage jsonb;empty_entry jsonb;
BEGIN
 -- Busy/cycle refusal precedes any worklist invalidation.
 IF memo#>>ARRAY[key,'busy']='true' THEN RETURN jsonb_build_object('memo',memo);END IF;
 IF memo ? 'emptyQueries' THEN
  IF memo ? key THEN
   IF application_empty_query_helpers_current() IS NOT TRUE THEN
    memo:=(SELECT coalesce(jsonb_object_agg(entry.key,entry.value),'{}') FROM jsonb_each(memo) entry WHERE entry.value->>'busy'='true' OR entry.key='memoryStatement');
   ELSIF application_empty_query_worklist_current(w,memo) IS NOT TRUE THEN
    memo:=(SELECT coalesce(jsonb_object_agg(entry.key,entry.value),'{}') FROM jsonb_each(memo) entry WHERE entry.value->>'busy'='true' OR entry.key='memoryStatement');
   END IF;
  END IF;
  IF memo ? 'emptyQueries' AND (SELECT count(*) FROM jsonb_object_keys(memo-'memoryStatement'-'emptyQueries'))
   +(SELECT count(*) FROM jsonb_object_keys(memo->'emptyQueries'))>=4096 THEN
   memo:=(SELECT coalesce(jsonb_object_agg(entry.key,entry.value),'{}') FROM jsonb_each(memo) entry WHERE entry.value->>'busy'='true' OR entry.key='memoryStatement');
  END IF;
 END IF;
 IF memo ? key THEN
  IF memo#>>ARRAY[key,'busy']='true' OR scope_review_state_held('application_field',i)
   OR application_session_eval_sources_current(w,memo#>ARRAY[key,'external']) IS NOT TRUE THEN RETURN jsonb_build_object('memo',memo);END IF;
  RETURN jsonb_build_object('memo',memo,'value',memo#>ARRAY[key,'value']);
 END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(memo-'memoryStatement'))>=4096 OR scope_review_state_held('application_field',i) THEN RETURN jsonb_build_object('memo',memo);END IF;
 SELECT * INTO resource FROM application_field_resources WHERE workspace_id=w AND id=i;
 IF NOT FOUND THEN RETURN jsonb_build_object('memo',memo);END IF;
 IF resource.origin<>'{"kind":"native","moduleKey":"native"}'::jsonb OR (resource.type_key NOT IN('session_message','session_message_annotation') AND NOT(resource.type_key='memory' AND coalesce(memo#>>'{memoryStatement,workspaceId}'=w::text,false))) THEN
  current_source:=application_recorded_field_state_before_session_eval(w,i,v,0);
  IF current_source->>'held'='false' AND resource.origin='{"kind":"native","moduleKey":"native"}'::jsonb
   AND resource.type_key IN('knowledge_entry','task','memory') AND resource.selection='query_domain' AND resource.selected_version IS NULL
   AND application_empty_query_helpers_current() IS TRUE
   AND (SELECT count(*) FROM jsonb_object_keys(memo-'memoryStatement'-'emptyQueries'))
    +(SELECT count(*) FROM jsonb_object_keys(coalesce(memo->'emptyQueries','{}')))<4095 THEN
   empty_capture:=application_recorded_field_root_capture(w,i,v,0);
   SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),'[]') INTO empty_lineage
    FROM application_scope_lineage(w,ARRAY['application_field'],ARRAY[i],ARRAY[v]) n;
   IF empty_capture#>'{envelope,children}'='[]'::jsonb AND empty_capture#>'{envelope,sources}'='[]'::jsonb
    AND empty_capture#>>'{envelope,state,sourceKind}'='application_query_domain'
    AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(empty_lineage) n
     WHERE NOT(n->>'kind'='application_field' AND n->>'id'=i::text AND n->>'version'=v
      OR n->>'kind'='application_query_domain' AND n->>'id'=resource.resource_id::text)) THEN
    empty_entry:=jsonb_build_object('workspaceId',w,'actor',current_setting('app.current_user_id',true),
     'id',i,'version',v,'capture',empty_capture,'state',current_source,'lineage',empty_lineage);
    IF memo#>ARRAY['emptyQueries',i::text||':'||v] IS NOT NULL
     AND memo#>ARRAY['emptyQueries',i::text||':'||v] IS DISTINCT FROM empty_entry THEN
     memo:=(SELECT coalesce(jsonb_object_agg(entry.key,entry.value),'{}') FROM jsonb_each(memo) entry
   WHERE entry.value->>'busy'='true' OR entry.key='memoryStatement');
    END IF;
    memo:=jsonb_set(memo,'{emptyQueries}',coalesce(memo->'emptyQueries','{}')||jsonb_build_object(i::text||':'||v,empty_entry));
   END IF;
  END IF;
  RETURN jsonb_build_object('value',current_source,'memo',memo);
 END IF;
 IF EXISTS(SELECT 1 FROM pg_roles role JOIN pg_class tab ON tab.oid='session_messages'::regclass WHERE role.rolname=session_user
  AND (role.rolsuper OR role.rolbypassrls OR pg_has_role(role.oid,tab.relowner,'USAGE'))) THEN RETURN jsonb_build_object('memo',memo);END IF;
 SELECT * INTO observation FROM application_field_observations WHERE workspace_id=w AND resource_id=i AND version=v;
 IF NOT FOUND OR resource.selected_version IS NOT NULL THEN RETURN jsonb_build_object('memo',memo);END IF;
 memo:=memo||jsonb_build_object(key,jsonb_build_object('busy',true));
 result:=application_session_eval_envelope(w,resource.type_key,resource.resource_id,resource.selection,resource.fields,memo);
 memo:=coalesce(result->'memo',memo);envelope:=result->'value';
 IF envelope IS NULL OR envelope->>'identity' IS DISTINCT FROM resource.identity OR (envelope#>>'{state,policyVersion}' IS DISTINCT FROM observation.policy_version
   AND NOT coalesce(resource.origin='{"kind":"native","moduleKey":"native"}'::jsonb AND resource.type_key='memory'
    AND envelope#>>'{state,legacyPolicyVersion}'=observation.policy_version,false))
  OR workflow_evidence_envelope_visible(w,observation.source_scope) IS NOT TRUE OR workflow_evidence_envelope_visible(w,envelope->'source') IS NOT TRUE THEN RETURN jsonb_build_object('memo',memo);END IF;
 FOR dependency IN SELECT * FROM application_field_observation_sources WHERE workspace_id=w AND resource_id=i AND version=v ORDER BY source_kind,source_id,source_version LOOP
  IF dependency.source_kind='application_field' THEN
   result:=application_session_eval_field(w,dependency.source_id,dependency.source_version,memo);memo:=coalesce(result->'memo',memo);current_source:=result->'value';
  ELSE current_source:=external_source_snapshot(w,dependency.source_id);END IF;
  IF current_source IS NULL OR current_source->>'held' IS DISTINCT FROM 'false'
   OR dependency.source_kind='external_source' AND current_source->>'version' IS DISTINCT FROM dependency.source_version THEN RETURN jsonb_build_object('memo',memo);END IF;
 END LOOP;
 current_source:=(envelope->'source')||jsonb_build_object('held',false,'validTo',NULL,'retractedAt',NULL);
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',source->'resourceId','version',source->'version') ORDER BY source::text),'[]') INTO refs
  FROM jsonb_array_elements(envelope->'sources') source WHERE source->>'resourceKind'='external_source';
 IF EXISTS(SELECT 1 FROM application_scope_lineage(w,ARRAY['application_field'],ARRAY[i],ARRAY[v]) n JOIN application_field_resources f
  ON f.workspace_id=w AND f.id=n.id WHERE n.kind='application_field'
   AND NOT coalesce(memo->'emptyQueries' ? (n.id::text||':'||n.version),false) AND (f.origin<>'{"kind":"native","moduleKey":"native"}'::jsonb OR (f.type_key NOT IN('session_message','session_message_annotation') AND NOT(f.type_key='memory' AND coalesce(memo#>>'{memoryStatement,workspaceId}'=w::text,false))))) THEN
  memo:=memo-key;
 ELSE memo:=memo||jsonb_build_object(key,jsonb_build_object('value',current_source,'external',refs)); END IF;RETURN jsonb_build_object('memo',memo,'value',current_source);
END

DECLARE m session_messages;revision session_context_scope_revisions;source jsonb;parent jsonb;payload jsonb;values_json jsonb;selected jsonb;
 keys text[]:=application_session_field_keys(t);record_version text;source_kind text;source_id uuid;checked jsonb;actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
 direct_kinds text[];direct_ids uuid[];direct_versions text[];direct_position integer;history_shape boolean:=false;
 dependency record;admitted jsonb;projection jsonb;label jsonb;seen jsonb:='[]';immutable_scope jsonb;
BEGIN
 -- Recording privacy admission precedes body selection.
 IF NOT recording_source_read_allowed(w,'session_message',i) THEN RETURN jsonb_build_object('memo',memo);END IF;
 IF keys IS NULL OR fields IS NULL OR cardinality(fields)>cardinality(keys) OR NOT fields<@keys
  OR array_position(fields,NULL) IS NOT NULL OR cardinality(fields)<>(SELECT count(DISTINCT f) FROM unnest(fields) f)
  OR nullif(current_setting('app.application_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.public_share_root',true),'') IS NOT NULL THEN RETURN NULL;END IF;
 -- Only immutable identity/scope metadata is selected before source admission.
 SELECT id,workspace_id,session_id,scope_version,sequence_num INTO m.id,m.workspace_id,m.session_id,m.scope_version,m.sequence_num
  FROM session_messages WHERE workspace_id=w AND id=i;
 IF NOT FOUND THEN RETURN NULL;END IF;
 -- Absence already returns NULL in the annotation branch below. Refuse it
 -- before the expensive parent proof, without changing scan identities or
 -- granting access. A present head still takes the original later head read,
 -- source admission and independent query-domain/currentness proofs.
 IF t='session_message_annotation' AND NOT EXISTS(
  SELECT 1 FROM session_message_annotation_heads h JOIN session_context_scope_revisions r
   ON r.workspace_id=h.workspace_id AND r.id=h.scope_revision_id
  WHERE h.workspace_id=w AND h.session_id=m.session_id AND h.message_id=i
   AND r.parent_kind='message_annotation' AND r.parent_id=i AND r.session_id=m.session_id
 ) THEN RETURN NULL;END IF;
 parent:=application_session_query_parent(w,m.session_id);IF parent IS NULL THEN RETURN NULL;END IF;
 IF t='session_message' THEN
  source:=read_admitted_native_scope_snapshot(w,'session_message',i);
  IF source IS NULL OR source->>'held' IS DISTINCT FROM 'false' OR source->>'version' IS DISTINCT FROM m.scope_version::text
    THEN RETURN NULL;END IF;

  -- Only the first canonical history-bearing message uses complete per-original admission.
  IF actor IS NOT NULL AND EXISTS(SELECT 1 FROM workspace_members member WHERE member.workspace_id=w AND member.user_id=actor)
  AND nullif(current_setting('app.application_id',true),'') IS NULL
  AND nullif(current_setting('app.public_share_root',true),'') IS NULL
  AND NOT EXISTS(SELECT 1 FROM pg_roles login JOIN pg_class owned ON owned.oid='public.session_messages'::regclass WHERE login.rolname=session_user
    AND(login.rolsuper OR login.rolbypassrls OR pg_has_role(login.oid,owned.relowner,'USAGE'))) THEN

 SELECT array_agg(s.source_kind ORDER BY s.source_kind,s.source_id,s.source_version),
  array_agg(s.source_id ORDER BY s.source_kind,s.source_id,s.source_version),
  array_agg(s.source_version ORDER BY s.source_kind,s.source_id,s.source_version),
  count(*) BETWEEN 1 AND 100 AND bool_and(s.source_kind='application_field')
   AND bool_or(EXISTS(SELECT 1 FROM application_field_resources f WHERE f.workspace_id=w AND f.id=s.source_id
    AND f.origin='{"kind":"native","moduleKey":"native"}' AND f.type_key='memory' AND f.selection='history'))
 INTO direct_kinds,direct_ids,direct_versions,history_shape
 FROM session_messages message JOIN sessions session ON session.id=message.session_id AND session.workspace_id=message.workspace_id
 JOIN scope_derivations d ON d.workspace_id=message.workspace_id AND d.resource_kind='session_message'
  AND d.resource_id=message.id AND d.resource_version='1' AND d.user_id IS NOT DISTINCT FROM message.user_id
  AND d.assistant_id IS NOT DISTINCT FROM message.assistant_id AND d.sensitivity=message.sensitivity
  AND d.compartments=message.compartments AND d.project_ids=message.project_ids
 JOIN scope_derivation_sources s ON s.workspace_id=d.workspace_id AND s.derivation_id=d.id
 WHERE message.workspace_id=w AND message.id=i AND message.scope_version=1 AND message.scope_held IS FALSE;
 IF history_shape IS TRUE THEN
  IF EXISTS(SELECT 1 FROM application_scope_lineage(w,direct_kinds,direct_ids,direct_versions) n
   WHERE n.kind='session_context_revision' OR n.kind='session_message' AND n.id=i) THEN history_shape:=false;END IF;
  FOR direct_position IN 1..cardinality(direct_ids) LOOP
   IF NOT EXISTS(SELECT 1 FROM application_field_resources f WHERE f.workspace_id=w AND f.id=direct_ids[direct_position]
    AND f.origin='{"kind":"native","moduleKey":"native"}' AND f.type_key='memory' AND f.selection='history')
    AND EXISTS(SELECT 1 FROM application_scope_lineage(w,ARRAY[direct_kinds[direct_position]],ARRAY[direct_ids[direct_position]],ARRAY[direct_versions[direct_position]]) n
     JOIN application_field_resources f ON f.workspace_id=w AND f.id=n.id WHERE n.kind='application_field'
      AND f.origin='{"kind":"native","moduleKey":"native"}' AND f.type_key='memory' AND f.selection='history') THEN history_shape:=false;END IF;
  END LOOP;
 END IF;

  END IF;
  IF history_shape IS TRUE THEN
   BEGIN
    IF application_reader_envelope_visible(w,source) IS NOT TRUE THEN RETURN jsonb_build_object('memo',memo);END IF;
    FOR direct_position IN 1..cardinality(direct_ids) LOOP
     SELECT o.source_scope INTO immutable_scope FROM application_field_observations o
      WHERE o.workspace_id=w AND o.resource_id=direct_ids[direct_position] AND o.version=direct_versions[direct_position];
     IF immutable_scope IS NULL OR workflow_evidence_envelope_visible(w,immutable_scope) IS NOT TRUE
      OR sensitivity_rank(immutable_scope->>'sensitivity')>sensitivity_rank(source->>'sensitivity')
      OR NOT (source->'compartments')@>(immutable_scope->'compartments') OR NOT (source->'projectIds')@>(immutable_scope->'projectIds')
      OR immutable_scope->>'userId' IS NOT NULL AND immutable_scope->>'userId' IS DISTINCT FROM source->>'userId'
       AND (source->>'userId' IS NOT NULL OR immutable_scope->>'userId' IS DISTINCT FROM actor::text)
      THEN RETURN jsonb_build_object('memo',memo);END IF;
     IF EXISTS(SELECT 1 FROM application_field_resources f WHERE f.workspace_id=w AND f.id=direct_ids[direct_position]
      AND f.origin='{"kind":"native","moduleKey":"native"}' AND f.type_key='memory' AND f.selection='history') THEN
      projection:=read_native_attended_memory_evidence(w,ARRAY['application_field'],ARRAY[direct_ids[direct_position]],ARRAY[direct_versions[direct_position]]);
      IF projection IS NULL OR projection->>'purpose' IS DISTINCT FROM 'memory_history' OR projection->>'available' IS DISTINCT FROM 'true'
       OR projection->'root' IS DISTINCT FROM (immutable_scope||jsonb_build_object('resourceKind','application_field','resourceId',direct_ids[direct_position],'version',direct_versions[direct_position]))
       OR jsonb_typeof(projection->'scopes') IS DISTINCT FROM 'array' OR jsonb_array_length(projection->'scopes') NOT BETWEEN 1 AND 8192 THEN RETURN jsonb_build_object('memo',memo);END IF;
      FOR label IN SELECT value FROM jsonb_array_elements(projection->'scopes') LOOP
       IF workflow_evidence_envelope_visible(w,label) IS NOT TRUE THEN RETURN jsonb_build_object('memo',memo);END IF;
      END LOOP;
     ELSE
      -- Ordinary originals retain their stricter exact current-version check.
      checked:=application_session_eval_field(w,direct_ids[direct_position],direct_versions[direct_position],memo);
      memo:=coalesce(checked->'memo',memo);admitted:=checked->'value';
      IF admitted IS NULL OR admitted->>'held' IS DISTINCT FROM 'false' OR admitted->>'version' IS DISTINCT FROM direct_versions[direct_position]
       THEN RETURN jsonb_build_object('memo',memo);END IF;
     END IF;
    END LOOP;
    FOR dependency IN SELECT * FROM read_native_session_field_dependencies(w,direct_kinds,direct_ids,direct_versions) LOOP
     -- The helper admits the complete originals after metadata discovery.
     -- Transitive ordinary fields retain D1; their immutable tuple is not rewritten.
     IF dependency.source IS NULL OR dependency.source->>'resourceKind' IS DISTINCT FROM 'application_field'
      OR dependency.source->>'version' IS DISTINCT FROM dependency.node_version
      OR NOT EXISTS(SELECT 1 FROM application_field_observations o WHERE o.workspace_id=w
       AND o.resource_id=(dependency.source->>'resourceId')::uuid AND o.version=dependency.node_version)
      OR application_reader_envelope_visible(w,dependency.source) IS NOT TRUE THEN RETURN jsonb_build_object('memo',memo);END IF;
     seen:=seen||jsonb_build_array(jsonb_build_array(dependency.source->>'resourceId',dependency.node_version));
     IF jsonb_array_length(seen)>4096 THEN RETURN jsonb_build_object('memo',memo);END IF;
    END LOOP;
    FOR direct_position IN 1..cardinality(direct_ids) LOOP
     IF NOT seen @> jsonb_build_array(jsonb_build_array(direct_ids[direct_position]::text,direct_versions[direct_position])) THEN RETURN jsonb_build_object('memo',memo);END IF;
    END LOOP;
    FOR dependency IN SELECT * FROM read_external_source_dependencies(w,direct_kinds,direct_ids,direct_versions) LOOP
     admitted:=external_source_snapshot(w,(dependency.source->>'resourceId')::uuid);
     IF dependency.source IS NULL OR admitted IS NULL OR admitted->>'held' IS DISTINCT FROM 'false'
      OR dependency.source->>'version' IS DISTINCT FROM dependency.node_version OR admitted->>'version' IS DISTINCT FROM dependency.node_version
      OR application_reader_envelope_visible(w,dependency.source) IS NOT TRUE OR application_reader_envelope_visible(w,admitted) IS NOT TRUE
      THEN RETURN jsonb_build_object('memo',memo);END IF;
    END LOOP;
    IF read_admitted_native_scope_snapshot(w,'session_message',i) IS DISTINCT FROM source THEN RETURN jsonb_build_object('memo',memo);END IF;
   EXCEPTION WHEN insufficient_privilege THEN RETURN jsonb_build_object('memo',memo);END;
  ELSE
  checked:=application_session_eval_scope(w,'session_message',i,m.scope_version::text,memo);memo:=checked->'memo';
  IF checked->>'value' IS DISTINCT FROM 'true' THEN RETURN jsonb_build_object('memo',memo);END IF;
  END IF;
  SELECT jsonb_build_object('id',id,'role',role,'content',content,'sequenceNum',sequence_num,'createdAt',created_at,
   'senderUserId',sender_user_id,'senderAssistantId',sender_assistant_id,'channelMessageId',channel_message_id,'attachments',attachments) INTO values_json
   FROM session_messages WHERE workspace_id=w AND id=i AND scope_version=m.scope_version;
  IF values_json IS NULL THEN RETURN NULL;END IF;
  source_kind:='session_message';source_id:=i;
  -- Selected payload changes remain distinct even when an old native writer
  -- changed text without advancing its scope envelope version.
  record_version:=m.scope_version::text||':'||application_field_digest(values_json);
 ELSE
  SELECT r.* INTO revision FROM session_message_annotation_heads h JOIN session_context_scope_revisions r
   ON r.workspace_id=h.workspace_id AND r.id=h.scope_revision_id
   WHERE h.workspace_id=w AND h.session_id=m.session_id AND h.message_id=i AND r.parent_kind='message_annotation'
    AND r.parent_id=i AND r.session_id=m.session_id;
  IF NOT FOUND THEN RETURN NULL;END IF;
  checked:=application_session_eval_scope(w,'session_context_revision',revision.id,'1',memo);memo:=checked->'memo';
  IF checked->>'value' IS DISTINCT FROM 'true' THEN RETURN jsonb_build_object('memo',memo);END IF;
  source:=session_context_revision_native(w,revision.id);
  IF source IS NULL OR source->>'held' IS DISTINCT FROM 'false' THEN RETURN NULL;END IF;
  SELECT content INTO payload FROM session_context_revision_contents WHERE workspace_id=w AND revision_id=revision.id;
  IF payload IS NULL THEN RETURN NULL;END IF;
  values_json:=jsonb_build_object('id',i,'sequenceNum',m.sequence_num,'topicLabel',payload->'topicLabel',
   'topicConfidence',payload->'topicConfidence','replyToText',payload->'replyToText');
  source_kind:='session_context_revision';source_id:=revision.id;record_version:=revision.id::text;
 END IF;
 SELECT coalesce(jsonb_object_agg(key,value),'{}') INTO selected FROM jsonb_each(values_json) WHERE key=ANY(fields);
 RETURN jsonb_build_object('memo',memo,'value',jsonb_build_object('values',selected,'source',source,'recordVersion',record_version,
  'sourceKind',source_kind,'sourceId',source_id,'sourceVersion',source->>'version','ownerId',NULL,
  'fieldIdentity',application_field_digest(jsonb_build_object('kind','session_field_v1','type',t,'fields',fields)),
  'policyVersion',application_field_digest(jsonb_build_object('kind','session_field_v1','parent',parent->'fingerprint','fields',fields)),
  'references','[]'::jsonb));
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR numeric_value_out_of_range THEN RETURN NULL;
END

DECLARE candidate record;result jsonb;point jsonb;parent jsonb;candidates jsonb:='[]';points jsonb:='[]';policies jsonb:='[]';children jsonb:='[]';attempts integer:=0;
BEGIN
 parent:=application_session_query_parent(w,s);
 IF parent IS NULL OR through IS NULL OR through<0 OR application_session_field_keys(t) IS NULL OR fields IS NULL
  OR NOT fields<@application_session_field_keys(t) OR array_position(fields,NULL) IS NOT NULL
  OR cardinality(fields)<>(SELECT count(DISTINCT f) FROM unnest(fields) f)
  OR application_query_scope_valid(bounds) IS NOT TRUE OR jsonb_typeof(visibility) IS DISTINCT FROM 'object'
  OR visibility-ARRAY['userId','assistants']<>'{}' OR NOT visibility ?& ARRAY['userId','assistants'] THEN RETURN jsonb_build_object('memo',memo);END IF;
 FOR candidate IN SELECT id,sequence_num FROM session_messages WHERE workspace_id=w AND session_id=s AND sequence_num<=through ORDER BY sequence_num,id LOOP
  attempts:=attempts+1;IF attempts>4096 THEN RAISE EXCEPTION 'query_domain_complexity_unavailable' USING ERRCODE='42501';END IF;
  result:=application_session_eval_envelope(w,t,candidate.id,'query',fields,memo);memo:=coalesce(result->'memo',memo);point:=result->'value';
  IF point IS NULL OR point='null'::jsonb OR application_query_scope_admits_point(bounds,point->'source') IS NOT TRUE
   OR point#>>'{source,userId}' IS NOT NULL AND point#>>'{source,userId}' IS DISTINCT FROM visibility->>'userId'
   OR point#>>'{source,assistantId}' IS NOT NULL AND visibility->'assistants'<>'null'::jsonb
    AND NOT coalesce(visibility->'assistants' ? (point#>>'{source,assistantId}'),false) THEN CONTINUE;END IF;
  candidates:=candidates||jsonb_build_array(jsonb_build_object('id',candidate.id,'version',point#>'{state,recordVersion}'));
  points:=points||jsonb_build_array(jsonb_build_object('id',candidate.id,'version',point#>'{state,recordVersion}','fields',fields,'source',point->'source'));
  policies:=policies||jsonb_build_array(jsonb_build_object('id',candidate.id,'policy',point#>'{state,policyVersion}'));
  children:=children||jsonb_build_array(point);
 END LOOP;
 RETURN jsonb_build_object('memo',memo,'value',jsonb_build_object('parent',parent,'candidates',candidates,'points',points,'policies',policies),'children',children);
END

DECLARE key text:='native:'||k||':'||i||':'||v;nodes jsonb;node jsonb;refs jsonb:='[]';current_source jsonb;result jsonb;dependency record;policy jsonb;mask jsonb;type_key text;
BEGIN
 IF memo#>>ARRAY[key,'busy']='true' THEN RETURN jsonb_build_object('value',false,'memo',memo);END IF;
 -- Only this evaluator consumes the extended namespace. The unchanged
 -- native-root snapshot evaluator cannot consume these completed entries.
 IF memo ? ('empty-'||key) THEN
  IF memo ? 'emptyQueries' THEN
   IF application_empty_query_helpers_current() IS TRUE THEN
    IF application_empty_query_worklist_current(w,memo) THEN
     RETURN jsonb_build_object('value',memo#>ARRAY['empty-'||key,'value']='true'::jsonb
      AND application_session_eval_sources_current(w,memo#>ARRAY['empty-'||key,'external']),'memo',memo);
    END IF;
   END IF;
  END IF;
  memo:=(SELECT coalesce(jsonb_object_agg(entry.key,entry.value),'{}') FROM jsonb_each(memo) entry WHERE entry.value->>'busy'='true' OR entry.key='memoryStatement');
 END IF;
 IF memo ? 'emptyQueries' AND (SELECT count(*) FROM jsonb_object_keys(memo-'memoryStatement'-'emptyQueries'))
  +(SELECT count(*) FROM jsonb_object_keys(memo->'emptyQueries'))>=4096 THEN memo:=(SELECT coalesce(jsonb_object_agg(entry.key,entry.value),'{}') FROM jsonb_each(memo) entry WHERE entry.value->>'busy'='true' OR entry.key='memoryStatement'); END IF;
 IF memo ? key THEN
  IF memo#>>ARRAY[key,'busy']='true' THEN RETURN jsonb_build_object('value',false,'memo',memo);END IF;
  RETURN jsonb_build_object('value',memo#>ARRAY[key,'value']='true'::jsonb AND application_session_eval_sources_current(w,memo#>ARRAY[key,'external']),'memo',memo);
 END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(memo-'memoryStatement'))>=4096 THEN RETURN jsonb_build_object('value',false,'memo',memo);END IF;
 memo:=memo||jsonb_build_object(key,jsonb_build_object('busy',true));
 SELECT coalesce(jsonb_agg(to_jsonb(n)),'[]') INTO nodes FROM application_scope_lineage(w,ARRAY[k],ARRAY[i],ARRAY[v]) n;
 FOR node IN SELECT value FROM jsonb_array_elements(nodes) ORDER BY value->>'kind',value->>'id',value->>'version' LOOP
  IF node->>'kind'='application_field' THEN
   result:=application_session_eval_field(w,(node->>'id')::uuid,node->>'version',memo);memo:=result->'memo';current_source:=result->'value';
   refs:=refs||coalesce(memo#>ARRAY['field:'||(node->>'id')||':'||(node->>'version'),'external'],'[]'::jsonb);
   IF current_source IS NULL OR current_source->>'held' IS DISTINCT FROM 'false' THEN RETURN jsonb_build_object('value',false,'memo',memo);END IF;
  ELSIF node->>'kind'='external_source' THEN
   refs:=refs||jsonb_build_array(jsonb_build_object('id',node->'id','version',node->'version'));
   current_source:=external_source_snapshot(w,(node->>'id')::uuid);
   IF current_source IS NULL OR current_source->>'held' IS DISTINCT FROM 'false' OR current_source->>'version' IS DISTINCT FROM node->>'version' THEN
    RETURN jsonb_build_object('value',false,'memo',memo);END IF;
  ELSIF scope_source_table(node->>'kind') IS NOT NULL THEN
   IF node->>'kind'='session_context_revision' AND read_entity_derivation_source(w,node->>'kind',(node->>'id')::uuid) IS NULL THEN
    RETURN jsonb_build_object('value',false,'memo',memo);END IF;
   current_source:=read_admitted_native_scope_snapshot(w,node->>'kind',(node->>'id')::uuid);
   IF node->>'kind' IN('crm_event','session_context_revision') AND current_source IS NULL
    OR current_source IS NOT NULL AND current_source->>'held' IS DISTINCT FROM 'false' THEN RETURN jsonb_build_object('value',false,'memo',memo);END IF;
  END IF;
 END LOOP;
 FOR dependency IN SELECT DISTINCT d.* FROM scope_derivations d JOIN jsonb_array_elements(nodes) ancestor(value)
  ON d.resource_kind=ancestor.value->>'kind' AND d.resource_id=(ancestor.value->>'id')::uuid WHERE d.workspace_id=w LOOP
  IF nullif(current_setting('app.application_id',true),'') IS NOT NULL OR workflow_evidence_envelope_visible(w,jsonb_build_object('workspaceId',w,
   'userId',dependency.user_id,'assistantId',dependency.assistant_id,'sensitivity',dependency.sensitivity,
   'compartments',dependency.compartments,'projectIds',dependency.project_ids)) IS NOT TRUE THEN RETURN jsonb_build_object('value',false,'memo',memo);END IF;
 END LOOP;
 -- An explicit raw entity source consumes the complete current field mask,
 -- unlike the selected native anchors of a field projection.
 FOR dependency IN SELECT DISTINCT edge.source_id FROM scope_derivation_sources edge JOIN scope_derivations d
  ON d.workspace_id=edge.workspace_id AND d.id=edge.derivation_id JOIN jsonb_array_elements(nodes) ancestor(value)
  ON d.resource_kind=ancestor.value->>'kind' AND d.resource_id=(ancestor.value->>'id')::uuid
  WHERE d.workspace_id=w AND edge.source_kind='entity' LOOP
  SELECT kind INTO type_key FROM entities WHERE workspace_id=w AND id=dependency.source_id;
  IF NOT FOUND OR type_key NOT IN('company','person','deal') THEN CONTINUE;END IF;
  policy:=application_native_field_contract_for(w,'{"kind":"native","moduleKey":"native"}',type_key,dependency.source_id::text);
  IF policy->>'registered' IS DISTINCT FROM 'false' THEN
   mask:=application_current_native_field_policy(w,'{"kind":"native","moduleKey":"native"}',type_key,dependency.source_id);
   IF policy->>'registered' IS DISTINCT FROM 'true' OR policy->>'held' IS DISTINCT FROM 'false' OR mask->>'held' IS DISTINCT FROM 'false'
    OR NOT coalesce(policy#>'{metadata,fieldKeys}'<@(mask->'readFields'),false) THEN RETURN jsonb_build_object('value',false,'memo',memo);END IF;
  END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(value ORDER BY value::text),'[]') INTO refs FROM (SELECT DISTINCT value FROM jsonb_array_elements(refs)) unique_refs;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>'id')::uuid
  WHERE n->>'kind'='application_field' AND (f.origin<>'{"kind":"native","moduleKey":"native"}'::jsonb
   OR (f.type_key NOT IN('session_message','session_message_annotation')
    AND NOT(f.type_key='memory' AND coalesce(memo#>>'{memoryStatement,workspaceId}'=w::text,false))))) THEN
  memo:=memo-key;
  IF memo ? 'emptyQueries' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>'id')::uuid
   WHERE n->>'kind'='application_field' AND NOT coalesce(memo->'emptyQueries' ? ((n->>'id')||':'||(n->>'version')),false)
    AND(f.origin<>'{"kind":"native","moduleKey":"native"}'::jsonb OR(f.type_key NOT IN('session_message','session_message_annotation')
     AND NOT(f.type_key='memory' AND coalesce(memo#>>'{memoryStatement,workspaceId}'=w::text,false))))) THEN
   memo:=memo||jsonb_build_object('empty-'||key,jsonb_build_object('value',true,'external',refs));
  END IF;
 ELSE memo:=memo||jsonb_build_object(key,jsonb_build_object('value',true,'external',refs)); END IF;RETURN jsonb_build_object('value',true,'memo',memo);
END

DECLARE key text:='native:'||k||':'||i||':'||v;nodes jsonb;node jsonb;refs jsonb:='[]';current_source jsonb;result jsonb;dependency record;policy jsonb;mask jsonb;type_key text;root_current jsonb;
BEGIN
 IF memo ? key THEN
  IF memo#>>ARRAY[key,'busy']='true' THEN RETURN jsonb_build_object('value',false,'memo',memo);END IF;
  result:=jsonb_build_object('value',memo#>ARRAY[key,'value']='true'::jsonb AND application_session_eval_sources_current(w,memo#>ARRAY[key,'external']),'memo',memo);
  IF result->>'value'='true' THEN
   -- A worklist hit still performs its current canonical native-root read.
   RETURN result||jsonb_build_object('current',read_admitted_native_scope_snapshot(w,k,i));
  END IF;
  RETURN result;
 END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(memo))>=4096 THEN RETURN jsonb_build_object('value',false,'memo',memo);END IF;
 memo:=memo||jsonb_build_object(key,jsonb_build_object('busy',true));
 SELECT coalesce(jsonb_agg(to_jsonb(n)),'[]') INTO nodes FROM application_scope_lineage(w,ARRAY[k],ARRAY[i],ARRAY[v]) n;
 FOR node IN SELECT value FROM jsonb_array_elements(nodes) ORDER BY value->>'kind',value->>'id',value->>'version' LOOP
  IF node->>'kind'='application_field' THEN
   result:=application_session_eval_field(w,(node->>'id')::uuid,node->>'version',memo);memo:=result->'memo';current_source:=result->'value';
   refs:=refs||coalesce(memo#>ARRAY['field:'||(node->>'id')||':'||(node->>'version'),'external'],'[]'::jsonb);
   IF current_source IS NULL OR current_source->>'held' IS DISTINCT FROM 'false' THEN RETURN jsonb_build_object('value',false,'memo',memo);END IF;
  ELSIF node->>'kind'='external_source' THEN
   refs:=refs||jsonb_build_array(jsonb_build_object('id',node->'id','version',node->'version'));
   current_source:=external_source_snapshot(w,(node->>'id')::uuid);
   IF current_source IS NULL OR current_source->>'held' IS DISTINCT FROM 'false' OR current_source->>'version' IS DISTINCT FROM node->>'version' THEN
    RETURN jsonb_build_object('value',false,'memo',memo);END IF;
  ELSIF scope_source_table(node->>'kind') IS NOT NULL THEN
   IF node->>'kind'='session_context_revision' AND read_entity_derivation_source(w,node->>'kind',(node->>'id')::uuid) IS NULL THEN
    RETURN jsonb_build_object('value',false,'memo',memo);END IF;
   current_source:=read_admitted_native_scope_snapshot(w,node->>'kind',(node->>'id')::uuid);
   IF node->>'kind' IN('crm_event','session_context_revision') AND current_source IS NULL
    OR current_source IS NOT NULL AND current_source->>'held' IS DISTINCT FROM 'false' THEN RETURN jsonb_build_object('value',false,'memo',memo);END IF;
   IF node->>'kind'=k AND (node->>'id')::uuid=i THEN root_current:=current_source;END IF;
  END IF;
 END LOOP;
 FOR dependency IN SELECT DISTINCT d.* FROM scope_derivations d JOIN jsonb_array_elements(nodes) ancestor(value)
  ON d.resource_kind=ancestor.value->>'kind' AND d.resource_id=(ancestor.value->>'id')::uuid WHERE d.workspace_id=w LOOP
  IF nullif(current_setting('app.application_id',true),'') IS NOT NULL OR workflow_evidence_envelope_visible(w,jsonb_build_object('workspaceId',w,
   'userId',dependency.user_id,'assistantId',dependency.assistant_id,'sensitivity',dependency.sensitivity,
   'compartments',dependency.compartments,'projectIds',dependency.project_ids)) IS NOT TRUE THEN RETURN jsonb_build_object('value',false,'memo',memo);END IF;
 END LOOP;
 -- An explicit raw entity source consumes the complete current field mask,
 -- unlike the selected native anchors of a field projection.
 FOR dependency IN SELECT DISTINCT edge.source_id FROM scope_derivation_sources edge JOIN scope_derivations d
  ON d.workspace_id=edge.workspace_id AND d.id=edge.derivation_id JOIN jsonb_array_elements(nodes) ancestor(value)
  ON d.resource_kind=ancestor.value->>'kind' AND d.resource_id=(ancestor.value->>'id')::uuid
  WHERE d.workspace_id=w AND edge.source_kind='entity' LOOP
  SELECT kind INTO type_key FROM entities WHERE workspace_id=w AND id=dependency.source_id;
  IF NOT FOUND OR type_key NOT IN('company','person','deal') THEN CONTINUE;END IF;
  policy:=application_native_field_contract_for(w,'{"kind":"native","moduleKey":"native"}',type_key,dependency.source_id::text);
  IF policy->>'registered' IS DISTINCT FROM 'false' THEN
   mask:=application_current_native_field_policy(w,'{"kind":"native","moduleKey":"native"}',type_key,dependency.source_id);
   IF policy->>'registered' IS DISTINCT FROM 'true' OR policy->>'held' IS DISTINCT FROM 'false' OR mask->>'held' IS DISTINCT FROM 'false'
    OR NOT coalesce(policy#>'{metadata,fieldKeys}'<@(mask->'readFields'),false) THEN RETURN jsonb_build_object('value',false,'memo',memo);END IF;
  END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(value ORDER BY value::text),'[]') INTO refs FROM (SELECT DISTINCT value FROM jsonb_array_elements(refs)) unique_refs;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>'id')::uuid
  WHERE n->>'kind'='application_field' AND (f.origin<>'{"kind":"native","moduleKey":"native"}'::jsonb OR f.type_key NOT IN('session_message','session_message_annotation'))) THEN
  memo:=memo-key;
 ELSE memo:=memo||jsonb_build_object(key,jsonb_build_object('value',true,'external',refs)); END IF;RETURN jsonb_build_object('value',true,'memo',memo,'current',root_current);
END

DECLARE bounds jsonb;
BEGIN
 bounds:=application_native_query_bounds(w);
 IF bounds IS NULL THEN
  -- This is the already-admitted real personal guest session's scope, not
  -- a workspace/General fallback for an unknown principal or missing source.
  IF parent IS NULL OR parent#>>'{scope,userId}' IS DISTINCT FROM nullif(current_setting('app.current_user_id',true),'')
   OR parent#>>'{scope,sensitivity}' IS DISTINCT FROM 'public' THEN RETURN NULL;END IF;
  bounds:=application_query_scope_cap(sensitivity_rank(parent#>>'{scope,sensitivity}'),parent#>'{scope,compartments}',parent#>'{scope,projectIds}');
 END IF;
 IF application_query_scope_valid(bounds) IS NOT TRUE THEN RETURN NULL;END IF;RETURN bounds;
END

DECLARE parent jsonb;binding jsonb;
BEGIN
 parent:=session_context_parent_snapshot(w,s);
 IF parent IS NULL OR workflow_evidence_envelope_visible(w,parent) IS NOT TRUE THEN RETURN NULL;END IF;
 SELECT jsonb_build_object('id',id,'workspaceId',workspace_id,'assistantId',assistant_id,'userId',user_id,
  'visibility',visibility,'anchorKind',anchor_kind,'anchorRef',anchor_ref,'mode',mode,'channelType',channel_type,
  'channelId',channel_id,'appId',app_id,'contextGroupId',context_group_id,'contextProjectId',context_project_id,
  'contextCompartments',context_compartments,'effectiveClearance',effective_clearance) INTO binding
  FROM sessions WHERE workspace_id=w AND id=s;
 IF binding IS NULL THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('scope',parent-ARRAY['assistant','createdBy'],'fingerprint',application_field_digest(binding));
END

' THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 IF nullif(current_setting('app.current_user_id',true),'') IS NULL OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='session_messages'::regclass WHERE r.rolname=session_user
  AND(r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,'USAGE'))) THEN RAISE EXCEPTION 'access_unavailable' USING ERRCODE='42501';END IF;
 -- Cohorts are separate evidence floors in one physical capture. Their shared
 -- graph is evaluated once; membership never widens either returned floor.
 IF cohorts IS NOT NULL THEN
  IF roots IS NOT NULL OR authority IS NOT NULL OR jsonb_typeof(cohorts) IS DISTINCT FROM 'array'
   OR jsonb_array_length(cohorts)<>2 THEN RAISE EXCEPTION 'invalid_scope_source' USING ERRCODE='22023';END IF;
  FOR groups IN SELECT value FROM jsonb_array_elements(cohorts) LOOP
   IF jsonb_typeof(groups) IS DISTINCT FROM 'array' OR jsonb_array_length(groups) NOT BETWEEN 1 AND 4096
   THEN RAISE EXCEPTION 'invalid_scope_source' USING ERRCODE='22023';END IF;
  END LOOP;
  SELECT jsonb_agg(DISTINCT item.node) INTO roots FROM jsonb_array_elements(cohorts) g CROSS JOIN jsonb_array_elements(g) item(node);
 END IF;
 IF jsonb_typeof(roots) IS DISTINCT FROM 'array' OR jsonb_array_length(roots) NOT BETWEEN 1 AND 4096 THEN RETURN NULL;END IF;
 groups:=coalesce(cohorts,jsonb_build_array(roots));
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(roots) AS input(root) WHERE jsonb_typeof(input.root) IS DISTINCT FROM 'object' OR input.root-ARRAY['kind','id','version']<>'{}'
  OR NOT input.root ?& ARRAY['kind','id','version'] OR jsonb_typeof(input.root->'kind') IS DISTINCT FROM 'string'
  OR jsonb_typeof(input.root->'version') IS DISTINCT FROM 'string' OR length(input.root->>'version') NOT BETWEEN 1 AND 256
  OR jsonb_typeof(input.root->'id') IS DISTINCT FROM 'string' OR NOT pg_input_is_valid(input.root->>'id','uuid')) THEN RAISE EXCEPTION 'invalid_scope_source' USING ERRCODE='22023';END IF;
 -- Query-domain identities are internal dependencies, never source roots.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(roots) root WHERE root->>'kind'='application_query_domain') THEN RETURN NULL;END IF;
 -- Source-family readers lock their native rows. Fence policy changes once
 -- across acquisition, without treating an uncommitted administrative lock as denial.
 SELECT jsonb_build_array(c.revision,p.revision) INTO policy_revision
  FROM application_policy_contract_epoch c CROSS JOIN application_policy_workspace_epochs p
  WHERE c.singleton AND p.workspace_id=w;
 IF NOT FOUND THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 context:=native_turn_context();
 WITH RECURSIVE closure(cohort,kind,id,version) AS(
  SELECT g.position,r->>'kind',(r->>'id')::uuid,r->>'version'
   FROM jsonb_array_elements(groups) WITH ORDINALITY g(roots,position) CROSS JOIN jsonb_array_elements(g.roots) r
  UNION SELECT c.cohort,e.kind,e.id,e.version FROM closure c CROSS JOIN LATERAL conversation_source_edges(w,c.kind,c.id,c.version) e
 ) SELECT coalesce(jsonb_agg(to_jsonb(c)),'[]') INTO membership FROM(SELECT * FROM closure LIMIT CASE WHEN cohorts IS NULL THEN 4097 ELSE 8193 END) c;
 IF jsonb_array_length(membership)>8192 THEN RAISE EXCEPTION 'scope_ancestry_unavailable' USING ERRCODE='42501';END IF;
 SELECT coalesce(jsonb_agg(DISTINCT member.node-'cohort'),'[]') INTO physical FROM jsonb_array_elements(membership) member(node);
 IF jsonb_array_length(physical)>4096 THEN RAISE EXCEPTION 'scope_ancestry_unavailable' USING ERRCODE='42501';END IF;
 IF cohorts IS NULL AND jsonb_array_length(roots)=1 AND EXISTS(SELECT 1 FROM application_field_resources f WHERE f.workspace_id=w AND f.id=(roots->0->>'id')::uuid
  AND roots->0->>'kind'='application_field' AND f.origin='{"kind":"native","moduleKey":"native"}' AND f.type_key='memory' AND f.selection='history') THEN
  RETURN read_native_attended_memory_evidence(w,ARRAY['application_field'],ARRAY[(roots->0->>'id')::uuid],ARRAY[roots->0->>'version']);
 END IF;
 -- Separate purpose/family adapters own independent source receipts and Memory
 -- history qualification. This operation does not speculate through those APIs.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(physical) x WHERE x->>'kind' NOT IN('application_field','application_query_domain','session_message','session_context_revision','memory','workspace_file','episode','recording','private_transcript'))
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(physical) x JOIN application_field_resources f ON f.workspace_id=w AND f.id=(x->>'id')::uuid
   WHERE x->>'kind'='application_field' AND (f.origin IS DISTINCT FROM '{"kind":"native","moduleKey":"native"}'::jsonb
    OR f.type_key NOT IN('session_message','session_message_annotation','memory') OR f.type_key='memory' AND f.selection='history'))
 THEN RETURN NULL;END IF;
 -- Stored result ancestry omits source-denied semantic candidates. Preserve
 -- the Memory family's complete-current-cohort discovery before claiming a
 -- native proof; metadata alone cannot substitute for external admission.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(physical) x JOIN application_field_resources f
  ON f.workspace_id=w AND f.id=(x->>'id')::uuid WHERE x->>'kind'='application_field'
  AND f.origin='{"kind":"native","moduleKey":"native"}' AND f.type_key='memory' AND f.selection='query_domain') THEN
  -- The canonical closure already owns ancestry. The old cohort facade
  -- walked it again through a 100-root API and refused larger valid captures.
  FOR selector IN SELECT DISTINCT q.domain FROM jsonb_to_recordset(physical) n(kind text,id uuid,version text)
   JOIN application_field_resources f ON f.workspace_id=w AND f.id=n.id AND n.kind='application_field'
   JOIN application_field_observations o ON o.workspace_id=w AND o.resource_id=f.id AND o.version=n.version
   JOIN application_query_domains q ON q.workspace_id=w AND q.id=f.resource_id AND q.type_key=f.type_key AND q.origin=f.origin
   WHERE f.origin='{"kind":"native","moduleKey":"native"}' AND f.type_key='memory' AND f.selection='query_domain' LOOP
   IF selector.domain->>'kind' IS DISTINCT FROM 'memory_query_domain_v1' OR application_query_scope_valid(selector.domain->'bounds') IS NOT TRUE
   THEN RAISE EXCEPTION 'scope_ancestry_unavailable' USING ERRCODE='22023';END IF;
   IF selector.domain->>'includeRetained' IS DISTINCT FROM 'true' THEN CONTINUE;END IF;
   FOR candidate IN SELECT id FROM memories WHERE workspace_id=w ORDER BY id LOOP
    attempts:=attempts+1;IF attempts>4096 THEN RAISE EXCEPTION 'scope_ancestry_unavailable' USING ERRCODE='22023';END IF;
    source:=read_scope_source(w,'memory',candidate.id);
    IF source IS NULL OR source->>'held' IS DISTINCT FROM 'false' OR application_query_scope_admits_point(selector.domain->'bounds',source) IS NOT TRUE THEN CONTINUE;END IF;
    candidate_sources:=candidate_sources||jsonb_build_array(jsonb_build_object('kind','memory','id',candidate.id,'version',source->'version'));
   END LOOP;
  END LOOP;
  FOR dependency IN SELECT array_agg(cohort_source.node->>'kind') kinds,
   array_agg((cohort_source.node->>'id')::uuid) ids,array_agg(cohort_source.node->>'version') versions
   FROM jsonb_array_elements(candidate_sources) WITH ORDINALITY cohort_source(node,ord)
   GROUP BY (cohort_source.ord-1)/100 LOOP
   IF EXISTS(SELECT 1 FROM read_external_source_dependencies(w,dependency.kinds,dependency.ids,dependency.versions)) THEN RETURN NULL;END IF;
  END LOOP;
 END IF;
 memo:=conversation_dag(w,roots,'[]');
 -- A denied semantic query candidate can become readable through an independent
 -- source. Its coordinator must reevaluate that complete candidate cohort.
 IF memo->>'hasExternal'='true' OR memo->>'recordingEligible' IS DISTINCT FROM 'true' THEN RETURN NULL;END IF;
 FOR cohort IN 1..jsonb_array_length(groups) LOOP
 immutable:='[]';currents:='[]';
 FOR n IN SELECT x-'cohort' FROM jsonb_array_elements(membership) x WHERE (x->>'cohort')::integer=cohort LOOP
  IF n->>'kind'='application_query_domain' THEN CONTINUE;END IF;
  IF n->>'kind'='application_field' THEN
   source:=memo#>ARRAY['field:'||(n->>'id')||':'||(n->>'version'),'value'];
   IF source IS NULL OR source->>'held' IS DISTINCT FROM 'false' THEN RETURN jsonb_build_object('admitted',false);END IF;
   SELECT * INTO STRICT observation FROM application_field_observations WHERE workspace_id=w AND resource_id=(n->>'id')::uuid AND version=n->>'version';
   immutable:=immutable||jsonb_build_array(observation.source_scope||jsonb_build_object('resourceKind','application_field','resourceId',observation.resource_id,'version',observation.version));
  ELSE
   IF memo#>>ARRAY['native:'||(n->>'kind')||':'||(n->>'id')||':'||(n->>'version'),'value'] IS DISTINCT FROM 'true' THEN RETURN jsonb_build_object('admitted',false);END IF;
   source:=memo#>ARRAY['current',(n->>'kind')||':'||(n->>'id')||':'||(n->>'version')];
   IF source IS NULL OR source='null'::jsonb THEN CONTINUE;END IF;
   source:=jsonb_build_object('workspaceId',w,'userId',source->'userId','assistantId',source->'assistantId','sensitivity',source->'sensitivity',
    'compartments',source->'compartments','projectIds',source->'projectIds','resourceKind',n->'kind','resourceId',n->'id','version',source->'version');
   IF n->>'kind'='session_context_revision' THEN
    IF source->>'version' IS DISTINCT FROM n->>'version' THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
    immutable:=immutable||jsonb_build_array(source);
   END IF;
  END IF;
  currents:=currents||jsonb_build_array(source-ARRAY['held','validTo','retractedAt']);
 END LOOP;
 proofs:=proofs||jsonb_build_array(jsonb_build_object('immutable',immutable,'current',currents));
 END LOOP;
 IF authority IS NOT NULL THEN
  IF jsonb_typeof(authority) IS DISTINCT FROM 'array' OR jsonb_array_length(authority)<>9
   OR authority->>0 IS DISTINCT FROM w::text OR authority->>1 IS DISTINCT FROM nullif(current_setting('app.current_user_id',true),'')
  THEN RAISE EXCEPTION 'access_unavailable' USING ERRCODE='42501';END IF;
  authority_facts:=read_session_authority_facts((authority->>0)::uuid,(authority->>1)::uuid,(authority->>2)::uuid,(authority->>3)::uuid,
    (authority->>4)::uuid,(authority->>5)::integer,(authority->>6)::uuid,(authority->>7)::boolean,(authority->>8)::boolean);
 END IF;
 IF (SELECT encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') FROM pg_proc p WHERE p.oid='native_turn_helpers_current()'::regprocedure)
  IS DISTINCT FROM '

' THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 IF native_turn_helpers_current() IS NOT TRUE OR native_turn_context() IS DISTINCT FROM context
  OR policy_revision IS DISTINCT FROM (SELECT jsonb_build_array(c.revision,p.revision) FROM application_policy_contract_epoch c
   CROSS JOIN application_policy_workspace_epochs p WHERE c.singleton AND p.workspace_id=w)
  OR clock_timestamp()>=(memo->>'validUntil')::timestamptz THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;

 RETURN jsonb_build_object('admitted',true)||CASE WHEN cohorts IS NULL THEN proofs->0 ELSE jsonb_build_object('cohorts',proofs) END
  ||CASE WHEN authority IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('authority',authority_facts) END;
END

DECLARE parent jsonb;bounds jsonb;visibility jsonb;context jsonb;memo jsonb;scanned jsonb;captured jsonb;
 selections jsonb;initial jsonb;fresh jsonb;fields text[];selection jsonb;pass integer;frozen application_query_domains;
 actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
BEGIN
 IF actor IS NULL OR body_through IS NULL AND topics_through IS NULL OR body_through<0 OR topics_through<0
  OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='public.session_messages'::regclass WHERE r.rolname=session_user
   AND(r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,'USAGE')))
 THEN RAISE EXCEPTION 'access_unavailable' USING ERRCODE='42501';END IF;
 IF (SELECT encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') FROM pg_proc p WHERE p.oid='native_turn_helpers_current()'::regprocedure)
  IS DISTINCT FROM '

' THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 context:=native_turn_context();
 selections:=jsonb_build_array(jsonb_build_object('type','session_message','through',body_through,'sessionId',s),
  jsonb_build_object('type','session_message_annotation','through',topics_through,'sessionId',s));
 FOR pass IN 1..2 LOOP
  parent:=application_session_query_parent(w,s);bounds:=application_session_query_bounds(w,parent);
  IF parent IS NULL OR bounds IS NULL THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
  visibility:=jsonb_build_object('userId',CASE WHEN current_setting('app.agent_shared_audience',true)='true' THEN NULL ELSE actor END,
   'assistants',coalesce(nullif(current_setting('app.agent_visibility_assistants',true),'')::jsonb,'null'::jsonb));
  memo:=conversation_dag(w,'[]',(SELECT jsonb_agg(value) FROM jsonb_array_elements(selections) WHERE value->>'through' IS NOT NULL));fresh:='[]';
  FOR selection IN SELECT value FROM jsonb_array_elements(selections) WHERE value->>'through' IS NOT NULL LOOP
   fields:=ARRAY(SELECT field FROM unnest(application_session_field_keys(selection->>'type')) field ORDER BY field);
   scanned:=capture_conversation_selection(w,s,selection->>'type',(selection->>'through')::integer,fields,bounds,visibility,memo);
   memo:=scanned->'memo';
   IF scanned->'value' IS NULL THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
   captured:=native_turn_build_query_capture(w,s,selection->>'type',(selection->>'through')::integer,fields,parent,bounds,visibility,scanned);
   IF recording_source_read_allowed(w,'application_field',(captured#>>'{envelope,resourceId}')::uuid) IS NOT TRUE
    OR scope_review_state_held('application_field',(captured#>>'{envelope,resourceId}')::uuid)
   THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
   fresh:=fresh||jsonb_build_array(captured);
  END LOOP;
  IF pass=1 THEN
   initial:=fresh;
   FOR captured IN SELECT value FROM jsonb_array_elements(initial) LOOP
    INSERT INTO application_query_domains(id,workspace_id,origin,type_key,schema_version,domain,identity)
     VALUES((captured->>'domainId')::uuid,w,'{"kind":"native","moduleKey":"native"}',captured->>'type','1',captured->'domain',captured->>'domainIdentity') ON CONFLICT DO NOTHING;
    SELECT * INTO frozen FROM application_query_domains WHERE workspace_id=w AND id=(captured->>'domainId')::uuid;
    IF NOT FOUND OR (frozen.origin,frozen.type_key,frozen.schema_version,frozen.domain,frozen.identity) IS DISTINCT FROM
     ('{"kind":"native","moduleKey":"native"}'::jsonb,captured->>'type','1',captured->'domain',captured->>'domainIdentity')
    THEN RAISE EXCEPTION 'scope_evidence_immutable' USING ERRCODE='22023';END IF;
    PERFORM application_materialize_field_envelope(w,captured->'envelope');
   END LOOP;
  ELSIF fresh IS DISTINCT FROM initial THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 END LOOP;
 IF (SELECT encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') FROM pg_proc p WHERE p.oid='native_turn_helpers_current()'::regprocedure)
  IS DISTINCT FROM '

' THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 IF native_turn_helpers_current() IS NOT TRUE OR native_turn_context() IS DISTINCT FROM context
 THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 IF clock_timestamp()>=(memo->>'validUntil')::timestamptz THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('history',coalesce((SELECT c->'rows' FROM jsonb_array_elements(initial) c WHERE c->>'type'='session_message'),'[]'::jsonb),
  'annotations',coalesce((SELECT c->'rows' FROM jsonb_array_elements(initial) c WHERE c->>'type'='session_message_annotation'),'[]'::jsonb));
END

DECLARE candidate record;result jsonb;point jsonb;parent jsonb;candidates jsonb:='[]';points jsonb:='[]';policies jsonb:='[]';children jsonb:='[]';attempts integer:=0;resource uuid;field_identity text;
BEGIN
 parent:=application_session_query_parent(w,s);
 IF parent IS NULL OR through IS NULL OR through<0 OR application_session_field_keys(t) IS NULL OR fields IS NULL
  OR NOT fields<@application_session_field_keys(t) OR array_position(fields,NULL) IS NOT NULL
  OR cardinality(fields)<>(SELECT count(DISTINCT f) FROM unnest(fields) f)
  OR application_query_scope_valid(bounds) IS NOT TRUE OR jsonb_typeof(visibility) IS DISTINCT FROM 'object'
  OR visibility-ARRAY['userId','assistants']<>'{}' OR NOT visibility ?& ARRAY['userId','assistants'] THEN RETURN jsonb_build_object('memo',memo);END IF;
 IF (SELECT count(*) FROM(SELECT 1 FROM session_messages WHERE workspace_id=w AND session_id=s AND sequence_num<=through LIMIT 4097) candidates)>4096
 THEN RAISE EXCEPTION 'query_domain_complexity_unavailable' USING ERRCODE='42501';END IF;
 -- The graph admits complete all-version privacy before selecting any point payload.
 FOR candidate IN SELECT id,sequence_num FROM session_messages WHERE workspace_id=w AND session_id=s AND sequence_num<=through ORDER BY sequence_num,id
 LOOP
  attempts:=attempts+1;IF attempts>4096 THEN RAISE EXCEPTION 'query_domain_complexity_unavailable' USING ERRCODE='42501';END IF;
  point:=memo#>ARRAY['envelopes',jsonb_build_array(t,candidate.id,fields)::text];
  IF point IS NULL OR point='null'::jsonb OR application_query_scope_admits_point(bounds,point->'source') IS NOT TRUE
   OR point#>>'{source,userId}' IS NOT NULL AND point#>>'{source,userId}' IS DISTINCT FROM visibility->>'userId'
   OR point#>>'{source,assistantId}' IS NOT NULL AND visibility->'assistants'<>'null'::jsonb
    AND NOT coalesce(visibility->'assistants' ? (point#>>'{source,assistantId}'),false) THEN CONTINUE;END IF;
  candidates:=candidates||jsonb_build_array(jsonb_build_object('id',candidate.id,'version',point#>'{state,recordVersion}'));
  points:=points||jsonb_build_array(jsonb_build_object('id',candidate.id,'version',point#>'{state,recordVersion}','fields',fields,'source',point->'source'));
  policies:=policies||jsonb_build_array(jsonb_build_object('id',candidate.id,'policy',point#>'{state,policyVersion}'));
  children:=children||jsonb_build_array(point);
 END LOOP;
 RETURN jsonb_build_object('memo',memo,'value',jsonb_build_object('parent',parent,'candidates',candidates,'points',points,'policies',policies),'children',children);
END

DECLARE parent jsonb;bounds jsonb;visibility jsonb;scanned jsonb;fields text[];domain jsonb;identity_value text;domain_id uuid;
 frozen application_query_domains;envelope jsonb;child jsonb;source jsonb;external jsonb;result jsonb;memo jsonb:='{}';
 ids uuid[];versions text[];snap record;expected jsonb;captures jsonb;rows_json jsonb:='[]';position integer:=0;
 actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
 frame_kinds text[];frame_ids uuid[];frame_versions text[];frame_nodes jsonb;frame_result jsonb;
 frame_ancestry boolean:=false;frame_point jsonb;frame_root jsonb;frame_tuple jsonb;frame_actual jsonb;
 frame_kind text;frame_id uuid;frame_version text;file_frame boolean:=false;file_final_proof boolean:=false;file_final_frame jsonb;file_reader_context jsonb;file_final_lineage jsonb;
BEGIN
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='public.observe_application_field_projection(uuid,jsonb,text,uuid,text,text,text,text[])'::regprocedure) IS DISTINCT FROM 'e98b2198a8793a57c982fa992f92cdd5dec0232b93de28d5b9b49cb4b061e1f5'
 OR (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='public.application_current_field_snapshot(uuid,uuid)'::regprocedure) IS DISTINCT FROM '06f3bd17edf6103a9d2014856a9abff19dba216614e6ce17cb13cd1705355403'
 OR (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='public.application_materialize_field_envelope(uuid,jsonb,integer)'::regprocedure) IS DISTINCT FROM '6b4340ea9aa09be4512d8259bd1055c40d6986f8cb5e6319c3d1341cf5a989d5'
 OR (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='public.application_session_query_scan(uuid,uuid,text,integer,text[],jsonb,jsonb)'::regprocedure) IS DISTINCT FROM '70c4a1c928f38e61aebedb549340a42516ec3ba01f62c432cf526b3b4a735d72'
 OR (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='public.read_native_session_field_snapshots(uuid,uuid[],text[])'::regprocedure) IS DISTINCT FROM '50cb4616c970bb1a2960cf9e285a0991c0338f77a13c15e1887ddc2c9309500c'
 OR (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='public.application_compute_field_envelope(uuid,jsonb,text,uuid,text,text,text[],integer)'::regprocedure) IS DISTINCT FROM '50973b8ff2d29e46ac9fdc0a424b8100d50ce28d3de6964eee52bde01cda43d7' THEN RETURN NULL;END IF;
 IF actor IS NULL OR t NOT IN('session_message','session_message_annotation') OR through IS NULL OR through<0
  OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='public.session_messages'::regclass WHERE r.rolname=session_user
   AND (r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,'USAGE'))) THEN RAISE EXCEPTION 'access_unavailable' USING ERRCODE='42501';END IF;
 parent:=application_session_query_parent(w,s);bounds:=application_session_query_bounds(w,parent);
 IF parent IS NULL OR bounds IS NULL THEN RAISE EXCEPTION 'access_unavailable' USING ERRCODE='42501';END IF;
 fields:=ARRAY(SELECT field FROM unnest(application_session_field_keys(t)) field ORDER BY field);
 visibility:=jsonb_build_object('userId',CASE WHEN current_setting('app.agent_shared_audience',true)='true' THEN NULL ELSE actor END,
  'assistants',coalesce(nullif(current_setting('app.agent_visibility_assistants',true),'')::jsonb,'null'::jsonb));
 -- Discover physical identities only. The original scan below still admits
 -- every point, computes payload, and owns the complete query-domain binding.
 IF EXISTS(SELECT 1 FROM workspace_members member WHERE member.workspace_id=w AND member.user_id=actor) THEN
  SELECT array_agg(candidate.kind ORDER BY candidate.sequence_num,candidate.message_id),
   array_agg(candidate.id ORDER BY candidate.sequence_num,candidate.message_id),
   array_agg(candidate.version ORDER BY candidate.sequence_num,candidate.message_id)
   INTO frame_kinds,frame_ids,frame_versions
  FROM(SELECT CASE WHEN t='session_message' THEN 'session_message' ELSE 'session_context_revision' END AS kind,
    CASE WHEN t='session_message' THEN message.id ELSE revision.id END AS id,
    CASE WHEN t='session_message' THEN message.scope_version::text ELSE '1' END AS version,
    message.sequence_num,message.id AS message_id
   FROM session_messages message
   LEFT JOIN session_message_annotation_heads head ON head.workspace_id=message.workspace_id
    AND head.session_id=message.session_id AND head.message_id=message.id
   LEFT JOIN session_context_scope_revisions revision ON revision.workspace_id=head.workspace_id
    AND revision.id=head.scope_revision_id AND revision.session_id=message.session_id
    AND revision.parent_kind='message_annotation' AND revision.parent_id=message.id
   WHERE message.workspace_id=w AND message.session_id=s AND message.sequence_num<=through
    AND(t='session_message' OR revision.id IS NOT NULL)
   ORDER BY message.sequence_num,message.id LIMIT 101) candidate;
  IF cardinality(frame_ids) BETWEEN 1 AND 100 AND array_position(frame_ids,NULL) IS NULL
   AND array_position(frame_versions,NULL) IS NULL THEN
   -- Optional eligibility discovery must not turn an incomplete observation
   -- or an oversized union into a new batch-wide refusal. This bounded metadata
   -- walk proves eligibility only; the complete canonical proof walks it again.
   WITH RECURSIVE candidates(kind,id,version) AS (
    SELECT * FROM unnest(frame_kinds,frame_ids,frame_versions)
    UNION SELECT edge.kind,edge.id,edge.version FROM candidates node
     CROSS JOIN LATERAL application_scope_source_edges(w,node.kind,node.id,node.version) edge
   ), bounded AS MATERIALIZED(SELECT * FROM candidates LIMIT 4097)
   SELECT coalesce(jsonb_agg(to_jsonb(node)),'[]') INTO frame_nodes FROM bounded node;
   IF jsonb_array_length(frame_nodes)<=4096
    AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(frame_nodes) node
     WHERE node->>'kind' IS NULL OR node->>'id' IS NULL OR node->>'version' IS NULL)
    AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(frame_nodes) node
     LEFT JOIN application_field_resources resource ON resource.workspace_id=w AND resource.id=(node->>'id')::uuid
     LEFT JOIN application_field_observations observation ON observation.workspace_id=w
      AND observation.resource_id=resource.id AND observation.version=node->>'version'
     WHERE node->>'kind'='application_field' AND(resource.id IS NULL OR observation.resource_id IS NULL))
    AND EXISTS(SELECT 1 FROM jsonb_array_elements(frame_nodes) node
     JOIN application_field_resources resource ON resource.workspace_id=w AND resource.id=(node->>'id')::uuid
     WHERE node->>'kind'='application_field' AND resource.origin='{"kind":"native","moduleKey":"native"}'::jsonb
      AND resource.type_key='memory' AND resource.selection='query_domain')
    AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(frame_nodes) node
     JOIN application_field_resources resource ON resource.workspace_id=w AND resource.id=(node->>'id')::uuid
     WHERE node->>'kind'='application_field' AND resource.type_key='memory'
      AND(resource.selection<>'query_domain' OR resource.selected_version IS NOT NULL)) THEN
    -- No-file captures retain their exact existing frame path and cost.
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(frame_nodes) n WHERE n->>'kind'='workspace_file') THEN
     IF application_native_file_capture_helpers_current() IS TRUE THEN
      file_reader_context:=jsonb_build_object('sessionUser',session_user,'currentUser',current_user,'settings',(SELECT jsonb_object_agg(setting_name,current_setting(setting_name,true)) FROM unnest(ARRAY['app.agent_actor_id','app.agent_clearance','app.agent_compartments','app.agent_mutation_compartments','app.agent_project_ids','app.agent_shared_audience','app.agent_visibility_assistants','app.agent_workspace_id','app.application_assistant_id','app.application_command_key','app.application_credential_id','app.application_credential_review_id','app.application_grant_review_id','app.application_home_binding_id','app.application_id','app.application_native_write_intent','app.application_oauth_id','app.application_record_write_type','app.assistant_transfer','app.association_source_membership_actor','app.association_source_order_actor','app.capture_admission','app.capture_session','app.connector_setup_id','app.creation_admission','app.crm_erasure_capture','app.crm_historical_actor','app.current_user_id','app.deployed_application_module','app.engineering_archive_publication','app.explicit_general','app.external_key_explicit','app.external_key_session','app.external_source_action','app.external_source_actor_id','app.external_source_assistant_id','app.external_source_operation_id','app.external_source_service_binding_id','app.knowledge_event_actor','app.media_intake_parent','app.native_entity_write_intent','app.native_query_data_ceilings','app.native_task_write_intent','app.page_event_moved_id','app.pdf_intake_artifact','app.programmatic_candidate','app.programmatic_candidate_source','app.programmatic_publication_batch','app.public_share_mode','app.public_share_root','app.public_share_token_hash','app.recording_session_admission','app.retained_task_goal','app.routine_intake_apply_receipt','app.routine_intake_toggle_receipt','app.scope_review_actor','app.session_creation_admission','app.source_service_release_review_id','app.system_bypass','app.v2_active','app.v2_assistant_id','app.v2_binding','app.v2_cap','app.v2_context_department','app.workflow_schedule_review']) setting_name));
     frame_result:=read_native_file_session_cohort_frame(w,frame_kinds,frame_ids,frame_versions,true);
 IF jsonb_build_object('sessionUser',session_user,'currentUser',current_user,'settings',(SELECT jsonb_object_agg(setting_name,current_setting(setting_name,true)) FROM unnest(ARRAY['app.agent_actor_id','app.agent_clearance','app.agent_compartments','app.agent_mutation_compartments','app.agent_project_ids','app.agent_shared_audience','app.agent_visibility_assistants','app.agent_workspace_id','app.application_assistant_id','app.application_command_key','app.application_credential_id','app.application_credential_review_id','app.application_grant_review_id','app.application_home_binding_id','app.application_id','app.application_native_write_intent','app.application_oauth_id','app.application_record_write_type','app.assistant_transfer','app.association_source_membership_actor','app.association_source_order_actor','app.capture_admission','app.capture_session','app.connector_setup_id','app.creation_admission','app.crm_erasure_capture','app.crm_historical_actor','app.current_user_id','app.deployed_application_module','app.engineering_archive_publication','app.explicit_general','app.external_key_explicit','app.external_key_session','app.external_source_action','app.external_source_actor_id','app.external_source_assistant_id','app.external_source_operation_id','app.external_source_service_binding_id','app.knowledge_event_actor','app.media_intake_parent','app.native_entity_write_intent','app.native_query_data_ceilings','app.native_task_write_intent','app.page_event_moved_id','app.pdf_intake_artifact','app.programmatic_candidate','app.programmatic_candidate_source','app.programmatic_publication_batch','app.public_share_mode','app.public_share_root','app.public_share_token_hash','app.recording_session_admission','app.retained_task_goal','app.routine_intake_apply_receipt','app.routine_intake_toggle_receipt','app.scope_review_actor','app.session_creation_admission','app.source_service_release_review_id','app.system_bypass','app.v2_active','app.v2_assistant_id','app.v2_binding','app.v2_cap','app.v2_context_department','app.workflow_schedule_review']) setting_name)) IS DISTINCT FROM file_reader_context THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
      file_frame:=frame_result->>'admitted'='true' AND frame_result#>>'{memo,memoryStatement,workspaceId}'=w::text;
     END IF;
    END IF;
    IF frame_result IS NULL THEN frame_result:=read_native_session_cohort_frame(w,frame_kinds,frame_ids,frame_versions,true);END IF;
    -- A rejected candidate cannot suppress a different readable point. Only
    -- the original scan decides membership. An unavailable private Memory
    -- statement likewise keeps the original, empty-worklist behavior.
    IF frame_result->>'admitted'='true' AND jsonb_typeof(frame_result->'memo')='object'
     AND frame_result#>>'{memo,memoryStatement,workspaceId}'=w::text THEN
     memo:=frame_result->'memo';
    END IF;
   END IF;
  END IF;
 END IF;
 result:=application_session_eval_scan(w,s,t,through,fields,bounds,visibility,memo);memo:=coalesce(result->'memo',memo);scanned:=result->'value';
 IF scanned IS NULL THEN RAISE EXCEPTION 'access_unavailable' USING ERRCODE='42501';END IF;
 domain:=jsonb_build_object('kind','session_query_domain_v1','sessionId',s,'throughSequence',through,'fields',fields,'bounds',bounds,'visibility',visibility,
  'parentFingerprint',parent->'fingerprint','candidates',scanned->'candidates','points',scanned->'points');
 identity_value:=application_field_digest(jsonb_build_object('kind','session_query_domain_v1','workspaceId',w,'type',t,'domain',domain));
 domain_id:=application_field_resource_uuid(identity_value);
 INSERT INTO application_query_domains(id,workspace_id,origin,type_key,schema_version,domain,identity)
  VALUES(domain_id,w,'{"kind":"native","moduleKey":"native"}',t,'1',domain,identity_value) ON CONFLICT DO NOTHING;
 SELECT * INTO frozen FROM application_query_domains WHERE workspace_id=w AND id=domain_id;
 IF NOT FOUND OR (frozen.type_key,frozen.schema_version,frozen.domain,frozen.identity) IS DISTINCT FROM (t,'1',domain,identity_value) THEN RAISE EXCEPTION 'scope_evidence_immutable' USING ERRCODE='22023';END IF;
 result:=application_session_eval_envelope(w,t,domain_id,'query_domain',fields,memo);envelope:=result->'value';
 IF envelope IS NULL OR envelope#>>'{state,recordVersion}' IS DISTINCT FROM '1' THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 FOR source IN SELECT value FROM jsonb_array_elements(envelope->'sources') WHERE value->>'resourceKind'='external_source' LOOP
  external:=external_source_snapshot(w,(source->>'resourceId')::uuid);
  IF external IS NULL OR external->>'held' IS DISTINCT FROM 'false' OR external->>'version' IS DISTINCT FROM source->>'version'
   OR NOT EXISTS(SELECT 1 FROM external_source_observations observation WHERE observation.workspace_id=w AND observation.id=(source->>'resourceId')::uuid
    AND (observation.observation#>>'{retention,mode}'='governed' OR
  observation.observation#>>'{retention,mode}'='released_snapshot'
  AND length(observation.observation#>>'{retention,releaseId}')>0
  AND jsonb_typeof(observation.observation#>'{retention,expiresAt}')='number'
  AND (observation.observation#>>'{retention,expiresAt}')::numeric>extract(epoch FROM clock_timestamp())*1000)) THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 END LOOP;
 -- Only this internally computed envelope can bind to the complete frame.
 -- Re-read every exact native root now. A new annotation head, changed scope,
 -- unknown point or independent source retains the original full validator.
 frame_ancestry:=frame_result->>'admitted'='true'
  AND frame_result#>>'{memo,memoryStatement,workspaceId}'=w::text;
 IF frame_ancestry THEN
  FOR frame_point IN WITH RECURSIVE points(value) AS (
   SELECT envelope UNION ALL SELECT child.value FROM points point
    CROSS JOIN LATERAL jsonb_array_elements(point.value->'children') child(value)
  ) SELECT value FROM points LOOP
   IF frame_point IS NOT DISTINCT FROM envelope THEN
    IF frame_point->'origin' IS DISTINCT FROM '{"kind":"native","moduleKey":"native"}'::jsonb
     OR frame_point->>'typeKey' IS DISTINCT FROM t OR frame_point->>'selection' IS DISTINCT FROM 'query_domain'
     OR frame_point->>'id' IS DISTINCT FROM domain_id::text OR frame_point->>'selectedVersion' IS NOT NULL
     OR frame_point#>>'{state,sourceKind}' IS DISTINCT FROM 'application_query_domain'
     OR frame_point#>>'{state,sourceId}' IS DISTINCT FROM domain_id::text
     OR EXISTS(SELECT 1 FROM jsonb_array_elements(frame_point->'sources') reference
      WHERE reference->>'resourceKind' IS DISTINCT FROM 'application_field') THEN
     frame_ancestry:=false;EXIT;
    END IF;
    CONTINUE;
   END IF;
   frame_kind:=frame_point#>>'{state,sourceKind}';
   IF frame_point->'origin' IS DISTINCT FROM '{"kind":"native","moduleKey":"native"}'::jsonb
    OR frame_point->>'typeKey' IS DISTINCT FROM t OR frame_point->>'selection' IS DISTINCT FROM 'query'
    OR frame_point->>'selectedVersion' IS NOT NULL OR frame_point->'children' IS DISTINCT FROM '[]'::jsonb
    OR frame_point->'sources' IS DISTINCT FROM '[]'::jsonb
    OR frame_kind IS DISTINCT FROM (CASE WHEN t='session_message' THEN 'session_message' ELSE 'session_context_revision' END)
    OR frame_point#>>'{state,source,held}' IS DISTINCT FROM 'false'
    OR frame_point#>>'{state,source,workspaceId}' IS DISTINCT FROM w::text
    OR frame_point#>>'{state,source,version}' IS DISTINCT FROM frame_point#>>'{state,sourceVersion}' THEN
    frame_ancestry:=false;EXIT;
   END IF;
   frame_id:=(frame_point#>>'{state,sourceId}')::uuid;frame_version:=frame_point#>>'{state,sourceVersion}';
   IF frame_id IS NULL OR frame_version IS NULL
    OR t='session_message' AND frame_id::text IS DISTINCT FROM frame_point->>'id'
    OR t='session_message_annotation' AND NOT EXISTS(SELECT 1 FROM session_message_annotation_heads head
     JOIN session_context_scope_revisions revision ON revision.workspace_id=head.workspace_id AND revision.id=head.scope_revision_id
     WHERE head.workspace_id=w AND head.session_id=s AND head.message_id=(frame_point->>'id')::uuid
      AND head.scope_revision_id=frame_id AND revision.parent_kind='message_annotation'
      AND revision.parent_id=head.message_id AND revision.session_id=s) THEN
    frame_ancestry:=false;EXIT;
   END IF;
   frame_tuple:=jsonb_build_object('workspaceId',frame_point#>'{state,source,workspaceId}',
    'userId',frame_point#>'{state,source,userId}','assistantId',frame_point#>'{state,source,assistantId}',
    'sensitivity',frame_point#>'{state,source,sensitivity}','compartments',frame_point#>'{state,source,compartments}',
    'projectIds',frame_point#>'{state,source,projectIds}','resourceKind',frame_kind,'resourceId',frame_id,'version',frame_version);
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(frame_result->'current') current_root WHERE current_root=frame_tuple) THEN
    frame_ancestry:=false;EXIT;
   END IF;
   IF frame_kind='session_context_revision' THEN
    frame_root:=read_entity_derivation_source(w,frame_kind,frame_id);
    frame_actual:=jsonb_build_object('workspaceId',frame_root->'workspaceId','userId',frame_root->'userId',
     'assistantId',frame_root->'assistantId','sensitivity',frame_root->'sensitivity','compartments',frame_root->'compartments',
     'projectIds',frame_root->'projectIds','resourceKind',frame_kind,'resourceId',frame_id,'version',frame_root->'version');
    IF frame_root->>'held' IS DISTINCT FROM 'false' OR frame_actual IS DISTINCT FROM frame_tuple THEN
     frame_ancestry:=false;EXIT;
    END IF;
   END IF;
   frame_root:=read_admitted_native_scope_snapshot(w,frame_kind,frame_id);
   frame_actual:=jsonb_build_object('workspaceId',frame_root->'workspaceId','userId',frame_root->'userId',
    'assistantId',frame_root->'assistantId','sensitivity',frame_root->'sensitivity','compartments',frame_root->'compartments',
    'projectIds',frame_root->'projectIds','resourceKind',frame_kind,'resourceId',frame_id,'version',frame_root->'version');
   IF frame_root->>'held' IS DISTINCT FROM 'false' OR frame_actual IS DISTINCT FROM frame_tuple THEN
    frame_ancestry:=false;EXIT;
   END IF;
  END LOOP;
 END IF;
 IF frame_ancestry IS DISTINCT FROM true THEN
  IF file_frame THEN RETURN NULL;END IF;
  IF application_field_envelope_ancestry_allowed(w,envelope) IS NOT TRUE THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 END IF;
 -- The initial proof already qualified selected fields and buffered payload.
 -- Bounded captures receive one independent final proof after materialization.
 -- Larger captures retain the original pre-materialization and snapshot path.
 file_final_proof:=file_frame AND jsonb_array_length(coalesce(envelope->'children','[]'))<100;
 IF file_frame THEN
