 root:=session_context_revision_native(w,i);
 IF root->>'held' IS DISTINCT FROM 'false' THEN RETURN NULL;END IF;
 FOR source IN SELECT value FROM jsonb_array_elements(read_resource_page_dependencies(w,k,i,'1')) LOOP
