  OR (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc
   WHERE oid='public.read_native_session_cohort_evidence(uuid,text[],uuid[],text[],boolean)'::regprocedure)
   IS DISTINCT FROM '2afff03ed88d3de82386880a3b582bbfa2c4379b06ecbc06fd98ff467f60c376' THEN RETURN NULL;END IF;

 IF kinds IS NULL OR ids IS NULL OR versions IS NULL OR cardinality(ids) NOT BETWEEN 1 AND 100
  OR cardinality(kinds)<>cardinality(ids) OR cardinality(versions)<>cardinality(ids)
  OR array_position(kinds,NULL) IS NOT NULL OR array_position(ids,NULL) IS NOT NULL OR array_position(versions,NULL) IS NOT NULL THEN
  RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 -- A changed original evaluator retains its full original fallback contract.
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc
  WHERE oid='public.application_session_eval_scope_current(uuid,text,uuid,text,jsonb)'::regprocedure)
  IS DISTINCT FROM 'b977bab4f04ae2d61d7c7d042225d41a97346466f95352e6f8c8e934bd2a46ca' THEN RETURN NULL;END IF;
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='public.read_native_session_query_cohort_sources(uuid,text[],uuid[],text[])'::regprocedure)
  IS DISTINCT FROM 'decf5058016df0127f14f201c843b311dad798075d3a86ed41071523139c7018' THEN RETURN NULL;END IF;
 -- Every other profile/resource family delegates to the original validator.
 IF actor IS NULL OR nullif(current_setting('app.application_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.public_share_root',true),'') IS NOT NULL
  OR EXISTS(SELECT 1 FROM unnest(kinds) kind WHERE kind NOT IN('application_field','session_context_revision','session_message','memory','workspace_file')) OR NOT include_memory AND 'memory'=ANY(kinds) THEN RETURN NULL;END IF;
 IF EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='session_messages'::regclass WHERE r.rolname=session_user
  AND(r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,'USAGE'))) THEN RETURN NULL;END IF;
 -- Ineligible root metadata adds no native lock or full-closure walk.
 IF EXISTS(SELECT 1 FROM unnest(kinds,ids) root(kind,id)
  LEFT JOIN application_field_resources field ON field.workspace_id=w AND field.id=root.id
  WHERE root.kind='application_field' AND(field.id IS NULL OR field.origin<>'{"kind":"native","moduleKey":"native"}'::jsonb
   OR NOT(field.type_key IN('session_message','session_message_annotation') OR include_memory AND field.type_key='memory'))) THEN RETURN NULL;END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),'[]') INTO nodes FROM application_scope_lineage(w,kinds,ids,versions) n;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n WHERE n->>'kind' NOT IN('application_field','application_query_domain','session_context_revision','session_message','memory','workspace_file'))
  OR NOT include_memory AND EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n WHERE n->>'kind'='memory')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n LEFT JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>'id')::uuid
   WHERE n->>'kind'='application_field' AND(f.id IS NULL OR f.origin<>'{"kind":"native","moduleKey":"native"}'::jsonb OR NOT(f.type_key IN('session_message','session_message_annotation') OR include_memory AND f.type_key='memory'))) THEN RETURN NULL;END IF;

 -- Discover eligibility only. A file with its own derivation, any historical
 -- selector, or independent Page ancestry keeps the complete original path.
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n WHERE n->>'kind'='workspace_file')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN scope_derivations d
   ON d.workspace_id=w AND d.resource_kind='workspace_file' AND d.resource_id=(n->>'id')::uuid
   WHERE n->>'kind'='workspace_file')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f
   ON f.workspace_id=w AND f.id=(n->>'id')::uuid WHERE n->>'kind'='application_field'
   AND (f.selected_version IS NOT NULL OR f.selection='history')) THEN RETURN NULL;END IF;
 FOR node IN SELECT value FROM jsonb_array_elements(nodes) WHERE value->>'kind'='workspace_file' LOOP
  IF read_admitted_page_dependencies(w,'workspace_file',(node->>'id')::uuid,node->>'version')
   IS DISTINCT FROM '[]'::jsonb THEN RETURN NULL;END IF;
 END LOOP;
 -- Source-denied physical candidates still require fresh remote cohort
 -- context. No fast-path admission is inferred from the original closure.
 IF EXISTS(SELECT 1 FROM read_native_session_query_cohort_nodes(w,nodes)) THEN RETURN NULL;END IF;
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='public.read_native_memory_query_cohort_sources(uuid,text[],uuid[],text[])'::regprocedure)
  IS DISTINCT FROM '8a01f2a9a01cbe613ce23a519610a77e3ae8354bef88df8e99cab0d32bcc2bcd' THEN RETURN NULL;END IF;
 -- Complete current Memory query cohorts cannot hide an independent source.
 -- Metadata is not permission; any independent candidate delegates unchanged.
 IF include_memory THEN
  FOR dependency IN SELECT array_agg(candidate.source->>'resourceKind') AS kinds,
    array_agg((candidate.source->>'resourceId')::uuid) AS ids,array_agg(candidate.source->>'version') AS versions
   FROM read_native_memory_query_cohort_sources(w,kinds,ids,versions) WITH ORDINALITY candidate(source,ord)
   GROUP BY (candidate.ord-1)/100 LOOP
   IF EXISTS(SELECT 1 FROM read_external_source_dependencies(w,dependency.kinds,dependency.ids,dependency.versions)) THEN RETURN NULL;END IF;
  END LOOP;
 END IF;

 PERFORM id FROM workspaces WHERE id=w FOR SHARE;
 IF NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=actor) THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;

 -- This private argument is created only by this closed SQL operation. It holds
 -- scope metadata, never a Memory business row or a shared selected-field grant.
 IF include_memory AND native_turn_helpers_current() AND (NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND (
 m.valid_to IS NOT NULL OR m.retracted_at IS NOT NULL OR m.superseded_by IS NOT NULL OR m.source_session_id IS NOT NULL OR m.source_episode_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind='memory' AND d.resource_id=m.id)
 OR EXISTS(SELECT 1 FROM memories prior WHERE prior.workspace_id=w AND prior.superseded_by=m.id)
 OR EXISTS(SELECT 1 FROM native_memory_successor_transitions t WHERE t.workspace_id=w AND (t.predecessor_id=m.id OR t.successor_id=m.id))))
 AND NOT EXISTS(SELECT 1 FROM application_native_resource_owners o WHERE o.workspace_id=w AND o.origin='{"kind":"native","moduleKey":"native"}'::jsonb AND o.resource_type='memory')
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>'id')::uuid WHERE n->>'kind'='application_field' AND f.type_key='memory' AND (
  f.selected_version IS NOT NULL OR f.selection NOT IN('read','query','identity','query_domain')
  OR f.selection<>'query_domain' AND NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND m.id=f.resource_id)
  OR EXISTS(SELECT 1 FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=f.id AND s.version=n->>'version')))
 AND (SELECT count(*) FROM (SELECT id FROM memories WHERE workspace_id=w LIMIT 4097) bounded)<=4096) THEN
  BEGIN
   PERFORM singleton FROM application_policy_contract_epoch WHERE singleton FOR SHARE NOWAIT;
   IF NOT FOUND THEN RAISE EXCEPTION 'memory_statement_unavailable' USING ERRCODE='55P03';END IF;
   PERFORM workspace_id FROM application_policy_workspace_epochs WHERE workspace_id=w FOR SHARE NOWAIT;
   IF NOT FOUND THEN RAISE EXCEPTION 'memory_statement_unavailable' USING ERRCODE='55P03';END IF;
   PERFORM id FROM memories WHERE workspace_id=w ORDER BY id FOR SHARE NOWAIT;
   IF NOT (NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND (
 m.valid_to IS NOT NULL OR m.retracted_at IS NOT NULL OR m.superseded_by IS NOT NULL OR m.source_session_id IS NOT NULL OR m.source_episode_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind='memory' AND d.resource_id=m.id)
 OR EXISTS(SELECT 1 FROM memories prior WHERE prior.workspace_id=w AND prior.superseded_by=m.id)
 OR EXISTS(SELECT 1 FROM native_memory_successor_transitions t WHERE t.workspace_id=w AND (t.predecessor_id=m.id OR t.successor_id=m.id))))
 AND NOT EXISTS(SELECT 1 FROM application_native_resource_owners o WHERE o.workspace_id=w AND o.origin='{"kind":"native","moduleKey":"native"}'::jsonb AND o.resource_type='memory')
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>'id')::uuid WHERE n->>'kind'='application_field' AND f.type_key='memory' AND (
  f.selected_version IS NOT NULL OR f.selection NOT IN('read','query','identity','query_domain')
  OR f.selection<>'query_domain' AND NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND m.id=f.resource_id)
  OR EXISTS(SELECT 1 FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=f.id AND s.version=n->>'version')))
 AND (SELECT count(*) FROM (SELECT id FROM memories WHERE workspace_id=w LIMIT 4097) bounded)<=4096) THEN RAISE EXCEPTION 'memory_statement_unavailable' USING ERRCODE='55P03';END IF;
   memory_context:=application_memory_query_context(w);
   IF memory_context#>>'{policy,nativeDefault}' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'memory_statement_unavailable' USING ERRCODE='55P03';END IF;
   memory_rows:='{}';memory_cohort:='[]';
   FOR memory_candidate IN SELECT id,scope_version FROM memories WHERE workspace_id=w ORDER BY id LOOP
    SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),'[]') INTO memory_lineage FROM application_scope_lineage(w,ARRAY['memory'],ARRAY[memory_candidate.id],ARRAY[memory_candidate.scope_version::text]) n;
    IF memory_lineage IS DISTINCT FROM jsonb_build_array(jsonb_build_object('kind','memory','id',memory_candidate.id,'version',memory_candidate.scope_version::text)) THEN RAISE EXCEPTION 'memory_statement_unavailable' USING ERRCODE='55P03';END IF;
    memory_source:=read_admitted_native_scope_snapshot(w,'memory',memory_candidate.id);
    memory_rows:=memory_rows||jsonb_build_object(memory_candidate.id::text,jsonb_build_object('source',memory_source,'lineage',memory_lineage));
    memory_cohort:=memory_cohort||jsonb_build_array(jsonb_build_object('id',memory_candidate.id,'version',memory_candidate.scope_version::text));
   END LOOP;
   memo:=memo||jsonb_build_object('memoryStatement',jsonb_build_object('workspaceId',w,'context',memory_context,'rows',memory_rows,'cohort',memory_cohort));
  EXCEPTION WHEN lock_not_available THEN memory_rows:=NULL;memory_context:=NULL;memory_cohort:=NULL;
  END;
 END IF;
 -- Read every original field under the current actor and original selector.
 -- Parent/payload/domain checks are inside the unchanged closed evaluator.
 FOR node IN SELECT value FROM jsonb_array_elements(nodes) WHERE value->>'kind'='application_field' ORDER BY value->>'id',value->>'version' LOOP
  SELECT * INTO STRICT observation FROM application_field_observations WHERE workspace_id=w AND resource_id=(node->>'id')::uuid AND version=node->>'version';
  result:=application_session_eval_field(w,(node->>'id')::uuid,node->>'version',memo);memo:=coalesce(result->'memo',memo);current_source:=result->'value';
  IF current_source IS NULL OR current_source->>'held' IS DISTINCT FROM 'false' THEN RETURN jsonb_build_object('admitted',false);END IF;
  immutable:=immutable||jsonb_build_array(observation.source_scope||jsonb_build_object('resourceKind','application_field','resourceId',observation.resource_id,'version',observation.version));
  currents:=currents||jsonb_build_array(current_source-ARRAY['held','validTo','retractedAt']);
 END LOOP;
 -- Direct native/context roots and every persistent ancestor retain the same
 -- current native admission, D1 lifecycle and immutable high-water behavior.
 FOR node IN SELECT value FROM jsonb_array_elements(nodes) WHERE value->>'kind' IN('session_message','session_context_revision','memory','workspace_file') ORDER BY value->>'kind',value->>'id',value->>'version' LOOP
  IF node->>'kind'='session_context_revision' AND read_entity_derivation_source(w,node->>'kind',(node->>'id')::uuid) IS NULL THEN
   RETURN jsonb_build_object('admitted',false);END IF;
  current_source:=read_admitted_native_scope_snapshot(w,node->>'kind',(node->>'id')::uuid);
  IF current_source IS NULL THEN
   IF node->>'kind'='session_context_revision' THEN RETURN jsonb_build_object('admitted',false);END IF;
   CONTINUE;
  END IF;
  IF current_source->>'held' IS DISTINCT FROM 'false' THEN RETURN jsonb_build_object('admitted',false);END IF;
  current_source:=jsonb_build_object('workspaceId',w,'userId',current_source->'userId','assistantId',current_source->'assistantId',
   'sensitivity',current_source->'sensitivity','compartments',current_source->'compartments','projectIds',current_source->'projectIds',
   'resourceKind',node->'kind','resourceId',node->'id','version',current_source->'version');
  currents:=currents||jsonb_build_array(current_source);
  IF node->>'kind'='session_context_revision' THEN
   IF current_source->>'version' IS DISTINCT FROM node->>'version' THEN RETURN jsonb_build_object('admitted',false);END IF;
   immutable:=immutable||jsonb_build_array(current_source);
  END IF;
 END LOOP;
 -- Every original derivation envelope still applies, including those on
 -- native ancestors. The full closure contains no raw Entity source; any such
 -- source already delegated above to the unchanged original evaluator.
 FOR dependency IN SELECT DISTINCT d.* FROM scope_derivations d JOIN jsonb_array_elements(nodes) ancestor(value)
  ON d.resource_kind=ancestor.value->>'kind' AND d.resource_id=(ancestor.value->>'id')::uuid WHERE d.workspace_id=w LOOP
  IF workflow_evidence_envelope_visible(w,jsonb_build_object('workspaceId',w,
   'userId',dependency.user_id,'assistantId',dependency.assistant_id,'sensitivity',dependency.sensitivity,
   'compartments',dependency.compartments,'projectIds',dependency.project_ids)) IS NOT TRUE THEN
   RETURN jsonb_build_object('admitted',false);END IF;
 END LOOP;
 -- The evaluator contract is also current at return.
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc
  WHERE oid='public.application_session_eval_scope_current(uuid,text,uuid,text,jsonb)'::regprocedure)
  IS DISTINCT FROM 'b977bab4f04ae2d61d7c7d042225d41a97346466f95352e6f8c8e934bd2a46ca' THEN RETURN NULL;END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),'[]') INTO fresh_nodes FROM application_scope_lineage(w,kinds,ids,versions) n;
 IF nodes IS DISTINCT FROM fresh_nodes THEN RETURN jsonb_build_object('admitted',false);END IF;
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='public.read_native_session_query_cohort_sources(uuid,text[],uuid[],text[])'::regprocedure)
  IS DISTINCT FROM 'decf5058016df0127f14f201c843b311dad798075d3a86ed41071523139c7018' THEN RETURN NULL;END IF;

 IF EXISTS(SELECT 1 FROM read_native_session_query_cohort_nodes(w,fresh_nodes)) THEN RETURN jsonb_build_object('admitted',false);END IF;
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='public.read_native_memory_query_cohort_sources(uuid,text[],uuid[],text[])'::regprocedure)
  IS DISTINCT FROM '8a01f2a9a01cbe613ce23a519610a77e3ae8354bef88df8e99cab0d32bcc2bcd' THEN RETURN NULL;END IF;
 -- Complete current Memory query cohorts cannot hide an independent source.
 -- Metadata is not permission; any independent candidate delegates unchanged.
 IF include_memory THEN
  FOR dependency IN SELECT array_agg(candidate.source->>'resourceKind') AS kinds,
    array_agg((candidate.source->>'resourceId')::uuid) AS ids,array_agg(candidate.source->>'version') AS versions
   FROM read_native_memory_query_cohort_sources(w,kinds,ids,versions) WITH ORDINALITY candidate(source,ord)
   GROUP BY (candidate.ord-1)/100 LOOP
   IF EXISTS(SELECT 1 FROM read_external_source_dependencies(w,dependency.kinds,dependency.ids,dependency.versions)) THEN RETURN NULL;END IF;
  END LOOP;
 END IF;


 IF memo ? 'memoryStatement' THEN
  IF native_turn_helpers_current() IS NOT TRUE OR application_memory_query_context(w) IS DISTINCT FROM memory_context OR NOT (NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND (
 m.valid_to IS NOT NULL OR m.retracted_at IS NOT NULL OR m.superseded_by IS NOT NULL OR m.source_session_id IS NOT NULL OR m.source_episode_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind='memory' AND d.resource_id=m.id)
 OR EXISTS(SELECT 1 FROM memories prior WHERE prior.workspace_id=w AND prior.superseded_by=m.id)
 OR EXISTS(SELECT 1 FROM native_memory_successor_transitions t WHERE t.workspace_id=w AND (t.predecessor_id=m.id OR t.successor_id=m.id))))
 AND NOT EXISTS(SELECT 1 FROM application_native_resource_owners o WHERE o.workspace_id=w AND o.origin='{"kind":"native","moduleKey":"native"}'::jsonb AND o.resource_type='memory')
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>'id')::uuid WHERE n->>'kind'='application_field' AND f.type_key='memory' AND (
  f.selected_version IS NOT NULL OR f.selection NOT IN('read','query','identity','query_domain')
  OR f.selection<>'query_domain' AND NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND m.id=f.resource_id)
  OR EXISTS(SELECT 1 FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=f.id AND s.version=n->>'version')))
 AND (SELECT count(*) FROM (SELECT id FROM memories WHERE workspace_id=w LIMIT 4097) bounded)<=4096) THEN RETURN NULL;END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'version',scope_version::text) ORDER BY id),'[]') INTO memory_cohort FROM memories WHERE workspace_id=w;
  IF memory_cohort IS DISTINCT FROM memo#>'{memoryStatement,cohort}' THEN RETURN NULL;END IF;
  FOR memory_candidate IN SELECT id,scope_version FROM memories WHERE workspace_id=w ORDER BY id LOOP
   memory_source:=read_admitted_native_scope_snapshot(w,'memory',memory_candidate.id);
   SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),'[]') INTO memory_lineage FROM application_scope_lineage(w,ARRAY['memory'],ARRAY[memory_candidate.id],ARRAY[memory_candidate.scope_version::text]) n;
   IF memory_source IS DISTINCT FROM memory_rows#>ARRAY[memory_candidate.id::text,'source'] OR memory_lineage IS DISTINCT FROM memory_rows#>ARRAY[memory_candidate.id::text,'lineage'] THEN RETURN NULL;END IF;
  END LOOP;
 END IF;

 IF native_turn_helpers_current() IS NOT TRUE
  OR (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc
   WHERE oid='public.read_native_session_cohort_evidence(uuid,text[],uuid[],text[],boolean)'::regprocedure)
   IS DISTINCT FROM '2afff03ed88d3de82386880a3b582bbfa2c4379b06ecbc06fd98ff467f60c376' THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('admitted',true,'immutable',immutable,'current',currents);
END

DECLARE buffered jsonb:='[]';position integer;memo jsonb:='{}';result jsonb;resource application_field_resources;
 frame_nodes jsonb;frame_result jsonb;actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
BEGIN
 IF application_native_file_capture_helpers_current() IS NOT TRUE THEN RETURN QUERY SELECT * FROM read_native_session_field_snapshots(w,ids,versions);RETURN;END IF;
 IF ids IS NULL OR versions IS NULL OR cardinality(ids) NOT BETWEEN 1 AND 4096 OR cardinality(ids)<>cardinality(versions)
  OR array_position(ids,NULL) IS NOT NULL OR array_position(versions,NULL) IS NOT NULL THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 -- This is a NEW complete proof after capture materialization. Initial
 -- capture state is never an input. Invalid roots retain per-row held results.
 IF cardinality(ids)<=100 AND array_ndims(ids)=1 AND array_lower(ids,1)=1
  AND array_ndims(versions)=1 AND array_lower(versions,1)=1
  AND EXISTS(SELECT 1 FROM workspace_members member WHERE member.workspace_id=w AND member.user_id=actor)
  AND NOT EXISTS(SELECT 1 FROM unnest(ids,versions) root(id,version)
   LEFT JOIN application_field_resources field ON field.workspace_id=w AND field.id=root.id
   LEFT JOIN application_field_observations observation ON observation.workspace_id=w AND observation.resource_id=field.id
    AND observation.version=root.version WHERE field.id IS NULL OR observation.resource_id IS NULL) THEN
  WITH RECURSIVE candidates(kind,id,version) AS (
   SELECT 'application_field'::text,root.id,root.version FROM unnest(ids,versions) root(id,version)
   UNION SELECT edge.kind,edge.id,edge.version FROM candidates node
    CROSS JOIN LATERAL application_scope_source_edges(w,node.kind,node.id,node.version) edge
  ), bounded AS MATERIALIZED(SELECT * FROM candidates LIMIT 4097)
  SELECT coalesce(jsonb_agg(to_jsonb(node)),'[]') INTO frame_nodes FROM bounded node;
  IF jsonb_array_length(frame_nodes)<=4096
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(frame_nodes) node
    WHERE node->>'kind' IS NULL OR node->>'id' IS NULL OR node->>'version' IS NULL)
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(frame_nodes) node
    LEFT JOIN application_field_resources field ON field.workspace_id=w AND field.id=(node->>'id')::uuid
    LEFT JOIN application_field_observations observation ON observation.workspace_id=w AND observation.resource_id=field.id
     AND observation.version=node->>'version'
    WHERE node->>'kind'='application_field' AND(field.id IS NULL OR observation.resource_id IS NULL))
   AND EXISTS(SELECT 1 FROM jsonb_array_elements(frame_nodes) node
    JOIN application_field_resources field ON field.workspace_id=w AND field.id=(node->>'id')::uuid
    WHERE node->>'kind'='application_field' AND field.origin='{"kind":"native","moduleKey":"native"}'::jsonb
     AND field.type_key='memory' AND field.selection='query_domain')
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(frame_nodes) node
    JOIN application_field_resources field ON field.workspace_id=w AND field.id=(node->>'id')::uuid
    WHERE node->>'kind'='application_field' AND field.type_key='memory'
     AND(field.selection<>'query_domain' OR field.selected_version IS NOT NULL)) THEN
   IF application_native_file_capture_helpers_current() IS NOT TRUE THEN RETURN QUERY SELECT * FROM read_native_session_field_snapshots(w,ids,versions);RETURN;END IF;
   frame_result:=read_native_file_session_cohort_frame(w,ARRAY(SELECT 'application_field'::text FROM unnest(ids)),ids,versions,true);
   IF frame_result->>'admitted'='true' AND jsonb_typeof(frame_result->'memo')='object'
    AND frame_result#>>'{memo,memoryStatement,workspaceId}'=w::text THEN memo:=frame_result->'memo';END IF;
  END IF;
 END IF;
 IF frame_result->>'admitted' IS DISTINCT FROM 'true' OR memo#>>'{memoryStatement,workspaceId}' IS DISTINCT FROM w::text THEN
  RETURN QUERY SELECT * FROM read_native_session_field_snapshots(w,ids,versions);RETURN;
 END IF;
 FOR position IN 1..cardinality(ids) LOOP
  SELECT * INTO resource FROM application_field_resources WHERE workspace_id=w AND id=ids[position];
  IF FOUND AND resource.origin='{"kind":"native","moduleKey":"native"}'::jsonb
   AND(resource.type_key IN('session_message','session_message_annotation')
    OR resource.type_key='memory' AND resource.selected_version IS NULL
     AND resource.selection IN('read','query','identity','query_domain')
     AND coalesce(memo#>>'{memoryStatement,workspaceId}'=w::text,false)) THEN
   result:=application_session_eval_field(w,ids[position],versions[position],memo);memo:=coalesce(result->'memo',memo);snapshot:=coalesce(result->'value','{"held":true}'::jsonb);
  ELSE snapshot:=read_admitted_application_field_snapshot(w,ids[position],versions[position]);END IF;
  ord:=position;buffered:=buffered||jsonb_build_array(jsonb_build_object('ord',ord,'snapshot',snapshot));
 END LOOP;

 -- No seed proof from capture enters this function. Qualify these buffered
 -- snapshots with another complete proof belonging to this new invocation.
 IF application_native_file_capture_helpers_current() IS NOT TRUE THEN
  RETURN QUERY SELECT * FROM read_native_session_field_snapshots(w,ids,versions);RETURN;
 END IF;
 IF application_native_file_frame_current(w,ARRAY(SELECT 'application_field'::text FROM unnest(ids)),ids,versions,frame_result) IS NOT TRUE THEN
  RETURN QUERY SELECT * FROM read_native_session_field_snapshots(w,ids,versions);RETURN;
 END IF;
 RETURN QUERY SELECT (item->>'ord')::integer,item->'snapshot' FROM jsonb_array_elements(buffered) item ORDER BY (item->>'ord')::integer;
END

DECLARE actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;nodes jsonb;node jsonb;
 observation application_field_observations;memo jsonb:='{}';result jsonb;current_source jsonb;worklist_frame jsonb;
 schedule jsonb;ready record;memo_size integer;native_currents jsonb;native_immutable jsonb;
 immutable jsonb:='[]';currents jsonb:='[]';dependency record;fresh_nodes jsonb;memory_candidate record;memory_rows jsonb;memory_cohort jsonb;memory_context jsonb;memory_lineage jsonb;memory_source jsonb;
BEGIN
 IF application_native_worklist_helpers_current() IS NOT TRUE THEN RETURN NULL;END IF;

 IF native_turn_helpers_current() IS NOT TRUE
  OR (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc
   WHERE oid='public.read_native_session_cohort_evidence(uuid,text[],uuid[],text[],boolean)'::regprocedure)
   IS DISTINCT FROM '2afff03ed88d3de82386880a3b582bbfa2c4379b06ecbc06fd98ff467f60c376' THEN RETURN NULL;END IF;

 IF kinds IS NULL OR ids IS NULL OR versions IS NULL OR cardinality(ids) NOT BETWEEN 1 AND 100
  OR cardinality(kinds)<>cardinality(ids) OR cardinality(versions)<>cardinality(ids)
  OR array_position(kinds,NULL) IS NOT NULL OR array_position(ids,NULL) IS NOT NULL OR array_position(versions,NULL) IS NOT NULL THEN
  RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 -- A changed original evaluator retains its full original fallback contract.
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc
  WHERE oid='public.application_session_eval_scope_current(uuid,text,uuid,text,jsonb)'::regprocedure)
  IS DISTINCT FROM 'b977bab4f04ae2d61d7c7d042225d41a97346466f95352e6f8c8e934bd2a46ca' THEN RETURN NULL;END IF;
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='public.read_native_session_query_cohort_sources(uuid,text[],uuid[],text[])'::regprocedure)
  IS DISTINCT FROM 'decf5058016df0127f14f201c843b311dad798075d3a86ed41071523139c7018' THEN RETURN NULL;END IF;
 -- Every other profile/resource family delegates to the original validator.
 IF actor IS NULL OR nullif(current_setting('app.application_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.public_share_root',true),'') IS NOT NULL
  OR EXISTS(SELECT 1 FROM unnest(kinds) kind WHERE kind NOT IN('application_field','session_context_revision','session_message','memory','workspace_file')) OR NOT include_memory AND 'memory'=ANY(kinds) THEN RETURN NULL;END IF;
 IF EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='session_messages'::regclass WHERE r.rolname=session_user
  AND(r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,'USAGE'))) THEN RETURN NULL;END IF;
 -- Ineligible root metadata adds no native lock or full-closure walk.
 IF EXISTS(SELECT 1 FROM unnest(kinds,ids) root(kind,id)
  LEFT JOIN application_field_resources field ON field.workspace_id=w AND field.id=root.id
  WHERE root.kind='application_field' AND(field.id IS NULL OR field.origin<>'{"kind":"native","moduleKey":"native"}'::jsonb
   OR NOT(field.type_key IN('session_message','session_message_annotation') OR include_memory AND field.type_key='memory'))) THEN RETURN NULL;END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),'[]') INTO nodes FROM application_scope_lineage(w,kinds,ids,versions) n;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n WHERE n->>'kind' NOT IN('application_field','application_query_domain','session_context_revision','session_message','memory','workspace_file'))
  OR NOT include_memory AND EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n WHERE n->>'kind'='memory')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n LEFT JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>'id')::uuid
   WHERE n->>'kind'='application_field' AND(f.id IS NULL OR f.origin<>'{"kind":"native","moduleKey":"native"}'::jsonb OR NOT(f.type_key IN('session_message','session_message_annotation') OR include_memory AND f.type_key='memory'))) THEN RETURN NULL;END IF;

 -- Discover eligibility only. A file with its own derivation, any historical
 -- selector, or independent Page ancestry keeps the complete original path.
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n WHERE n->>'kind'='workspace_file')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN scope_derivations d
   ON d.workspace_id=w AND d.resource_kind='workspace_file' AND d.resource_id=(n->>'id')::uuid
   WHERE n->>'kind'='workspace_file')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f
   ON f.workspace_id=w AND f.id=(n->>'id')::uuid WHERE n->>'kind'='application_field'
   AND (f.selected_version IS NOT NULL OR f.selection='history')) THEN RETURN NULL;END IF;
 -- Decline an overfull graph before the original per-file Page walks.
 IF native_worklist_edges(w,nodes) IS NULL THEN RETURN NULL;END IF;
 FOR node IN SELECT value FROM jsonb_array_elements(nodes) WHERE value->>'kind'='workspace_file' LOOP
  IF read_admitted_page_dependencies(w,'workspace_file',(node->>'id')::uuid,node->>'version')
   IS DISTINCT FROM '[]'::jsonb THEN RETURN NULL;END IF;
 END LOOP;
 -- Source-denied physical candidates still require fresh remote cohort
 -- context. No fast-path admission is inferred from the original closure.
 IF EXISTS(SELECT 1 FROM read_native_session_query_cohort_nodes(w,nodes)) THEN RETURN NULL;END IF;
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='public.read_native_memory_query_cohort_sources(uuid,text[],uuid[],text[])'::regprocedure)
  IS DISTINCT FROM '8a01f2a9a01cbe613ce23a519610a77e3ae8354bef88df8e99cab0d32bcc2bcd' THEN RETURN NULL;END IF;
 -- Complete current Memory query cohorts cannot hide an independent source.
 -- Metadata is not permission; any independent candidate delegates unchanged.
 IF include_memory THEN
  FOR dependency IN SELECT array_agg(candidate.source->>'resourceKind') AS kinds,
    array_agg((candidate.source->>'resourceId')::uuid) AS ids,array_agg(candidate.source->>'version') AS versions
   FROM read_native_memory_query_cohort_sources(w,kinds,ids,versions) WITH ORDINALITY candidate(source,ord)
   GROUP BY (candidate.ord-1)/100 LOOP
   IF EXISTS(SELECT 1 FROM read_external_source_dependencies(w,dependency.kinds,dependency.ids,dependency.versions)) THEN RETURN NULL;END IF;
  END LOOP;
 END IF;

 PERFORM id FROM workspaces WHERE id=w FOR SHARE;
 IF NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=actor) THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;

 -- This private argument is created only by this closed SQL operation. It holds
 -- scope metadata, never a Memory business row or a shared selected-field grant.
 IF include_memory AND native_turn_helpers_current() AND (NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND (
 m.valid_to IS NOT NULL OR m.retracted_at IS NOT NULL OR m.superseded_by IS NOT NULL OR m.source_session_id IS NOT NULL OR m.source_episode_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind='memory' AND d.resource_id=m.id)
 OR EXISTS(SELECT 1 FROM memories prior WHERE prior.workspace_id=w AND prior.superseded_by=m.id)
 OR EXISTS(SELECT 1 FROM native_memory_successor_transitions t WHERE t.workspace_id=w AND (t.predecessor_id=m.id OR t.successor_id=m.id))))
 AND NOT EXISTS(SELECT 1 FROM application_native_resource_owners o WHERE o.workspace_id=w AND o.origin='{"kind":"native","moduleKey":"native"}'::jsonb AND o.resource_type='memory')
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>'id')::uuid WHERE n->>'kind'='application_field' AND f.type_key='memory' AND (
  f.selected_version IS NOT NULL OR f.selection NOT IN('read','query','identity','query_domain')
  OR f.selection<>'query_domain' AND NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND m.id=f.resource_id)
  OR EXISTS(SELECT 1 FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=f.id AND s.version=n->>'version')))
 AND (SELECT count(*) FROM (SELECT id FROM memories WHERE workspace_id=w LIMIT 4097) bounded)<=4096) THEN
  BEGIN
   PERFORM singleton FROM application_policy_contract_epoch WHERE singleton FOR SHARE NOWAIT;
   IF NOT FOUND THEN RAISE EXCEPTION 'memory_statement_unavailable' USING ERRCODE='55P03';END IF;
   PERFORM workspace_id FROM application_policy_workspace_epochs WHERE workspace_id=w FOR SHARE NOWAIT;
   IF NOT FOUND THEN RAISE EXCEPTION 'memory_statement_unavailable' USING ERRCODE='55P03';END IF;
   PERFORM id FROM memories WHERE workspace_id=w ORDER BY id FOR SHARE NOWAIT;
   IF NOT (NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND (
 m.valid_to IS NOT NULL OR m.retracted_at IS NOT NULL OR m.superseded_by IS NOT NULL OR m.source_session_id IS NOT NULL OR m.source_episode_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind='memory' AND d.resource_id=m.id)
 OR EXISTS(SELECT 1 FROM memories prior WHERE prior.workspace_id=w AND prior.superseded_by=m.id)
 OR EXISTS(SELECT 1 FROM native_memory_successor_transitions t WHERE t.workspace_id=w AND (t.predecessor_id=m.id OR t.successor_id=m.id))))
 AND NOT EXISTS(SELECT 1 FROM application_native_resource_owners o WHERE o.workspace_id=w AND o.origin='{"kind":"native","moduleKey":"native"}'::jsonb AND o.resource_type='memory')
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>'id')::uuid WHERE n->>'kind'='application_field' AND f.type_key='memory' AND (
  f.selected_version IS NOT NULL OR f.selection NOT IN('read','query','identity','query_domain')
  OR f.selection<>'query_domain' AND NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND m.id=f.resource_id)
  OR EXISTS(SELECT 1 FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=f.id AND s.version=n->>'version')))
 AND (SELECT count(*) FROM (SELECT id FROM memories WHERE workspace_id=w LIMIT 4097) bounded)<=4096) THEN RAISE EXCEPTION 'memory_statement_unavailable' USING ERRCODE='55P03';END IF;
   memory_context:=application_memory_query_context(w);
   IF memory_context#>>'{policy,nativeDefault}' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'memory_statement_unavailable' USING ERRCODE='55P03';END IF;
   memory_rows:='{}';memory_cohort:='[]';
   FOR memory_candidate IN SELECT id,scope_version FROM memories WHERE workspace_id=w ORDER BY id LOOP
    SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),'[]') INTO memory_lineage FROM application_scope_lineage(w,ARRAY['memory'],ARRAY[memory_candidate.id],ARRAY[memory_candidate.scope_version::text]) n;
    IF memory_lineage IS DISTINCT FROM jsonb_build_array(jsonb_build_object('kind','memory','id',memory_candidate.id,'version',memory_candidate.scope_version::text)) THEN RAISE EXCEPTION 'memory_statement_unavailable' USING ERRCODE='55P03';END IF;
    memory_source:=read_admitted_native_scope_snapshot(w,'memory',memory_candidate.id);
    memory_rows:=memory_rows||jsonb_build_object(memory_candidate.id::text,jsonb_build_object('source',memory_source,'lineage',memory_lineage));
    memory_cohort:=memory_cohort||jsonb_build_array(jsonb_build_object('id',memory_candidate.id,'version',memory_candidate.scope_version::text));
   END LOOP;
   memo:=memo||jsonb_build_object('memoryStatement',jsonb_build_object('workspaceId',w,'context',memory_context,'rows',memory_rows,'cohort',memory_cohort));
  EXCEPTION WHEN lock_not_available THEN memory_rows:=NULL;memory_context:=NULL;memory_cohort:=NULL;
  END;
 END IF;
 -- Read every original field under the current actor and original selector.
 -- Parent/payload/domain checks are inside the unchanged closed evaluator.
 IF return_frame AND memo#>>'{memoryStatement,workspaceId}' IS DISTINCT FROM w::text THEN RETURN NULL;END IF;
 worklist_frame:=native_worklist_seed(w,nodes);
 IF worklist_frame IS NULL THEN RETURN NULL;END IF;
 memo:=memo||jsonb_build_object('nativeWorklist',true);

 -- Metadata-only schedule. Its bound is independent of the canonical graph
 -- limit; an overfull schedule keeps the original recursive evaluator.
 WITH RECURSIVE reach(root,node) AS (
  SELECT (n->>'kind')||':'||(n->>'id')||':'||(n->>'version'),(n->>'kind')||':'||(n->>'id')||':'||(n->>'version') FROM jsonb_array_elements(nodes) n
  UNION
  SELECT r.root,(e->>'kind')||':'||(e->>'id')||':'||(e->>'version') FROM reach r
   CROSS JOIN LATERAL jsonb_array_elements(worklist_frame#>ARRAY['edges',r.node]) e
 ), bounded AS MATERIALIZED(SELECT * FROM reach LIMIT 262145), grouped AS(
  SELECT bounded.root,coalesce(jsonb_agg('field:'||substring(bounded.node FROM 19) ORDER BY bounded.node)
   FILTER(WHERE bounded.node LIKE 'application_field:%'),'[]') fields FROM bounded GROUP BY bounded.root
 ) SELECT CASE WHEN (SELECT count(*) FROM bounded)>262144 THEN NULL ELSE
  (SELECT jsonb_object_agg(root,fields) FROM grouped) END INTO schedule;
 -- Extended empty-domain fields cannot prime ordinary native entries.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f
  ON f.workspace_id=w AND f.id=(n->>'id')::uuid WHERE n->>'kind'='application_field'
  AND(f.origin<>'{"kind":"native","moduleKey":"native"}'::jsonb OR NOT(f.type_key IN('session_message','session_message_annotation')
   OR f.type_key='memory' AND memo#>>'{memoryStatement,workspaceId}'=w::text))) THEN schedule:=NULL;END IF;
 -- Direct native/context roots and every persistent ancestor retain the same
 -- current native admission, D1 lifecycle and immutable high-water behavior.
 FOR node IN SELECT value FROM jsonb_array_elements(nodes) WHERE value->>'kind' IN('session_message','session_context_revision','memory','workspace_file') ORDER BY value->>'kind',value->>'id',value->>'version' LOOP
  IF node->>'kind'='session_context_revision' AND native_worklist_source(w,node->>'kind',(node->>'id')::uuid,worklist_frame) IS NULL THEN
   RETURN NULL;END IF;
  current_source:=native_detached_snapshot(w,node->>'kind',(node->>'id')::uuid,node->>'version',(CASE WHEN memo->'nativeWorklist'='true'::jsonb THEN worklist_frame END));
  IF current_source IS NULL THEN
   IF node->>'kind'='session_context_revision' THEN RETURN NULL;END IF;
   CONTINUE;
  END IF;
  IF current_source->>'held' IS DISTINCT FROM 'false' THEN RETURN NULL;END IF;
  current_source:=jsonb_build_object('workspaceId',w,'userId',current_source->'userId','assistantId',current_source->'assistantId',
   'sensitivity',current_source->'sensitivity','compartments',current_source->'compartments','projectIds',current_source->'projectIds',
   'resourceKind',node->'kind','resourceId',node->'id','version',current_source->'version');
  currents:=currents||jsonb_build_array(current_source);
  IF node->>'kind'='session_context_revision' THEN
   IF current_source->>'version' IS DISTINCT FROM node->>'version' THEN RETURN NULL;END IF;
   immutable:=immutable||jsonb_build_array(current_source);
  END IF;
 END LOOP;
 -- Every original derivation envelope still applies, including those on
 -- native ancestors. The full closure contains no raw Entity source; any such
 -- source already delegated above to the unchanged original evaluator.
 FOR dependency IN SELECT DISTINCT d.* FROM scope_derivations d JOIN jsonb_array_elements(nodes) ancestor(value)
  ON d.resource_kind=ancestor.value->>'kind' AND d.resource_id=(ancestor.value->>'id')::uuid WHERE d.workspace_id=w LOOP
  IF workflow_evidence_envelope_visible(w,jsonb_build_object('workspaceId',w,
   'userId',dependency.user_id,'assistantId',dependency.assistant_id,'sensitivity',dependency.sensitivity,
   'compartments',dependency.compartments,'projectIds',dependency.project_ids)) IS NOT TRUE THEN
   RETURN NULL;END IF;
 END LOOP;
 native_currents:=currents;native_immutable:=immutable;currents:='[]';immutable:='[]';
 FOR node IN SELECT value FROM jsonb_array_elements(nodes) WHERE value->>'kind'='application_field' ORDER BY coalesce(jsonb_array_length(schedule->((value->>'kind')||':'||(value->>'id')||':'||(value->>'version'))),0),value->>'id',value->>'version' LOOP
 -- A completed scope is a conjunction of already completed obligations.
 -- Never create a pending allow, overwrite a busy entry, or re-enable a reset
 -- worklist. The original evaluator remains the consumer and fallback.
 IF schedule IS NOT NULL AND memo->'nativeWorklist'='true'::jsonb AND NOT memo ? 'emptyQueries' THEN
  SELECT count(*) INTO memo_size FROM jsonb_object_keys(memo-'nativeWorklist'-'memoryStatement');
  FOR ready IN SELECT * FROM jsonb_each(schedule) WHERE key LIKE 'session_message:%'
   OR key LIKE 'session_context_revision:%' OR key LIKE 'memory:%' OR key LIKE 'workspace_file:%' LOOP
   EXIT WHEN memo_size>=4096;
   IF NOT memo ? ('native:'||ready.key) AND NOT EXISTS(
    SELECT 1 FROM jsonb_array_elements_text(ready.value) dependency_key
    WHERE memo#>>ARRAY[dependency_key,'busy']='true'
     OR scope_review_state_held('application_field',substring(dependency_key FROM 7 FOR 36)::uuid)
     OR memo#>>ARRAY[dependency_key,'value','held'] IS DISTINCT FROM 'false'
     OR memo#>ARRAY[dependency_key,'external'] IS DISTINCT FROM '[]'::jsonb) THEN
    memo:=memo||jsonb_build_object('native:'||ready.key,jsonb_build_object('value',true,'external','[]'::jsonb));
    memo_size:=memo_size+1;
   END IF;
  END LOOP;
 END IF;

  SELECT * INTO STRICT observation FROM application_field_observations WHERE workspace_id=w AND resource_id=(node->>'id')::uuid AND version=node->>'version';
  result:=native_detached_eval_field(w,(node->>'id')::uuid,node->>'version',memo,worklist_frame);memo:=coalesce(result->'memo',memo);current_source:=result->'value';
  IF current_source IS NULL OR current_source->>'held' IS DISTINCT FROM 'false' THEN RETURN NULL;END IF;
  immutable:=immutable||jsonb_build_array(observation.source_scope||jsonb_build_object('resourceKind','application_field','resourceId',observation.resource_id,'version',observation.version));
  currents:=currents||jsonb_build_array(current_source-ARRAY['held','validTo','retractedAt']);
 END LOOP;

 -- A completed scope is a conjunction of already completed obligations.
 -- Never create a pending allow, overwrite a busy entry, or re-enable a reset
 -- worklist. The original evaluator remains the consumer and fallback.
 IF schedule IS NOT NULL AND memo->'nativeWorklist'='true'::jsonb AND NOT memo ? 'emptyQueries' THEN
  SELECT count(*) INTO memo_size FROM jsonb_object_keys(memo-'nativeWorklist'-'memoryStatement');
  FOR ready IN SELECT * FROM jsonb_each(schedule) WHERE key LIKE 'session_message:%'
   OR key LIKE 'session_context_revision:%' OR key LIKE 'memory:%' OR key LIKE 'workspace_file:%' LOOP
   EXIT WHEN memo_size>=4096;
   IF NOT memo ? ('native:'||ready.key) AND NOT EXISTS(
    SELECT 1 FROM jsonb_array_elements_text(ready.value) dependency_key
    WHERE memo#>>ARRAY[dependency_key,'busy']='true'
     OR scope_review_state_held('application_field',substring(dependency_key FROM 7 FOR 36)::uuid)
     OR memo#>>ARRAY[dependency_key,'value','held'] IS DISTINCT FROM 'false'
     OR memo#>ARRAY[dependency_key,'external'] IS DISTINCT FROM '[]'::jsonb) THEN
    memo:=memo||jsonb_build_object('native:'||ready.key,jsonb_build_object('value',true,'external','[]'::jsonb));
    memo_size:=memo_size+1;
   END IF;
  END LOOP;
 END IF;

 SELECT coalesce(jsonb_agg(value ORDER BY value->>'resourceId',value->>'version'),'[]') INTO immutable FROM jsonb_array_elements(immutable);
 SELECT coalesce(jsonb_agg(value ORDER BY value->>'resourceId',value->>'version'),'[]') INTO currents FROM jsonb_array_elements(currents);
 immutable:=immutable||native_immutable;currents:=currents||native_currents;
 FOR dependency IN SELECT DISTINCT d.* FROM scope_derivations d JOIN jsonb_array_elements(nodes) ancestor(value)
  ON d.resource_kind=ancestor.value->>'kind' AND d.resource_id=(ancestor.value->>'id')::uuid WHERE d.workspace_id=w LOOP
  IF workflow_evidence_envelope_visible(w,jsonb_build_object('workspaceId',w,
   'userId',dependency.user_id,'assistantId',dependency.assistant_id,'sensitivity',dependency.sensitivity,
   'compartments',dependency.compartments,'projectIds',dependency.project_ids)) IS NOT TRUE THEN
   RETURN NULL;END IF;
 END LOOP;
 -- The evaluator contract is also current at return.
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc
  WHERE oid='public.application_session_eval_scope_current(uuid,text,uuid,text,jsonb)'::regprocedure)
  IS DISTINCT FROM 'b977bab4f04ae2d61d7c7d042225d41a97346466f95352e6f8c8e934bd2a46ca' THEN RETURN NULL;END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),'[]') INTO fresh_nodes FROM application_scope_lineage(w,kinds,ids,versions) n;
 IF nodes IS DISTINCT FROM fresh_nodes THEN RETURN NULL;END IF;
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='public.read_native_session_query_cohort_sources(uuid,text[],uuid[],text[])'::regprocedure)
  IS DISTINCT FROM 'decf5058016df0127f14f201c843b311dad798075d3a86ed41071523139c7018' THEN RETURN NULL;END IF;

 IF EXISTS(SELECT 1 FROM read_native_session_query_cohort_nodes(w,fresh_nodes)) THEN RETURN NULL;END IF;
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='public.read_native_memory_query_cohort_sources(uuid,text[],uuid[],text[])'::regprocedure)
  IS DISTINCT FROM '8a01f2a9a01cbe613ce23a519610a77e3ae8354bef88df8e99cab0d32bcc2bcd' THEN RETURN NULL;END IF;
 -- Complete current Memory query cohorts cannot hide an independent source.
 -- Metadata is not permission; any independent candidate delegates unchanged.
 IF include_memory THEN
  FOR dependency IN SELECT array_agg(candidate.source->>'resourceKind') AS kinds,
    array_agg((candidate.source->>'resourceId')::uuid) AS ids,array_agg(candidate.source->>'version') AS versions
   FROM read_native_memory_query_cohort_sources(w,kinds,ids,versions) WITH ORDINALITY candidate(source,ord)
   GROUP BY (candidate.ord-1)/100 LOOP
   IF EXISTS(SELECT 1 FROM read_external_source_dependencies(w,dependency.kinds,dependency.ids,dependency.versions)) THEN RETURN NULL;END IF;
  END LOOP;
 END IF;


 IF memo ? 'memoryStatement' THEN
  IF native_turn_helpers_current() IS NOT TRUE OR application_memory_query_context(w) IS DISTINCT FROM memory_context OR NOT (NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND (
 m.valid_to IS NOT NULL OR m.retracted_at IS NOT NULL OR m.superseded_by IS NOT NULL OR m.source_session_id IS NOT NULL OR m.source_episode_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind='memory' AND d.resource_id=m.id)
 OR EXISTS(SELECT 1 FROM memories prior WHERE prior.workspace_id=w AND prior.superseded_by=m.id)
 OR EXISTS(SELECT 1 FROM native_memory_successor_transitions t WHERE t.workspace_id=w AND (t.predecessor_id=m.id OR t.successor_id=m.id))))
 AND NOT EXISTS(SELECT 1 FROM application_native_resource_owners o WHERE o.workspace_id=w AND o.origin='{"kind":"native","moduleKey":"native"}'::jsonb AND o.resource_type='memory')
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>'id')::uuid WHERE n->>'kind'='application_field' AND f.type_key='memory' AND (
  f.selected_version IS NOT NULL OR f.selection NOT IN('read','query','identity','query_domain')
  OR f.selection<>'query_domain' AND NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND m.id=f.resource_id)
  OR EXISTS(SELECT 1 FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=f.id AND s.version=n->>'version')))
 AND (SELECT count(*) FROM (SELECT id FROM memories WHERE workspace_id=w LIMIT 4097) bounded)<=4096) THEN RETURN NULL;END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'version',scope_version::text) ORDER BY id),'[]') INTO memory_cohort FROM memories WHERE workspace_id=w;
  IF memory_cohort IS DISTINCT FROM memo#>'{memoryStatement,cohort}' THEN RETURN NULL;END IF;
  FOR memory_candidate IN SELECT id,scope_version FROM memories WHERE workspace_id=w ORDER BY id LOOP
   memory_source:=read_admitted_native_scope_snapshot(w,'memory',memory_candidate.id);
   SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),'[]') INTO memory_lineage FROM application_scope_lineage(w,ARRAY['memory'],ARRAY[memory_candidate.id],ARRAY[memory_candidate.scope_version::text]) n;
   IF memory_source IS DISTINCT FROM memory_rows#>ARRAY[memory_candidate.id::text,'source'] OR memory_lineage IS DISTINCT FROM memory_rows#>ARRAY[memory_candidate.id::text,'lineage'] THEN RETURN NULL;END IF;
  END LOOP;
 END IF;

 IF native_turn_helpers_current() IS NOT TRUE
  OR (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc
   WHERE oid='public.read_native_session_cohort_evidence(uuid,text[],uuid[],text[],boolean)'::regprocedure)
   IS DISTINCT FROM '2afff03ed88d3de82386880a3b582bbfa2c4379b06ecbc06fd98ff467f60c376' THEN RETURN NULL;END IF;
 IF native_worklist_frame_current(w,worklist_frame) IS NOT TRUE THEN RETURN NULL;END IF;
 IF application_native_worklist_helpers_current() IS NOT TRUE THEN RETURN NULL;END IF;
 -- Native worklists are invocation-local. Only the original canonical memo
 -- entries may cross into the existing independently revalidated capture path.
 memo:=memo-'nativeWorklist';
 IF return_frame THEN RETURN jsonb_build_object('admitted',true,'immutable',immutable,'current',currents,'memo',memo,'lineage',fresh_nodes);END IF;
 RETURN jsonb_build_object('admitted',true,'immutable',immutable,'current',currents);
EXCEPTION WHEN data_exception OR insufficient_privilege OR no_data_found THEN RETURN NULL;
 WHEN raise_exception THEN
  IF SQLERRM IN('page_ancestry_unavailable','scope_source_changed','scope_evidence_missing','scope_operation_denied','access_unavailable','scope_ancestry_unavailable') THEN RETURN NULL;END IF;
  RAISE;
END

DECLARE nodes jsonb;selector record;candidate record;root jsonb;attempts integer:=0;
BEGIN
 SELECT coalesce(jsonb_agg(to_jsonb(n)),'[]') INTO nodes FROM application_scope_lineage(w,kinds,ids,versions) n;
 FOR selector IN SELECT DISTINCT q.domain FROM jsonb_to_recordset(nodes) n(kind text,id uuid,version text)
  JOIN application_field_resources f ON f.workspace_id=w AND f.id=n.id AND n.kind='application_field'
  JOIN application_field_observations o ON o.workspace_id=w AND o.resource_id=f.id AND o.version=n.version
  JOIN application_query_domains q ON q.workspace_id=w AND q.id=f.resource_id AND q.type_key=f.type_key AND q.origin=f.origin
  WHERE f.origin='{"kind":"native","moduleKey":"native"}' AND f.type_key='memory' AND f.selection='query_domain' LOOP
  IF selector.domain->>'kind' IS DISTINCT FROM 'memory_query_domain_v1' OR application_query_scope_valid(selector.domain->'bounds') IS NOT TRUE THEN
   RAISE EXCEPTION 'scope_ancestry_unavailable' USING ERRCODE='22023';END IF;
  IF selector.domain->>'includeRetained' IS DISTINCT FROM 'true' THEN CONTINUE;END IF;
  FOR candidate IN SELECT id FROM memories WHERE workspace_id=w ORDER BY id LOOP
   attempts:=attempts+1;IF attempts>4096 THEN RAISE EXCEPTION 'scope_ancestry_unavailable' USING ERRCODE='22023';END IF;
   root:=read_scope_source(w,'memory',candidate.id);
   IF root IS NULL OR root->>'held' IS DISTINCT FROM 'false' OR application_query_scope_admits_point(selector.domain->'bounds',root) IS NOT TRUE THEN CONTINUE;END IF;
   source:=jsonb_build_object('workspaceId',w,'userId',root->'userId','assistantId',root->'assistantId','sensitivity',root->'sensitivity',
    'compartments',root->'compartments','projectIds',root->'projectIds','resourceKind','memory','resourceId',candidate.id,'version',root->'version');RETURN NEXT;
  END LOOP;
 END LOOP;
END

DECLARE actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
 assistant uuid:=nullif(current_setting('app.v2_assistant_id',true),'')::uuid;
 position integer;head uuid;nodes jsonb;proof jsonb;root jsonb;sources jsonb:='[]';payload jsonb;rows_json jsonb:='[]';
BEGIN
 IF application_native_title_group_helpers_current() IS NOT TRUE THEN RETURN NULL;END IF;
 IF actor IS NULL OR assistant IS NULL OR session_ids IS NULL OR revision_ids IS NULL
  OR array_ndims(session_ids)<>1 OR array_lower(session_ids,1)<>1 OR array_ndims(revision_ids)<>1 OR array_lower(revision_ids,1)<>1
  OR cardinality(session_ids) NOT BETWEEN 2 AND 50 OR cardinality(session_ids)<>cardinality(revision_ids)
  OR array_position(session_ids,NULL) IS NOT NULL OR array_position(revision_ids,NULL) IS NOT NULL
  OR (SELECT count(DISTINCT id) FROM unnest(session_ids) id)<>cardinality(session_ids)
  OR nullif(current_setting('app.application_id',true),'') IS NOT NULL OR nullif(current_setting('app.public_share_root',true),'') IS NOT NULL
  OR current_setting('app.agent_shared_audience',true)='true'
  OR EXISTS(SELECT 1 FROM pg_roles role JOIN pg_class owned ON owned.oid='public.session_context_revision_contents'::regclass
   WHERE role.rolname=session_user AND(role.rolsuper OR role.rolbypassrls OR pg_has_role(role.oid,owned.relowner,'USAGE'))) THEN RETURN NULL;END IF;
 -- Every original head and parent stays bound to its own session. The SHARE
 -- lock is the canonical title reader's lock, held until this read commits.
 FOR position IN 1..cardinality(session_ids) LOOP
  IF NOT EXISTS(SELECT 1 FROM sessions s WHERE s.workspace_id=w AND s.id=session_ids[position]
   AND s.user_id=actor AND s.assistant_id=assistant AND s.visibility='personal' AND s.channel_type='web' AND s.anchor_kind='none')
   OR session_recording_read_allowed(session_ids[position]) IS NOT TRUE
   OR recording_source_read_allowed(w,'session_context_revision',revision_ids[position]) IS NOT TRUE THEN RETURN NULL;END IF;
  SELECT h.scope_revision_id INTO head FROM session_title_heads h WHERE h.workspace_id=w AND h.session_id=session_ids[position] FOR SHARE;
  IF head IS DISTINCT FROM revision_ids[position] OR NOT EXISTS(SELECT 1 FROM session_context_scope_revisions r
   WHERE r.workspace_id=w AND r.id=revision_ids[position] AND r.session_id=session_ids[position]
    AND r.parent_kind='session_title' AND r.parent_id=session_ids[position]) THEN RETURN NULL;END IF;
  root:=read_entity_derivation_source(w,'session_context_revision',revision_ids[position]);
  IF root IS NULL OR root->>'held' IS DISTINCT FROM 'false' OR root->>'version' IS DISTINCT FROM '1' THEN RETURN NULL;END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(node)),'[]') INTO nodes
   FROM application_scope_lineage(w,ARRAY['session_context_revision'],ARRAY[revision_ids[position]],ARRAY['1']) node;
  -- Keep the exact ordinary Memory/file title branch. Other purposes use
  -- the unchanged individual reader, including selected Memory history.
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n WHERE n->>'kind'='workspace_file')
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f
    ON f.workspace_id=w AND f.id=(n->>'id')::uuid WHERE n->>'kind'='application_field'
     AND f.origin='{"kind":"native","moduleKey":"native"}'::jsonb AND f.type_key='memory' AND f.selection='query_domain')
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f
    ON f.workspace_id=w AND f.id=(n->>'id')::uuid WHERE n->>'kind'='application_field'
     AND f.type_key='memory' AND (f.selected_version IS NOT NULL OR f.selection<>'query_domain')) THEN RETURN NULL;END IF;
  sources:=sources||jsonb_build_array(jsonb_build_object('workspaceId',root->'workspaceId','userId',root->'userId','assistantId',root->'assistantId',
   'sensitivity',root->'sensitivity','compartments',root->'compartments','projectIds',root->'projectIds',
   'resourceKind','session_context_revision','resourceId',revision_ids[position],'version','1'));
 END LOOP;
 proof:=capture_conversation_evidence(w,(SELECT jsonb_agg(jsonb_build_object(
   'kind','session_context_revision','id',id,'version','1') ORDER BY ordinal)
   FROM unnest(revision_ids) WITH ORDINALITY input(id,ordinal)));
 IF proof->>'admitted' IS DISTINCT FROM 'true' OR NOT coalesce(proof->'immutable' @> sources,false) THEN RETURN NULL;END IF;
 FOR position IN 1..cardinality(session_ids) LOOP
  SELECT c.content INTO payload FROM session_context_revision_contents c WHERE c.workspace_id=w AND c.revision_id=revision_ids[position];
  IF payload IS NULL THEN RETURN NULL;END IF;
  rows_json:=rows_json||jsonb_build_array(jsonb_build_object('sessionId',session_ids[position],'revisionId',revision_ids[position],
   'content',payload,'source',sources->(position-1)));
 END LOOP;
 IF application_native_title_group_helpers_current() IS NOT TRUE THEN RETURN NULL;END IF;
 RETURN rows_json;
EXCEPTION WHEN invalid_parameter_value THEN
 IF SQLERRM='scope_ancestry_unavailable' THEN RETURN NULL;END IF;
 RAISE;
END

' THEN RETURN NULL;END IF;
 IF application_native_title_acquisition_helpers_current() IS NOT TRUE THEN RETURN NULL;END IF;
 -- A broadened facade ACL cannot grant a caller the original reader's authority.
 IF has_function_privilege(session_user,'public.read_native_personal_title_group(uuid,uuid[],uuid[])','EXECUTE') IS NOT TRUE THEN RETURN NULL;END IF;
 captured:=native_personal_title_group_acquisition(w,session_ids,revision_ids);
 IF (SELECT encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') FROM pg_catalog.pg_proc p
  WHERE p.oid='public.application_native_title_acquisition_helpers_current()'::regprocedure) IS DISTINCT FROM '

' THEN RETURN NULL;END IF;
 IF application_native_title_acquisition_helpers_current() IS NOT TRUE THEN RETURN NULL;END IF;
 RETURN captured;
END

DECLARE actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;nodes jsonb;node jsonb;
 observation application_field_observations;memo jsonb:='{}';result jsonb;current_source jsonb;
 immutable jsonb:='[]';currents jsonb:='[]';dependency record;fresh_nodes jsonb;memory_candidate record;memory_rows jsonb;memory_cohort jsonb;memory_context jsonb;memory_lineage jsonb;memory_source jsonb;
BEGIN
 IF kinds IS NULL OR ids IS NULL OR versions IS NULL OR cardinality(ids) NOT BETWEEN 1 AND 100
  OR cardinality(kinds)<>cardinality(ids) OR cardinality(versions)<>cardinality(ids)
  OR array_position(kinds,NULL) IS NOT NULL OR array_position(ids,NULL) IS NOT NULL OR array_position(versions,NULL) IS NOT NULL THEN
  RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 -- A changed original evaluator retains its full original fallback contract.
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc
  WHERE oid='public.application_session_eval_scope_current(uuid,text,uuid,text,jsonb)'::regprocedure)
  IS DISTINCT FROM 'b977bab4f04ae2d61d7c7d042225d41a97346466f95352e6f8c8e934bd2a46ca' THEN RETURN NULL;END IF;
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='public.read_native_session_query_cohort_sources(uuid,text[],uuid[],text[])'::regprocedure)
  IS DISTINCT FROM 'decf5058016df0127f14f201c843b311dad798075d3a86ed41071523139c7018' THEN RETURN NULL;END IF;
 -- Every other profile/resource family delegates to the original validator.
 IF actor IS NULL OR nullif(current_setting('app.application_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.public_share_root',true),'') IS NOT NULL
  OR EXISTS(SELECT 1 FROM unnest(kinds) kind WHERE kind NOT IN('application_field','session_context_revision','session_message','memory')) OR NOT include_memory AND 'memory'=ANY(kinds) THEN RETURN NULL;END IF;
 IF EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='session_messages'::regclass WHERE r.rolname=session_user
  AND(r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,'USAGE'))) THEN RETURN NULL;END IF;
 -- Ineligible root metadata adds no native lock or full-closure walk.
 IF EXISTS(SELECT 1 FROM unnest(kinds,ids) root(kind,id)
  LEFT JOIN application_field_resources field ON field.workspace_id=w AND field.id=root.id
  WHERE root.kind='application_field' AND(field.id IS NULL OR field.origin<>'{"kind":"native","moduleKey":"native"}'::jsonb
   OR NOT(field.type_key IN('session_message','session_message_annotation') OR include_memory AND field.type_key='memory'))) THEN RETURN NULL;END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),'[]') INTO nodes FROM application_scope_lineage(w,kinds,ids,versions) n;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n WHERE n->>'kind' NOT IN('application_field','application_query_domain','session_context_revision','session_message','memory'))
  OR NOT include_memory AND EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n WHERE n->>'kind'='memory')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n LEFT JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>'id')::uuid
   WHERE n->>'kind'='application_field' AND(f.id IS NULL OR f.origin<>'{"kind":"native","moduleKey":"native"}'::jsonb OR NOT(f.type_key IN('session_message','session_message_annotation') OR include_memory AND f.type_key='memory'))) THEN RETURN NULL;END IF;
 -- Source-denied physical candidates still require fresh remote cohort
 -- context. No fast-path admission is inferred from the original closure.
 IF EXISTS(SELECT 1 FROM read_native_session_query_cohort_nodes(w,nodes)) THEN RETURN NULL;END IF;
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='public.read_native_memory_query_cohort_sources(uuid,text[],uuid[],text[])'::regprocedure)
  IS DISTINCT FROM '8a01f2a9a01cbe613ce23a519610a77e3ae8354bef88df8e99cab0d32bcc2bcd' THEN RETURN NULL;END IF;
 -- Complete current Memory query cohorts cannot hide an independent source.
 -- Metadata is not permission; any independent candidate delegates unchanged.
 IF include_memory THEN
  FOR dependency IN SELECT array_agg(candidate.source->>'resourceKind') AS kinds,
    array_agg((candidate.source->>'resourceId')::uuid) AS ids,array_agg(candidate.source->>'version') AS versions
   FROM read_native_memory_query_cohort_sources(w,kinds,ids,versions) WITH ORDINALITY candidate(source,ord)
   GROUP BY (candidate.ord-1)/100 LOOP
   IF EXISTS(SELECT 1 FROM read_external_source_dependencies(w,dependency.kinds,dependency.ids,dependency.versions)) THEN RETURN NULL;END IF;
  END LOOP;
 END IF;

 PERFORM id FROM workspaces WHERE id=w FOR SHARE;
 IF NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=actor) THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;

 -- This private argument is created only by this closed SQL operation. It holds
 -- scope metadata, never a Memory business row or a shared selected-field grant.
 IF include_memory AND native_turn_helpers_current() AND (NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND (
 m.valid_to IS NOT NULL OR m.retracted_at IS NOT NULL OR m.superseded_by IS NOT NULL OR m.source_session_id IS NOT NULL OR m.source_episode_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind='memory' AND d.resource_id=m.id)
 OR EXISTS(SELECT 1 FROM memories prior WHERE prior.workspace_id=w AND prior.superseded_by=m.id)
 OR EXISTS(SELECT 1 FROM native_memory_successor_transitions t WHERE t.workspace_id=w AND (t.predecessor_id=m.id OR t.successor_id=m.id))))
 AND NOT EXISTS(SELECT 1 FROM application_native_resource_owners o WHERE o.workspace_id=w AND o.origin='{"kind":"native","moduleKey":"native"}'::jsonb AND o.resource_type='memory')
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>'id')::uuid WHERE n->>'kind'='application_field' AND f.type_key='memory' AND (
  f.selected_version IS NOT NULL OR f.selection NOT IN('read','query','identity','query_domain')
  OR f.selection<>'query_domain' AND NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND m.id=f.resource_id)
  OR EXISTS(SELECT 1 FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=f.id AND s.version=n->>'version')))
 AND (SELECT count(*) FROM (SELECT id FROM memories WHERE workspace_id=w LIMIT 4097) bounded)<=4096) THEN
  BEGIN
   PERFORM singleton FROM application_policy_contract_epoch WHERE singleton FOR SHARE NOWAIT;
   IF NOT FOUND THEN RAISE EXCEPTION 'memory_statement_unavailable' USING ERRCODE='55P03';END IF;
   PERFORM workspace_id FROM application_policy_workspace_epochs WHERE workspace_id=w FOR SHARE NOWAIT;
   IF NOT FOUND THEN RAISE EXCEPTION 'memory_statement_unavailable' USING ERRCODE='55P03';END IF;
   PERFORM id FROM memories WHERE workspace_id=w ORDER BY id FOR SHARE NOWAIT;
   IF NOT (NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND (
 m.valid_to IS NOT NULL OR m.retracted_at IS NOT NULL OR m.superseded_by IS NOT NULL OR m.source_session_id IS NOT NULL OR m.source_episode_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind='memory' AND d.resource_id=m.id)
 OR EXISTS(SELECT 1 FROM memories prior WHERE prior.workspace_id=w AND prior.superseded_by=m.id)
 OR EXISTS(SELECT 1 FROM native_memory_successor_transitions t WHERE t.workspace_id=w AND (t.predecessor_id=m.id OR t.successor_id=m.id))))
 AND NOT EXISTS(SELECT 1 FROM application_native_resource_owners o WHERE o.workspace_id=w AND o.origin='{"kind":"native","moduleKey":"native"}'::jsonb AND o.resource_type='memory')
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>'id')::uuid WHERE n->>'kind'='application_field' AND f.type_key='memory' AND (
  f.selected_version IS NOT NULL OR f.selection NOT IN('read','query','identity','query_domain')
  OR f.selection<>'query_domain' AND NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND m.id=f.resource_id)
  OR EXISTS(SELECT 1 FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=f.id AND s.version=n->>'version')))
 AND (SELECT count(*) FROM (SELECT id FROM memories WHERE workspace_id=w LIMIT 4097) bounded)<=4096) THEN RAISE EXCEPTION 'memory_statement_unavailable' USING ERRCODE='55P03';END IF;
   memory_context:=application_memory_query_context(w);
   IF memory_context#>>'{policy,nativeDefault}' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'memory_statement_unavailable' USING ERRCODE='55P03';END IF;
   memory_rows:='{}';memory_cohort:='[]';
   FOR memory_candidate IN SELECT id,scope_version FROM memories WHERE workspace_id=w ORDER BY id LOOP
    SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),'[]') INTO memory_lineage FROM application_scope_lineage(w,ARRAY['memory'],ARRAY[memory_candidate.id],ARRAY[memory_candidate.scope_version::text]) n;
    IF memory_lineage IS DISTINCT FROM jsonb_build_array(jsonb_build_object('kind','memory','id',memory_candidate.id,'version',memory_candidate.scope_version::text)) THEN RAISE EXCEPTION 'memory_statement_unavailable' USING ERRCODE='55P03';END IF;
    memory_source:=read_admitted_native_scope_snapshot(w,'memory',memory_candidate.id);
    memory_rows:=memory_rows||jsonb_build_object(memory_candidate.id::text,jsonb_build_object('source',memory_source,'lineage',memory_lineage));
    memory_cohort:=memory_cohort||jsonb_build_array(jsonb_build_object('id',memory_candidate.id,'version',memory_candidate.scope_version::text));
   END LOOP;
   memo:=memo||jsonb_build_object('memoryStatement',jsonb_build_object('workspaceId',w,'context',memory_context,'rows',memory_rows,'cohort',memory_cohort));
  EXCEPTION WHEN lock_not_available THEN memory_rows:=NULL;memory_context:=NULL;memory_cohort:=NULL;
  END;
 END IF;
 -- Read every original field under the current actor and original selector.
 -- Parent/payload/domain checks are inside the unchanged closed evaluator.
 FOR node IN SELECT value FROM jsonb_array_elements(nodes) WHERE value->>'kind'='application_field' ORDER BY value->>'id',value->>'version' LOOP
  SELECT * INTO STRICT observation FROM application_field_observations WHERE workspace_id=w AND resource_id=(node->>'id')::uuid AND version=node->>'version';
  result:=application_session_eval_field(w,(node->>'id')::uuid,node->>'version',memo);memo:=coalesce(result->'memo',memo);current_source:=result->'value';
  IF current_source IS NULL OR current_source->>'held' IS DISTINCT FROM 'false' THEN RETURN jsonb_build_object('admitted',false);END IF;
  immutable:=immutable||jsonb_build_array(observation.source_scope||jsonb_build_object('resourceKind','application_field','resourceId',observation.resource_id,'version',observation.version));
  currents:=currents||jsonb_build_array(current_source-ARRAY['held','validTo','retractedAt']);
 END LOOP;
 -- Direct native/context roots and every persistent ancestor retain the same
 -- current native admission, D1 lifecycle and immutable high-water behavior.
 FOR node IN SELECT value FROM jsonb_array_elements(nodes) WHERE value->>'kind' IN('session_message','session_context_revision','memory') ORDER BY value->>'kind',value->>'id',value->>'version' LOOP
  IF node->>'kind'='session_context_revision' AND read_entity_derivation_source(w,node->>'kind',(node->>'id')::uuid) IS NULL THEN
   RETURN jsonb_build_object('admitted',false);END IF;
  current_source:=read_admitted_native_scope_snapshot(w,node->>'kind',(node->>'id')::uuid);
  IF current_source IS NULL THEN
   IF node->>'kind'='session_context_revision' THEN RETURN jsonb_build_object('admitted',false);END IF;
   CONTINUE;
  END IF;
  IF current_source->>'held' IS DISTINCT FROM 'false' THEN RETURN jsonb_build_object('admitted',false);END IF;
  current_source:=jsonb_build_object('workspaceId',w,'userId',current_source->'userId','assistantId',current_source->'assistantId',
   'sensitivity',current_source->'sensitivity','compartments',current_source->'compartments','projectIds',current_source->'projectIds',
   'resourceKind',node->'kind','resourceId',node->'id','version',current_source->'version');
  currents:=currents||jsonb_build_array(current_source);
  IF node->>'kind'='session_context_revision' THEN
   IF current_source->>'version' IS DISTINCT FROM node->>'version' THEN RETURN jsonb_build_object('admitted',false);END IF;
   immutable:=immutable||jsonb_build_array(current_source);
  END IF;
 END LOOP;
 -- Every original derivation envelope still applies, including those on
 -- native ancestors. The full closure contains no raw Entity source; any such
 -- source already delegated above to the unchanged original evaluator.
 FOR dependency IN SELECT DISTINCT d.* FROM scope_derivations d JOIN jsonb_array_elements(nodes) ancestor(value)
  ON d.resource_kind=ancestor.value->>'kind' AND d.resource_id=(ancestor.value->>'id')::uuid WHERE d.workspace_id=w LOOP
  IF workflow_evidence_envelope_visible(w,jsonb_build_object('workspaceId',w,
   'userId',dependency.user_id,'assistantId',dependency.assistant_id,'sensitivity',dependency.sensitivity,
   'compartments',dependency.compartments,'projectIds',dependency.project_ids)) IS NOT TRUE THEN
   RETURN jsonb_build_object('admitted',false);END IF;
 END LOOP;
 -- The evaluator contract is also current at return.
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc
  WHERE oid='public.application_session_eval_scope_current(uuid,text,uuid,text,jsonb)'::regprocedure)
  IS DISTINCT FROM 'b977bab4f04ae2d61d7c7d042225d41a97346466f95352e6f8c8e934bd2a46ca' THEN RETURN NULL;END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),'[]') INTO fresh_nodes FROM application_scope_lineage(w,kinds,ids,versions) n;
 IF nodes IS DISTINCT FROM fresh_nodes THEN RETURN jsonb_build_object('admitted',false);END IF;
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='public.read_native_session_query_cohort_sources(uuid,text[],uuid[],text[])'::regprocedure)
  IS DISTINCT FROM 'decf5058016df0127f14f201c843b311dad798075d3a86ed41071523139c7018' THEN RETURN NULL;END IF;

 IF EXISTS(SELECT 1 FROM read_native_session_query_cohort_nodes(w,fresh_nodes)) THEN RETURN jsonb_build_object('admitted',false);END IF;
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='public.read_native_memory_query_cohort_sources(uuid,text[],uuid[],text[])'::regprocedure)
  IS DISTINCT FROM '8a01f2a9a01cbe613ce23a519610a77e3ae8354bef88df8e99cab0d32bcc2bcd' THEN RETURN NULL;END IF;
 -- Complete current Memory query cohorts cannot hide an independent source.
 -- Metadata is not permission; any independent candidate delegates unchanged.
 IF include_memory THEN
  FOR dependency IN SELECT array_agg(candidate.source->>'resourceKind') AS kinds,
    array_agg((candidate.source->>'resourceId')::uuid) AS ids,array_agg(candidate.source->>'version') AS versions
   FROM read_native_memory_query_cohort_sources(w,kinds,ids,versions) WITH ORDINALITY candidate(source,ord)
   GROUP BY (candidate.ord-1)/100 LOOP
   IF EXISTS(SELECT 1 FROM read_external_source_dependencies(w,dependency.kinds,dependency.ids,dependency.versions)) THEN RETURN NULL;END IF;
  END LOOP;
 END IF;


 IF memo ? 'memoryStatement' THEN
  IF native_turn_helpers_current() IS NOT TRUE OR application_memory_query_context(w) IS DISTINCT FROM memory_context OR NOT (NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND (
 m.valid_to IS NOT NULL OR m.retracted_at IS NOT NULL OR m.superseded_by IS NOT NULL OR m.source_session_id IS NOT NULL OR m.source_episode_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind='memory' AND d.resource_id=m.id)
 OR EXISTS(SELECT 1 FROM memories prior WHERE prior.workspace_id=w AND prior.superseded_by=m.id)
 OR EXISTS(SELECT 1 FROM native_memory_successor_transitions t WHERE t.workspace_id=w AND (t.predecessor_id=m.id OR t.successor_id=m.id))))
 AND NOT EXISTS(SELECT 1 FROM application_native_resource_owners o WHERE o.workspace_id=w AND o.origin='{"kind":"native","moduleKey":"native"}'::jsonb AND o.resource_type='memory')
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>'id')::uuid WHERE n->>'kind'='application_field' AND f.type_key='memory' AND (
  f.selected_version IS NOT NULL OR f.selection NOT IN('read','query','identity','query_domain')
  OR f.selection<>'query_domain' AND NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND m.id=f.resource_id)
  OR EXISTS(SELECT 1 FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=f.id AND s.version=n->>'version')))
 AND (SELECT count(*) FROM (SELECT id FROM memories WHERE workspace_id=w LIMIT 4097) bounded)<=4096) THEN RETURN NULL;END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'version',scope_version::text) ORDER BY id),'[]') INTO memory_cohort FROM memories WHERE workspace_id=w;
  IF memory_cohort IS DISTINCT FROM memo#>'{memoryStatement,cohort}' THEN RETURN NULL;END IF;
  FOR memory_candidate IN SELECT id,scope_version FROM memories WHERE workspace_id=w ORDER BY id LOOP
   memory_source:=read_admitted_native_scope_snapshot(w,'memory',memory_candidate.id);
   SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),'[]') INTO memory_lineage FROM application_scope_lineage(w,ARRAY['memory'],ARRAY[memory_candidate.id],ARRAY[memory_candidate.scope_version::text]) n;
   IF memory_source IS DISTINCT FROM memory_rows#>ARRAY[memory_candidate.id::text,'source'] OR memory_lineage IS DISTINCT FROM memory_rows#>ARRAY[memory_candidate.id::text,'lineage'] THEN RETURN NULL;END IF;
  END LOOP;
 END IF;
 RETURN jsonb_build_object('admitted',true,'immutable',immutable,'current',currents);
END

DECLARE actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;nodes jsonb;node jsonb;
