DECLARE s sessions; held boolean;
BEGIN
 IF k<>'browser_session' THEN RETURN read_scope_source_before_browser_session(w,k,i); END IF;
 PERFORM id FROM workspaces WHERE id=w FOR SHARE;
 SELECT * INTO s FROM sessions WHERE workspace_id=w AND id=i FOR SHARE;
 IF NOT FOUND THEN RETURN NULL; END IF;
 PERFORM id FROM assistants WHERE workspace_id=w AND id=s.assistant_id FOR SHARE;
 IF NOT FOUND THEN RETURN NULL; END IF;
 -- Only a personal, unanchored web conversation is a browser-session source.
 held:=s.channel_type IS DISTINCT FROM 'web' OR s.visibility IS DISTINCT FROM 'personal' OR s.anchor_kind<>'none'
  OR s.context_locked_at IS NULL OR s.context_binding_origin='held' OR s.context_compartments IS NULL
  OR (s.context_group_id IS NOT NULL AND NOT ('team:'||s.context_group_id::text)=ANY(s.context_compartments))
  OR EXISTS(SELECT 1 FROM unnest(s.context_compartments) label WHERE label IS NULL OR NOT EXISTS(
   SELECT 1 FROM workspace_groups g WHERE g.workspace_id=w AND g.kind='team' AND g.compartment_key=label))
  OR (s.context_project_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM workspace_projects p
   WHERE p.workspace_id=w AND p.id=s.context_project_id));
 RETURN jsonb_build_object('workspaceId',w,'resourceKind',k,'resourceId',i,'version',s.browser_source_version::text,
  'userId',s.user_id,'assistantId',NULL,'sensitivity',coalesce(s.effective_clearance,'public'),
  'compartments',to_jsonb(s.context_compartments),'projectIds',CASE WHEN s.context_project_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(s.context_project_id) END,
  'held',held,'validTo',NULL,'retractedAt',NULL);
END

DECLARE result jsonb;
BEGIN
 -- Recording privacy admission precedes body selection.
 IF NOT recording_source_read_allowed(w,'session_context_revision',i) THEN RETURN NULL;END IF;
 IF EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='session_context_revision_contents'::regclass
   WHERE r.rolname=session_user AND (r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,'USAGE')))
  OR session_context_revision_allowed(w,i) IS NOT TRUE THEN RETURN NULL;END IF;
 SELECT c.content INTO result FROM session_context_revision_contents c WHERE c.workspace_id=w AND c.revision_id=i;
 RETURN result;
END

DECLARE current_revision uuid;
BEGIN
 -- Recording privacy admission precedes body selection.
 IF NOT session_recording_read_allowed(s) THEN RETURN NULL;END IF;
 PERFORM id FROM workspaces WHERE id=w FOR SHARE;
 SELECT h.scope_revision_id INTO current_revision FROM session_title_heads h
  WHERE h.workspace_id=w AND h.session_id=s FOR SHARE;
 IF current_revision IS DISTINCT FROM i OR NOT EXISTS(SELECT 1 FROM session_context_scope_revisions r
  WHERE r.workspace_id=w AND r.id=i AND r.session_id=s AND r.parent_kind='session_title' AND r.parent_id=s) THEN RETURN NULL;END IF;
 RETURN read_session_context_revision(w,i);
END

DECLARE context_room boolean;previous_check text;expected jsonb;identity jsonb;generation integer;
BEGIN
 SELECT provider_conversation_context,provider_context_identity,provider_context_generation INTO context_room,identity,generation FROM sessions WHERE id=NEW.session_id FOR UPDATE;
 IF context_room THEN
  expected:=nullif(current_setting('app.provider_conversation_expected',true),'')::jsonb;
  IF expected IS DISTINCT FROM jsonb_build_object('identity',identity,'generation',generation) THEN
   RAISE EXCEPTION 'provider_context_unavailable' USING ERRCODE='42501';END IF;
  previous_check:=current_setting('app.provider_conversation_context_check',true);
  PERFORM set_config('app.provider_conversation_context_check',NEW.session_id::text,true);
  UPDATE sessions SET last_active_at=last_active_at WHERE id=NEW.session_id;
  PERFORM set_config('app.provider_conversation_context_check',coalesce(previous_check,''),true);
 END IF;
 IF NOT session_recording_read_allowed(NEW.session_id) THEN
  RAISE EXCEPTION 'recording_privacy_review_required' USING ERRCODE='42501';
 END IF;
 RETURN NEW;
END

BEGIN

 IF k='private_transcript' THEN
  RETURN QUERY SELECT id FROM private_transcript_observations WHERE workspace_id=w AND id=i;
  RETURN;
 END IF;

 IF k='office_observation' THEN
  RETURN QUERY SELECT id FROM office_scope_observations WHERE workspace_id=w AND id=i;
  RETURN;
 END IF;
 IF k='workflow_run' THEN
  RETURN QUERY WITH RECURSIVE consumers(id) AS (
   SELECT i UNION SELECT s.run_id FROM workflow_run_copy_sources s JOIN consumers c ON c.id=s.source_run_id WHERE s.workspace_id=w
  ) SELECT id FROM consumers;
 ELSE RETURN QUERY SELECT * FROM scope_source_ancestors_before_workflow_run(w,k,i); END IF;
END

DECLARE tab text; versioned boolean;
BEGIN
  -- These are the same workspace-scoped column walks, with static plans.
  IF p_kind='memory' THEN
    RETURN QUERY WITH RECURSIVE ancestry(id) AS (
      SELECT id FROM memories WHERE workspace_id=p_workspace AND id=p_id
      UNION SELECT r.id FROM memories r JOIN ancestry a ON r.superseded_by=a.id WHERE r.workspace_id=p_workspace
    ) SELECT id FROM ancestry;
    RETURN;
  ELSIF p_kind='session_message' THEN
    RETURN QUERY SELECT id FROM session_messages WHERE workspace_id=p_workspace AND id=p_id;
    RETURN;
  ELSIF p_kind='session_context_revision' THEN
    RETURN QUERY SELECT id FROM session_context_scope_revisions WHERE workspace_id=p_workspace AND id=p_id;
    RETURN;
  END IF;
  IF p_kind IN('crm_event','memory_verification','brain_verification','correction_audit') THEN RETURN QUERY SELECT p_id; RETURN; END IF;
  tab=scope_source_table(p_kind);
  IF tab IS NULL THEN RAISE EXCEPTION 'scope_evidence_missing'; END IF;
  SELECT EXISTS(
    SELECT 1 FROM pg_attribute
     WHERE attrelid=format('%I',tab)::regclass AND attname='superseded_by' AND NOT attisdropped
  ) INTO versioned;

  -- Retain the live canonical mapping and column-shape decision above.
  -- Schema changes or a replacement mapping use the original dynamic branch.
  IF p_kind='workspace_file' AND tab='workspace_files' AND versioned THEN
    RETURN QUERY WITH RECURSIVE ancestry(id) AS (
      SELECT id FROM workspace_files WHERE workspace_id=p_workspace AND id=p_id
      UNION SELECT r.id FROM workspace_files r JOIN ancestry a ON r.superseded_by=a.id WHERE r.workspace_id=p_workspace
    ) SELECT id FROM ancestry;
    RETURN;
  END IF;
  IF NOT versioned THEN
    RETURN QUERY EXECUTE format('SELECT id FROM %I WHERE workspace_id=$2 AND id=$1',tab) USING p_id,p_workspace;
    RETURN;
  END IF;
  RETURN QUERY EXECUTE format('WITH RECURSIVE ancestry(id) AS (
    SELECT id FROM %I WHERE workspace_id=$2 AND id=$1
    UNION SELECT r.id FROM %I r JOIN ancestry a ON r.superseded_by=a.id WHERE r.workspace_id=$2)
    SELECT id FROM ancestry',tab,tab) USING p_id,p_workspace;
END;

