DECLARE s sessions;actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
 acting uuid:=nullif(current_setting('app.v2_assistant_id',true),'')::uuid;
 live_floor text;invocation_floor text:=nullif(current_setting('app.agent_clearance',true),'');
BEGIN
 -- Recording privacy admission precedes body selection.
 IF NOT session_recording_read_allowed(i) THEN RETURN NULL;END IF;
 -- There is no application data grant for a raw native session. A canonical
 -- application-session port must be integrated before that lane is available.
 IF actor IS NULL OR nullif(current_setting('app.application_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.public_share_root',true),'') IS NOT NULL
  OR nullif(current_setting('app.agent_workspace_id',true),'') IS NOT NULL AND current_setting('app.agent_workspace_id',true)::uuid<>w
  OR nullif(current_setting('app.agent_actor_id',true),'') IS NOT NULL AND current_setting('app.agent_actor_id',true)::uuid<>actor
  OR acting IS NOT NULL AND (NOT EXISTS(SELECT 1 FROM assistants a WHERE a.workspace_id=w AND a.id=acting)
    OR assistant_placement_visible(actor,acting) IS NOT TRUE) THEN RETURN NULL;END IF;
 SELECT * INTO s FROM sessions WHERE workspace_id=w AND id=i FOR SHARE;
 IF NOT FOUND OR NOT coalesce(session_personal_audience(s) OR session_workspace_audience(s),false)
  OR session_project_audience(s,false) IS NOT TRUE THEN RETURN NULL;END IF;
 -- Personal sessions inherit a current, persisted assistant/member ceiling.
 -- Shared/legacy unclassified rows remain held. The GUC can only narrow the
 -- real ceiling; it never supplies authority or a missing canonical label.
 live_floor:=s.effective_clearance;
 IF live_floor IS NULL AND s.visibility='personal' THEN
  SELECT CASE WHEN sensitivity_rank(a.clearance)<=sensitivity_rank(wm.clearance) THEN a.clearance ELSE wm.clearance END
   INTO live_floor FROM assistants a JOIN workspace_members wm ON wm.workspace_id=a.workspace_id
   WHERE a.workspace_id=w AND a.id=coalesce(acting,s.assistant_id) AND wm.user_id=actor;
  IF live_floor NOT IN('public','internal','confidential') OR live_floor IS NULL THEN RETURN NULL;END IF;
  IF invocation_floor IS NOT NULL THEN
   IF invocation_floor NOT IN('public','internal','confidential') THEN RETURN NULL;END IF;
   IF sensitivity_rank(invocation_floor)<sensitivity_rank(live_floor) THEN live_floor:=invocation_floor;END IF;
  END IF;
 END IF;
 IF live_floor IS NULL OR s.context_compartments IS NULL THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('workspaceId',w,'userId',CASE WHEN s.visibility='personal' THEN s.user_id ELSE NULL END,
  'assistantId',NULL,'sensitivity',live_floor,'compartments',s.context_compartments,
  'projectIds',CASE WHEN s.context_project_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(s.context_project_id) END,
  'assistant',s.assistant_id,'createdBy',s.user_id);
END

DECLARE root jsonb;actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
 child_kinds text[];child_ids uuid[];child_versions text[];eligible boolean;position integer;admitted jsonb;dependency record;
 seen jsonb:='[]';current_source jsonb;chat_nodes jsonb;chat_proof jsonb;
BEGIN
 IF EXISTS(SELECT 1 FROM session_context_scope_revisions r WHERE r.workspace_id=w AND r.id=i AND r.parent_kind IN('turn_frame','session_title'))
  AND actor IS NOT NULL AND nullif(current_setting('app.application_id',true),'') IS NULL
  AND nullif(current_setting('app.public_share_root',true),'') IS NULL
  AND NOT EXISTS(SELECT 1 FROM pg_roles login JOIN pg_class owned ON owned.oid='public.session_messages'::regclass
   WHERE login.rolname=session_user AND(login.rolsuper OR login.rolbypassrls OR pg_has_role(login.oid,owned.relowner,'USAGE'))) THEN
  chat_proof:=capture_conversation_evidence(w,jsonb_build_array(jsonb_build_object('kind','session_context_revision','id',i,'version','1')));
  IF chat_proof IS NOT NULL THEN RETURN (chat_proof->>'admitted'='true') IS TRUE;END IF;
 END IF;
 -- Recording privacy admission precedes body selection.
 IF NOT recording_source_read_allowed(w,'session_context_revision',i) THEN RETURN false;END IF;
 root:=read_entity_derivation_source(w,'session_context_revision',i);
 IF root IS NULL OR root->>'held' IS DISTINCT FROM 'false' THEN RETURN false;END IF;
 IF actor IS NOT NULL AND EXISTS(SELECT 1 FROM workspace_members m WHERE m.workspace_id=w AND m.user_id=actor)
  AND nullif(current_setting('app.application_id',true),'') IS NULL
  AND nullif(current_setting('app.public_share_root',true),'') IS NULL
  AND NOT EXISTS(SELECT 1 FROM pg_roles login JOIN pg_class owned ON owned.oid='public.session_messages'::regclass WHERE login.rolname=session_user
    AND(login.rolsuper OR login.rolbypassrls OR pg_has_role(login.oid,owned.relowner,'USAGE'))) THEN

 SELECT array_agg(s.source_kind ORDER BY s.source_kind,s.source_id,s.source_version),
  array_agg(s.source_id ORDER BY s.source_kind,s.source_id,s.source_version),
  array_agg(s.source_version ORDER BY s.source_kind,s.source_id,s.source_version),
  count(*) BETWEEN 1 AND 100 AND bool_and(s.source_kind='application_field')
   AND bool_or(s.source_kind='application_field' AND EXISTS(SELECT 1 FROM application_field_resources f WHERE f.workspace_id=w AND f.id=s.source_id
    AND f.origin='{"kind":"native","moduleKey":"native"}' AND f.type_key='memory' AND f.selection='history'))
 INTO child_kinds,child_ids,child_versions,eligible
 FROM session_context_scope_revisions r JOIN scope_derivations d ON d.workspace_id=r.workspace_id AND d.resource_kind='session_context_revision'
  AND d.resource_id=r.id AND d.resource_version='1' AND d.user_id IS NOT DISTINCT FROM r.user_id AND d.assistant_id IS NOT DISTINCT FROM r.assistant_id
  AND d.sensitivity=r.sensitivity AND d.compartments=r.compartments AND d.project_ids=r.project_ids
 JOIN scope_derivation_sources s ON s.workspace_id=d.workspace_id AND s.derivation_id=d.id
 WHERE r.workspace_id=w AND r.id=i AND r.parent_kind='session_title' AND r.parent_id=r.session_id AND r.scope_version=1;
 IF eligible IS TRUE AND EXISTS(SELECT 1 FROM application_scope_lineage(w,child_kinds,child_ids,child_versions) n WHERE n.kind='session_context_revision') THEN eligible:=false;END IF;

  IF eligible IS TRUE THEN
   IF root->>'version' IS DISTINCT FROM '1' OR application_reader_envelope_visible(w,root) IS NOT TRUE THEN RETURN false;END IF;
   FOR position IN 1..cardinality(child_ids) LOOP
    admitted:=read_admitted_application_field_snapshot(w,child_ids[position],child_versions[position]);
    IF admitted IS NULL OR admitted->>'held' IS DISTINCT FROM 'false' OR admitted->>'version' IS DISTINCT FROM child_versions[position] THEN RETURN false;END IF;
   END LOOP;
   FOR dependency IN SELECT * FROM read_native_session_field_dependencies(w,child_kinds,child_ids,child_versions) LOOP
    admitted:=read_admitted_application_field_snapshot(w,(dependency.source->>'resourceId')::uuid,dependency.node_version);
    IF admitted IS NULL OR admitted->>'held' IS DISTINCT FROM 'false' OR admitted->>'version' IS DISTINCT FROM dependency.node_version THEN RETURN false;END IF;
    seen:=seen||jsonb_build_array(jsonb_build_array(dependency.source->>'resourceId',dependency.node_version));
   END LOOP;
   IF jsonb_array_length(seen)=0 THEN RETURN false;END IF;
   FOR position IN 1..cardinality(child_ids) LOOP
    IF NOT seen @> jsonb_build_array(jsonb_build_array(child_ids[position]::text,child_versions[position])) THEN RETURN false;END IF;
   END LOOP;
   FOR dependency IN SELECT * FROM read_external_source_dependencies(w,child_kinds,child_ids,child_versions) LOOP
    current_source:=external_source_snapshot(w,(dependency.source->>'resourceId')::uuid);
    IF dependency.source IS NULL OR dependency.source->>'workspaceId' IS DISTINCT FROM w::text
     OR dependency.source->>'version' IS DISTINCT FROM dependency.node_version
     OR current_source IS NULL OR current_source->>'held' IS DISTINCT FROM 'false'
     OR current_source->>'version' IS DISTINCT FROM dependency.node_version
     OR application_reader_envelope_visible(w,dependency.source) IS NOT TRUE
     OR application_reader_envelope_visible(w,current_source) IS NOT TRUE THEN RETURN false;END IF;
   END LOOP;
   RETURN true;
  END IF;
 END IF;
 -- Keep the separate historical-purpose branch above. Ordinary current
 -- Memory domains can use the existing complete cohort proof, never a label
 -- or an envelope supplied by the caller. Its explicit denial stays denied.
 IF actor IS NOT NULL AND EXISTS(SELECT 1 FROM workspace_members member WHERE member.workspace_id=w AND member.user_id=actor)
  AND nullif(current_setting('app.application_id',true),'') IS NULL
  AND nullif(current_setting('app.public_share_root',true),'') IS NULL
  AND NOT EXISTS(SELECT 1 FROM pg_roles login JOIN pg_class owned ON owned.oid='public.session_messages'::regclass
   WHERE login.rolname=session_user AND(login.rolsuper OR login.rolbypassrls OR pg_has_role(login.oid,owned.relowner,'USAGE'))) THEN
  SELECT coalesce(jsonb_agg(to_jsonb(node)),'[]') INTO chat_nodes
   FROM application_scope_lineage(w,ARRAY['session_context_revision'],ARRAY[i],ARRAY['1']) node;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(chat_nodes) node
   JOIN application_field_resources resource ON resource.workspace_id=w AND resource.id=(node->>'id')::uuid
   WHERE node->>'kind'='application_field' AND resource.origin='{"kind":"native","moduleKey":"native"}'::jsonb
    AND resource.type_key='memory' AND resource.selection='query_domain')
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(chat_nodes) node
    JOIN application_field_resources resource ON resource.workspace_id=w AND resource.id=(node->>'id')::uuid
    WHERE node->>'kind'='application_field' AND resource.type_key='memory'
     AND(resource.selection<>'query_domain' OR resource.selected_version IS NOT NULL)) THEN
   chat_proof:=read_native_session_cohort_evidence(w,ARRAY['session_context_revision'],ARRAY[i],ARRAY['1'],true);
   IF chat_proof IS NOT NULL THEN RETURN (chat_proof->>'admitted'='true') IS TRUE;END IF;
  END IF;
 END IF;
 RETURN root IS NOT NULL AND root->>'held'='false'
  AND application_canonical_ancestry_allowed(w,'session_context_revision',i,'1') IS TRUE;
END

DECLARE root jsonb;parent jsonb;r session_context_scope_revisions;
BEGIN
 -- Recording privacy admission precedes body selection.
 IF NOT recording_source_read_allowed(w,'session_context_revision',i) THEN RETURN NULL;END IF;
 root:=session_context_revision_snapshot(w,i);
 SELECT * INTO r FROM session_context_scope_revisions WHERE workspace_id=w AND id=i;
 parent:=session_context_parent_snapshot(w,r.session_id);
 IF r.parent_kind='message_annotation' AND
  read_admitted_native_scope_snapshot(w,'session_message',r.parent_id)->>'held' IS DISTINCT FROM 'false'
 THEN RETURN '{"held":true}';END IF;
 IF root->>'held' IS DISTINCT FROM 'false' OR parent IS NULL OR workflow_evidence_envelope_visible(w,parent) IS NOT TRUE
  OR agent_visibility_allows(w,r.user_id,r.assistant_id) IS NOT TRUE
  OR workflow_evidence_envelope_visible(w,root) IS NOT TRUE THEN RETURN '{"held":true}';END IF;
 RETURN root;
END

DECLARE output scope_derivations; dependency record; source jsonb; current jsonb; has_fields boolean:=false;
 history boolean:=false;projection jsonb;label jsonb;fields jsonb;

BEGIN
 IF (SELECT encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') FROM pg_proc p WHERE p.oid='native_turn_validate_event(jsonb)'::regprocedure)='

' AND native_turn_validate_event(to_jsonb(NEW)) THEN RETURN NULL;END IF;

  has_fields:=false;history:=false;projection:=NULL;label:=NULL;fields:=NULL;source:=NULL;current:=NULL;
 SELECT * INTO output FROM scope_derivations WHERE workspace_id=NEW.workspace_id AND id=NEW.derivation_id;
 IF NOT FOUND THEN RETURN NULL; END IF;
 -- Direct history keeps its purpose only for canonical titles or stored messages.
 history:=NEW.source_kind='application_field' AND output.resource_version='1'
  AND ((output.resource_kind='session_context_revision'
   AND EXISTS(SELECT 1 FROM session_context_scope_revisions r WHERE r.workspace_id=output.workspace_id AND r.id=output.resource_id
    AND r.parent_kind='session_title' AND r.parent_id=r.session_id AND r.user_id IS NOT DISTINCT FROM output.user_id
    AND r.assistant_id IS NOT DISTINCT FROM output.assistant_id AND r.sensitivity=output.sensitivity
    AND r.compartments=output.compartments AND r.project_ids=output.project_ids))
   OR (output.resource_kind='session_message'
    AND EXISTS(SELECT 1 FROM session_messages m JOIN sessions s ON s.id=m.session_id AND s.workspace_id=m.workspace_id
     WHERE m.workspace_id=output.workspace_id AND m.id=output.resource_id AND m.scope_version=1 AND m.scope_held IS FALSE
      AND m.user_id IS NOT DISTINCT FROM output.user_id AND m.assistant_id IS NOT DISTINCT FROM output.assistant_id
      AND m.sensitivity=output.sensitivity AND m.compartments=output.compartments AND m.project_ids=output.project_ids)))
  AND EXISTS(SELECT 1 FROM application_field_resources f WHERE f.workspace_id=NEW.workspace_id AND f.id=NEW.source_id
   AND f.origin='{"kind":"native","moduleKey":"native"}' AND f.type_key='memory' AND f.selection='history');
 IF history THEN
  current:=read_admitted_application_field_snapshot(NEW.workspace_id,NEW.source_id,NEW.source_version);
  IF current IS NULL OR current->>'held' IS DISTINCT FROM 'false' OR current->>'version' IS DISTINCT FROM NEW.source_version THEN
   RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
  projection:=read_native_attended_memory_evidence(NEW.workspace_id,ARRAY[NEW.source_kind],ARRAY[NEW.source_id],ARRAY[NEW.source_version]);
  IF projection IS NULL OR projection->>'purpose' IS DISTINCT FROM 'memory_history' OR projection->>'available' IS DISTINCT FROM 'true'
   OR projection->'root' IS DISTINCT FROM (current-ARRAY['held','validTo','retractedAt'])
   OR jsonb_typeof(projection->'scopes') IS DISTINCT FROM 'array' OR jsonb_array_length(projection->'scopes') NOT BETWEEN 1 AND 8192 THEN
   RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
  FOR label IN SELECT value FROM jsonb_array_elements(projection->'scopes') LOOP
   IF workflow_evidence_envelope_visible(NEW.workspace_id,label) IS NOT TRUE
    OR label->>'userId' IS NOT NULL AND label->>'userId' IS DISTINCT FROM output.user_id::text
     AND (output.user_id IS NOT NULL OR label->>'userId' IS DISTINCT FROM nullif(current_setting('app.current_user_id',true),''))
    OR sensitivity_rank(label->>'sensitivity')>sensitivity_rank(output.sensitivity)
    OR NOT to_jsonb(output.compartments)@>(label->'compartments') OR NOT to_jsonb(output.project_ids)@>(label->'projectIds') THEN
    RAISE EXCEPTION 'scope_visibility_incompatible' USING ERRCODE='22023';END IF;
  END LOOP;
  SELECT coalesce(jsonb_agg(jsonb_build_object('node_version',d.node_version,'source',d.source)),'[]') INTO fields
   FROM read_native_session_field_dependencies(NEW.workspace_id,ARRAY[NEW.source_kind],ARRAY[NEW.source_id],ARRAY[NEW.source_version]) d;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(fields) d WHERE d->>'node_version'=NEW.source_version
    AND d#>>'{source,resourceId}'=NEW.source_id::text) THEN
   RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 ELSE
  SELECT coalesce(jsonb_agg(jsonb_build_object('node_version',d.node_version,'source',d.source)),'[]') INTO fields
   FROM read_application_field_dependencies(NEW.workspace_id,ARRAY[NEW.source_kind],ARRAY[NEW.source_id],ARRAY[NEW.source_version]) d;
 END IF;
 FOR dependency IN SELECT d->>'node_version' AS node_version,d->'source' AS source FROM jsonb_array_elements(fields) d LOOP
  has_fields:=true;source:=dependency.source;
  current:=application_current_field_snapshot(NEW.workspace_id,(source->>'resourceId')::uuid);
  IF current IS NULL OR current->>'held' IS DISTINCT FROM 'false' OR current->>'version' IS DISTINCT FROM dependency.node_version THEN
   RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501'; END IF;
  IF NOT EXISTS(SELECT 1 FROM scope_derivation_sources s WHERE s.workspace_id=NEW.workspace_id AND s.derivation_id=NEW.derivation_id
   AND s.source_kind='application_field' AND s.source_id=(source->>'resourceId')::uuid AND s.source_version=dependency.node_version) THEN
   RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023'; END IF;
  IF source->>'userId' IS NOT NULL AND source->>'userId' IS DISTINCT FROM output.user_id::text
   AND source->>'userId' IS DISTINCT FROM nullif(current_setting('app.current_user_id',true),'')
   OR sensitivity_rank(source->>'sensitivity')>sensitivity_rank(output.sensitivity)
   OR NOT to_jsonb(output.compartments)@>(source->'compartments') OR NOT to_jsonb(output.project_ids)@>(source->'projectIds') THEN
   RAISE EXCEPTION 'scope_visibility_incompatible' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF NOT has_fields THEN RETURN NULL; END IF;
 FOR dependency IN SELECT * FROM read_external_source_dependencies(NEW.workspace_id,ARRAY[NEW.source_kind],ARRAY[NEW.source_id],ARRAY[NEW.source_version]) LOOP
  IF dependency.source IS NULL OR dependency.source->>'version' IS DISTINCT FROM dependency.node_version
   OR NOT external_source_retention_allowed(NEW.workspace_id,(dependency.source->>'resourceId')::uuid,dependency.node_version)
   OR NOT EXISTS(SELECT 1 FROM scope_derivation_sources s WHERE s.workspace_id=NEW.workspace_id AND s.derivation_id=NEW.derivation_id
    AND s.source_kind='external_source' AND s.source_id=(dependency.source->>'resourceId')::uuid AND s.source_version=dependency.node_version) THEN
   RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023'; END IF;
  source:=dependency.source;
  IF sensitivity_rank(source->>'sensitivity')>sensitivity_rank(output.sensitivity)
   OR NOT to_jsonb(output.compartments)@>(source->'compartments') OR NOT to_jsonb(output.project_ids)@>(source->'projectIds') THEN
   RAISE EXCEPTION 'scope_visibility_incompatible' USING ERRCODE='22023'; END IF;
 END LOOP;
 RETURN NULL;


 RETURN NULL;
END

DECLARE source jsonb; admitted jsonb; parent jsonb; output scope_derivations;
BEGIN
 IF (SELECT encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') FROM pg_proc p WHERE p.oid='native_turn_page_event(jsonb)'::regprocedure)='

'
 THEN
  IF native_turn_page_event(to_jsonb(NEW)) THEN RETURN NULL;END IF;
 END IF;
 SELECT * INTO output FROM scope_derivations WHERE workspace_id=NEW.workspace_id AND id=NEW.derivation_id;
 IF NOT FOUND THEN RETURN NULL; END IF;
 FOR source IN SELECT value FROM jsonb_array_elements(read_resource_page_dependencies(NEW.workspace_id,NEW.source_kind,NEW.source_id,NEW.source_version)) LOOP
  IF output.resource_kind='session_message' THEN
   IF NOT EXISTS(SELECT 1 FROM session_messages m JOIN sessions session ON session.id=m.session_id
    JOIN comment_threads ct ON ct.session_id=session.id AND ct.workspace_id=output.workspace_id
    JOIN workflow_page_event_receipts receipt ON receipt.workspace_id=output.workspace_id AND receipt.page_id=ct.page_id
    LEFT JOIN workflow_page_event_observations observation ON observation.workspace_id=output.workspace_id
     AND observation.id=(source->>'resourceId')::uuid
    WHERE m.workspace_id=output.workspace_id AND m.id=output.resource_id
     AND session.visibility='workspace' AND session.anchor_kind='doc_thread'
     AND receipt.revision=CASE WHEN source->>'resourceKind' LIKE 'page_live_%' THEN observation.receipt_id ELSE (source->>'resourceId')::uuid END)
   THEN RAISE EXCEPTION 'page_derivation_output_not_integrated';END IF;
  ELSIF output.resource_kind NOT IN('workspace_file','file_segment','session_context_revision') THEN RAISE EXCEPTION 'page_derivation_output_not_integrated';END IF;
  admitted:=read_page_derivation_source(NEW.workspace_id,source->>'resourceKind',(source->>'resourceId')::uuid);
  IF admitted IS NULL OR admitted->>'version' IS DISTINCT FROM source->>'version' THEN RAISE EXCEPTION 'scope_source_changed'; END IF;
  FOR parent IN SELECT value FROM jsonb_array_elements(jsonb_build_array(source)||(admitted->'requiredSources')) LOOP
   IF NOT EXISTS(SELECT 1 FROM scope_derivation_sources p WHERE p.workspace_id=NEW.workspace_id AND p.derivation_id=NEW.derivation_id
    AND p.source_kind=parent->>'resourceKind' AND p.source_id=(parent->>'resourceId')::uuid AND p.source_version=parent->>'version') THEN RAISE EXCEPTION 'scope_evidence_missing'; END IF;
   IF (parent->>'userId' IS NOT NULL AND parent->>'userId' IS DISTINCT FROM output.user_id::text AND output.resource_kind<>'session_message')
    OR (parent->>'assistantId' IS NOT NULL AND parent->>'assistantId' IS DISTINCT FROM output.assistant_id::text)
    OR sensitivity_rank(parent->>'sensitivity')>sensitivity_rank(output.sensitivity)
    OR NOT(to_jsonb(output.compartments) @> (parent->'compartments'))
    OR NOT(to_jsonb(output.project_ids) @> (parent->'projectIds')) THEN RAISE EXCEPTION 'scope_visibility_incompatible'; END IF;
  END LOOP;
 END LOOP;
 RETURN NULL;
END

DECLARE source_row jsonb; expected_id uuid; expected_version text; expected_kind text;
BEGIN
  IF TG_TABLE_NAME='scope_derivation_sources' THEN
    expected_id=NEW.source_id;expected_version=NEW.source_version;expected_kind=NEW.source_kind;
  ELSE expected_id=NEW.resource_id;expected_version=NEW.resource_version;expected_kind=NEW.resource_kind;
  END IF;
  source_row:=NULL;
  IF TG_TABLE_NAME='scope_derivations' AND expected_kind='session_context_revision' AND EXISTS(
   SELECT 1 FROM native_turn_publication_work op WHERE op.transaction_id=txid_current() AND op.workspace_id=NEW.workspace_id AND op.frame_id=expected_id)
  THEN
   IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
   SELECT jsonb_build_object('workspaceId',r.workspace_id,'resourceKind','session_context_revision','resourceId',r.id,'version',r.scope_version::text,
    'userId',r.user_id,'assistantId',r.assistant_id,'sensitivity',r.sensitivity,'compartments',r.compartments,'projectIds',r.project_ids)
   INTO source_row FROM session_context_scope_revisions r JOIN native_turn_frames f ON f.workspace_id=r.workspace_id AND f.id=r.id AND f.session_id=r.session_id
   WHERE r.workspace_id=NEW.workspace_id AND r.id=expected_id AND r.parent_kind='turn_frame' AND r.parent_id=r.id AND NOT r.scope_held;
  END IF;

  IF TG_RELID='public.scope_derivation_sources'::regclass AND TG_OP='INSERT' AND expected_kind='application_field' THEN
   IF (SELECT encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') FROM pg_proc p WHERE p.oid='native_turn_field_reference(uuid,uuid,uuid,text)'::regprocedure)='

' THEN
    source_row:=native_turn_field_reference(NEW.workspace_id,NEW.derivation_id,expected_id,expected_version);
   END IF;
  END IF;
  IF source_row IS NULL THEN
    source_row=CASE WHEN TG_TABLE_NAME='scope_resource_states'
      THEN read_scope_review_source(NEW.workspace_id,expected_kind,expected_id)
      ELSE read_scope_source(NEW.workspace_id,expected_kind,expected_id) END;
  END IF;
  IF source_row IS NULL OR source_row->>'version' IS DISTINCT FROM expected_version THEN RAISE EXCEPTION 'scope_source_changed'; END IF;
  IF TG_TABLE_NAME='scope_derivations' THEN
    IF NEW.user_id IS DISTINCT FROM (source_row->>'userId')::uuid
      OR NEW.assistant_id IS DISTINCT FROM (source_row->>'assistantId')::uuid
      OR NEW.sensitivity<>(source_row->>'sensitivity')
      OR NOT(to_jsonb(NEW.compartments) @> (source_row->'compartments') AND to_jsonb(NEW.compartments) <@ (source_row->'compartments'))
      OR NOT(to_jsonb(NEW.project_ids) @> (source_row->'projectIds') AND to_jsonb(NEW.project_ids) <@ (source_row->'projectIds')) THEN
      RAISE EXCEPTION 'scope_envelope_mismatch';
    END IF;
  END IF;
  RETURN NEW;
END;

DECLARE revision_id uuid;r session_context_scope_revisions;parent_row jsonb;payload jsonb;s sessions;
BEGIN
 IF TG_TABLE_NAME='session_context_scope_revisions' AND to_jsonb(NEW)->>'parent_kind'='turn_frame' THEN
  IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
  IF native_turn_frame_pair(NEW.workspace_id,NEW.id) IS NOT TRUE THEN
   IF EXISTS(SELECT 1 FROM native_turn_publication_work WHERE transaction_id=txid_current() AND frame_id=NEW.id AND workspace_id=NEW.workspace_id)
   THEN RAISE EXCEPTION 'native_turn_construction_unavailable' USING ERRCODE='PNT02';END IF;
   RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';
  END IF;
  RETURN NULL;
 END IF;
 IF TG_TABLE_NAME='session_context_scope_revisions' AND to_jsonb(NEW)->>'parent_kind'='session_title' THEN RETURN NULL;END IF;
 IF TG_TABLE_NAME='session_context_scope_revisions' THEN revision_id:=(to_jsonb(NEW)->>'id')::uuid;
 ELSIF TG_TABLE_NAME='session_message_annotation_heads' THEN
  SELECT to_jsonb(h) INTO parent_row FROM session_message_annotation_heads h WHERE h.message_id=NEW.message_id;
  IF parent_row IS NULL THEN RETURN NULL;END IF;
  revision_id:=(parent_row->>'scope_revision_id')::uuid;
 ELSIF TG_TABLE_NAME='sessions' THEN
  IF TG_OP='UPDATE' AND NEW.compact_summary IS NOT DISTINCT FROM OLD.compact_summary
   AND NEW.compact_boundary_sequence IS NOT DISTINCT FROM OLD.compact_boundary_sequence
   AND NEW.compact_scope_revision_id IS NOT DISTINCT FROM OLD.compact_scope_revision_id THEN RETURN NULL;END IF;
  SELECT to_jsonb(p) INTO parent_row FROM sessions p WHERE p.id=(to_jsonb(NEW)->>'id')::uuid;
  IF parent_row IS NULL THEN RETURN NULL;END IF;
  revision_id:=(parent_row->>'compact_scope_revision_id')::uuid;
  IF revision_id IS NULL AND parent_row->>'compact_summary' IS NULL THEN RETURN NULL;END IF;
 ELSE
  IF TG_TABLE_NAME='session_state' THEN
   SELECT to_jsonb(p) INTO parent_row FROM session_state p WHERE p.id=(to_jsonb(NEW)->>'id')::uuid;
   IF TG_OP='UPDATE' AND NEW.scope_revision_id IS NOT DISTINCT FROM OLD.scope_revision_id AND
    (to_jsonb(NEW)-ARRAY['updated_at'])=(to_jsonb(OLD)-ARRAY['updated_at']) THEN RETURN NULL;END IF;
  ELSE
   SELECT to_jsonb(p) INTO parent_row FROM episodic_memories p WHERE p.id=(to_jsonb(NEW)->>'id')::uuid;
   IF TG_OP='UPDATE' AND NEW.scope_revision_id IS NOT DISTINCT FROM OLD.scope_revision_id AND
    (to_jsonb(NEW)-ARRAY['last_accessed_at','access_count','survival_count'])=(to_jsonb(OLD)-ARRAY['last_accessed_at','access_count','survival_count']) THEN RETURN NULL;END IF;
  END IF;
  IF parent_row IS NULL THEN RETURN NULL;END IF;
  revision_id:=(parent_row->>'scope_revision_id')::uuid;
 END IF;
 IF revision_id IS NULL THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 SELECT * INTO r FROM session_context_scope_revisions WHERE id=revision_id;
 IF TG_TABLE_NAME='session_message_annotation_heads' AND
   (r.parent_kind IS DISTINCT FROM 'message_annotation' OR r.parent_id::text IS DISTINCT FROM parent_row->>'message_id'
    OR r.session_id::text IS DISTINCT FROM parent_row->>'session_id' OR r.workspace_id::text IS DISTINCT FROM parent_row->>'workspace_id')
  OR TG_TABLE_NAME='sessions' AND (r.parent_kind IS DISTINCT FROM 'compact_summary' OR r.parent_id IS DISTINCT FROM (to_jsonb(NEW)->>'id')::uuid OR r.session_id IS DISTINCT FROM (to_jsonb(NEW)->>'id')::uuid)
  OR TG_TABLE_NAME='session_state' AND (r.parent_kind IS DISTINCT FROM 'session_state' OR r.parent_id IS DISTINCT FROM (to_jsonb(NEW)->>'id')::uuid OR r.session_id::text IS DISTINCT FROM parent_row->>'session_id')
  OR TG_TABLE_NAME='episodic_memories' AND (r.parent_kind IS DISTINCT FROM 'episodic_memory' OR r.parent_id IS DISTINCT FROM (to_jsonb(NEW)->>'id')::uuid OR r.session_id::text IS DISTINCT FROM parent_row->>'session_id') THEN
  RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='22023';END IF;
 SELECT * INTO s FROM sessions WHERE id=r.session_id AND workspace_id=r.workspace_id;
 SELECT c.content INTO payload FROM session_context_revision_contents c WHERE c.workspace_id=r.workspace_id AND c.revision_id=r.id;
 IF r.id IS NULL OR s.id IS NULL OR r.scope_held OR payload IS NULL
  OR NOT EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=r.workspace_id AND d.resource_kind='session_context_revision'
    AND d.resource_id=r.id AND d.resource_version='1' AND d.user_id IS NOT DISTINCT FROM r.user_id AND d.assistant_id IS NOT DISTINCT FROM r.assistant_id
    AND d.sensitivity=r.sensitivity AND d.compartments=r.compartments AND d.project_ids=r.project_ids
    AND EXISTS(SELECT 1 FROM scope_derivation_sources edge WHERE edge.workspace_id=d.workspace_id AND edge.derivation_id=d.id))
  OR r.parent_kind<>'message_annotation' AND
   (r.user_id IS DISTINCT FROM (CASE WHEN s.visibility='personal' THEN s.user_id ELSE NULL END) OR r.assistant_id IS NOT NULL)
  OR r.parent_kind='message_annotation' AND s.visibility='personal' AND r.user_id IS DISTINCT FROM s.user_id
 THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 IF r.parent_kind='message_annotation' THEN
  SELECT to_jsonb(h) INTO parent_row FROM session_message_annotation_heads h
   JOIN session_messages m ON m.id=h.message_id AND m.session_id=h.session_id AND m.workspace_id=h.workspace_id
   WHERE h.message_id=r.parent_id AND h.session_id=r.session_id AND h.workspace_id=r.workspace_id;
  IF parent_row IS NULL OR parent_row->>'scope_revision_id' IS DISTINCT FROM r.id::text THEN
   RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='22023';END IF;
 ELSIF r.parent_kind='compact_summary' THEN
  IF r.parent_id<>r.session_id OR s.compact_scope_revision_id IS DISTINCT FROM r.id OR s.compact_summary IS NOT NULL
   OR s.compact_boundary_sequence IS DISTINCT FROM (payload->>'boundarySequence')::int THEN
   RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='22023';END IF;
 ELSIF r.parent_kind='session_state' THEN
  SELECT to_jsonb(p) INTO parent_row FROM session_state p WHERE p.id=r.parent_id AND p.session_id=r.session_id;
  IF parent_row IS NULL OR parent_row->>'scope_revision_id' IS DISTINCT FROM r.id::text OR parent_row->>'key' IS DISTINCT FROM r.parent_id::text
   OR parent_row->>'summary' IS DISTINCT FROM '' OR parent_row->>'detail' IS NOT NULL OR parent_row->>'status' IS DISTINCT FROM 'open'
   OR parent_row->>'source' IS DISTINCT FROM 'tool' OR parent_row->>'resolved_at' IS NOT NULL THEN
   RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='22023';END IF;
 ELSE
  SELECT to_jsonb(p) INTO parent_row FROM episodic_memories p WHERE p.id=r.parent_id AND p.session_id=r.session_id;
  IF parent_row IS NULL OR parent_row->>'scope_revision_id' IS DISTINCT FROM r.id::text OR parent_row->>'topic_label' IS DISTINCT FROM ''
   OR parent_row->>'summary' IS DISTINCT FROM '' OR parent_row->'message_span' IS DISTINCT FROM '{}'::jsonb OR parent_row->>'entity_refs' IS NOT NULL THEN
   RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='22023';END IF;
 END IF;
 RETURN NULL;
END

DECLARE s jsonb; parent jsonb;
BEGIN
 IF NEW.source_kind<>'workflow_run' THEN RETURN NULL; END IF;
 s:=read_scope_source(NEW.workspace_id,NEW.source_kind,NEW.source_id);
 IF s->>'version' IS DISTINCT FROM NEW.source_version THEN RAISE EXCEPTION 'scope_source_changed'; END IF;
 FOR parent IN SELECT value FROM jsonb_array_elements(s->'requiredSources') LOOP
  IF NOT EXISTS(SELECT 1 FROM scope_derivation_sources p WHERE p.workspace_id=NEW.workspace_id AND p.derivation_id=NEW.derivation_id
   AND p.source_kind=parent->>'resourceKind' AND p.source_id=(parent->>'resourceId')::uuid AND p.source_version=parent->>'version')
   THEN RAISE EXCEPTION 'scope_evidence_missing'; END IF;
 END LOOP;
 RETURN NULL;
END

DECLARE actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
 teams text[]; projects uuid[]; grants jsonb; v2 boolean;
BEGIN
 IF actor IS NULL OR jsonb_typeof(s)<>'object' OR s->>'workspaceId' IS DISTINCT FROM w::text
  OR NOT(s ?& ARRAY['sensitivity','compartments','projectIds','userId','assistantId'])
  OR coalesce(s->>'sensitivity','') NOT IN('public','internal','confidential')
  OR jsonb_typeof(s->'compartments') IS DISTINCT FROM 'array'
  OR jsonb_typeof(s->'projectIds') IS DISTINCT FROM 'array'
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->'compartments') x WHERE jsonb_typeof(x)<>'string')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->'projectIds') x WHERE jsonb_typeof(x)<>'string')
  OR (s->>'userId' IS NOT NULL AND s->>'userId'<>actor::text)
  OR (s->>'userId' IS NOT NULL AND current_setting('app.agent_shared_audience',true)='true')
  OR NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=actor)
  THEN RETURN false; END IF;
 teams:=ARRAY(SELECT jsonb_array_elements_text(s->'compartments'));
 projects:=ARRAY(SELECT jsonb_array_elements_text(s->'projectIds')::uuid);
 IF agent_visibility_allows(w,(s->>'userId')::uuid,(s->>'assistantId')::uuid) IS NOT TRUE
  OR agent_scope_grant_allows('app.agent_project_ids',projects::text[]) IS NOT TRUE THEN RETURN false; END IF;
 SELECT department_read_v2 INTO v2 FROM workspaces WHERE id=w;
 IF v2 THEN
  grants:=department_read_grants();
  IF NOT(grants ? w::text) OR department_row_allows(grants,w,s->>'sensitivity',teams,(s->>'userId')::uuid) IS NOT TRUE THEN RETURN false; END IF;
  IF nullif(current_setting('app.agent_clearance',true),'') IS NOT NULL
    AND current_setting('app.v2_active',true) IS DISTINCT FROM 'true'
    AND nullif(current_setting('app.v2_assistant_id',true),'') IS NULL THEN
   IF cardinality(teams)>0 AND nullif(current_setting('app.agent_compartments',true),'') IS NULL THEN RETURN false; END IF;
   IF agent_read_scope_allows(s->>'sensitivity',teams,projects) IS NOT TRUE THEN RETURN false; END IF;
  END IF;
 ELSE
  IF member_operation_scope_allows(w,s->>'sensitivity',teams,false) IS NOT TRUE
    OR agent_read_scope_allows(s->>'sensitivity',teams,projects) IS NOT TRUE THEN RETURN false; END IF;
 END IF;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value THEN RETURN false;
END

