DECLARE resource application_field_resources;observation application_field_observations;proof jsonb;
BEGIN
 RETURN QUERY SELECT e.kind,e.id,e.version FROM knowledge_version_source_edges(w,k,i,v) e;
 IF k IS DISTINCT FROM 'application_field' THEN RETURN;END IF;
 SELECT f.* INTO resource FROM application_field_resources f WHERE f.workspace_id=w AND f.id=i
  AND f.origin='{"kind":"native","moduleKey":"native"}' AND f.type_key='memory' AND f.selection='history';
 IF NOT FOUND THEN RETURN;END IF;
 SELECT o.* INTO observation FROM application_field_observations o WHERE o.workspace_id=w AND o.resource_id=i AND o.version=v;
 IF NOT FOUND OR observation.source_kind IS DISTINCT FROM 'memory' OR observation.source_id IS DISTINCT FROM resource.resource_id
  OR observation.record_version IS DISTINCT FROM resource.selected_version OR observation.source_version IS DISTINCT FROM resource.selected_version THEN
  RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 proof:=application_memory_history_status(w,resource.resource_id,resource.selected_version);
 IF proof IS NULL THEN RAISE EXCEPTION 'scope_ancestry_unavailable' USING ERRCODE='22023';END IF;
 RETURN QUERY SELECT value->>'kind',(value->>'id')::uuid,value->>'version' FROM jsonb_array_elements(proof->'roots');
END

DECLARE publication knowledge_entry_revision_publications;
BEGIN
 IF k IS DISTINCT FROM 'knowledge_entry' AND k IS DISTINCT FROM 'knowledge_entry_revision' THEN
  RETURN QUERY SELECT e.kind,e.id,e.version FROM application_scope_source_edges_before_knowledge_versions(w,k,i,v) e;RETURN;
 END IF;
 IF k='knowledge_entry' THEN
  SELECT * INTO publication FROM knowledge_entry_revision_publications p WHERE p.workspace_id=w AND p.entry_id=i AND p.entry_version=v;
  IF FOUND THEN RETURN QUERY SELECT 'knowledge_entry_revision'::text,publication.revision_id,'1'::text;RETURN;END IF;
  IF EXISTS(SELECT 1 FROM knowledge_entry_revision_publications p JOIN knowledge_entry_scope_revisions r ON r.workspace_id=p.workspace_id AND r.id=p.revision_id
   WHERE p.workspace_id=w AND p.entry_id=i AND r.revision_kind='body') THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 END IF;
 RETURN QUERY SELECT e.kind,e.id,e.version FROM application_scope_source_edges_before_knowledge_versions(w,k,i,v) e
  UNION SELECT c.source_kind,c.source_id,c.source_version FROM knowledge_entry_revision_capture_inputs c
   WHERE k='knowledge_entry_revision' AND c.workspace_id=w AND c.revision_id=i AND v='1'
  UNION SELECT 'knowledge_entry'::text,p.entry_id,p.entry_version FROM knowledge_entry_revision_publications p
   WHERE k='knowledge_entry_revision' AND p.workspace_id=w AND p.revision_id=i AND v='1';
END

BEGIN
 IF k='workflow_run' THEN
  RETURN QUERY WITH RECURSIVE consumers(id) AS (
   SELECT i UNION SELECT s.run_id FROM workflow_run_copy_sources s JOIN consumers c ON c.id=s.source_run_id WHERE s.workspace_id=w
  ) SELECT id FROM consumers;
 ELSE RETURN QUERY SELECT * FROM scope_source_ancestors_before_workflow_run(w,k,i); END IF;
END

